void color(int i, int j) {
	int coll = 0;
	while(!canbe[i][j][coll]) {
		coll++;
	}
	col[i][j] = coll;
	int curri = i+d;
	int currj = j;
	int endi = i;
	int endj = j+d;
	for(;currj <= endj; curri--, currj++) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
		}
	}
	curri = i;
	currj = j+d;
	endi = i-d;
	endj = j;
	for(;curri >= endi; curri--, currj--) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
		}
	}
	curri = i-d;
	currj = j;
	endi = i;
	endj = j-d;
	for(;curri <= endi; curri++, currj--) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
		}
	}
	curri = i;
	currj = j-d;
	endi = i+d;
	endj = j;
	for(;curri <= endi; curri++, currj++) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
		}
	}
}

