bool Check(int x, int y) {
	if(x < 1 || x > n) return 0;
	if(y < 1 || y > m) return 0;
	return 1;
}

void Dfs(int p) {
	for(int i = 1; i <= 4; i++)
		if(!vis[p][i]) {col[p] = i; break;}
	if(col[p] == 0) printf("******\n");
	int nx, ny;
	if(p % m == 0) nx = p / m, ny = m;
	else nx = p / m + 1, ny = p % m;
	for(int k = 0; k <= d; k++) {
		int x = nx + k, y = ny + (d - k);
		if(Check(x, y)) vis[(x - 1) * m + y][col[p]] = 1;
		x = nx + k; y = ny - (d - k);
		if(Check(x, y)) vis[(x - 1) * m + y][col[p]] = 1;
		x = nx - k; y = ny - (d - k);
		if(Check(x, y)) vis[(x - 1) * m + y][col[p]] = 1;
		x = nx - k; y = ny + (d - k);
		if(Check(x, y)) vis[(x - 1) * m + y][col[p]] = 1;
	}
	for(int k = 0; k <= d; k++) {
		int x = nx + k, y = ny + (d - k);
		if(Check(x, y) && !col[(x - 1) * m + y]) Dfs((x - 1) * m + y);
		x = nx + k; y = ny - (d - k);
		if(Check(x, y) && !col[(x - 1) * m + y]) Dfs((x - 1) * m + y);
		x = nx - k; y = ny - (d - k);
		if(Check(x, y) && !col[(x - 1) * m + y]) Dfs((x - 1) * m + y);
		x = nx - k; y = ny + (d - k);
		if(Check(x, y) && !col[(x - 1) * m + y]) Dfs((x - 1) * m + y);
	}
}

