set<PIP> st;
int vis[MAXN][MAXN];

int ADD(int x, int y, int col, int cnt){
	st.erase(PIP(g[x][y][4], PII(x, y)));
	if (g[x][y][col] == 0){
		g[x][y][4]--;
	}
	g[x][y][col] += cnt;
	if (g[x][y][col] == 0){
		g[x][y][4]++;
	}
	st.insert(PIP(g[x][y][4], PII(x, y)));
	if (g[x][y][4] == 0) return 0;
	else return 1;
}

int d;

int dfs(int dep){
	if (dep == n * m + 1){
		for(int i = 1; i <= n; i++){
			for (int j = 1; j <= m; j++)
				putchar(CH[f[i][j]]);
			puts("");
		}
		return 1;
	}
	PIP p = *(st.begin());
	st.erase(st.begin());
	int x = p.second.first;
	int y = p.second.second;
	//cout << dep << ' ' << x << ' ' << y << endl;
	vis[x][y] = 1;
	for (int i = 0; i < 4; i++)
		if ((g[x][y][i] == 0)){
			f[x][y] = i;
			int flag = 1;
			for (int dx = -d; dx <= d; dx++){
				int dy = d - abs(dx);
				if (1 <= x + dx && x + dx <= n && y + dy >= 1 && y + dy <= m && !vis[x + dx][y + dy]){
					flag &= ADD(x + dx, y + dy, i, 1);
				}
				if (dy != 0) {
					dy = -dy;
					if (1 <= x + dx && x + dx <= n && y + dy >= 1 && y + dy <= m && !vis[x + dx][y + dy]){
						flag &= ADD(x + dx, y + dy, i, 1);
					}
				}
			}
			if (flag) if (dfs(dep + 1)) return 1;
			for (int dx = -d; dx <= d; dx++){
				int dy = d - abs(dx);
				if (1 <= x + dx && x + dx <= n && y + dy >= 1 && y + dy <= m && !vis[x + dx][y + dy]){
					ADD(x + dx, y + dy, i, -1);
				}
				if (dy != 0) {
					dy = -dy;
					if (1 <= x + dx && x + dx <= n && y + dy >= 1 && y + dy <= m && !vis[x + dx][y + dy]){
						ADD(x + dx, y + dy, i, -1);
					}
				}
			}
		}
	vis[x][y] = 0;
	st.insert(p);
	return 0;
}

