//	cout << "Case #" << casi << ": ";
	scanf("%d%d%d", &n, &m, &d);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++){
			st.insert(PIP(4, PII(i, j)));
			g[i][j][4] = 4;
			vis[i][j] = 0;
		}
	dfs(1);
}

