void bfs(int si,int sj){
  col[si][sj] = 1;
  queue< pair<int,int> > line;
  line.push({si,sj});
  while(!line.empty()) {
  	int topx = line.front().first;
  	int topy = line.front().second;
  	line.pop();

  	int currColor = col[topx][topy];

  	for(auto point : atD[topx][topy]) {

  		if(col[point.first][point.second]) continue;

  		int cant[5] = {0};

  		cant[currColor] = 1;

  		for(auto jpoint : atD[point.first][point.second])
  			cant[col[jpoint.first][jpoint.second]] = 1;

  		for(int i=1;i<5;i++)
  			if(!cant[i]){
  				//cerr<<point.first<<" "<<point.second<<" "<<i<<endl;
  				col[point.first][point.second] = i;
  				break;
  			}

  		line.push({point.first,point.second});
  	}
  }
}

