void solve1(int h, int w, int d){
  d--;

  for(int k=0;k<2;k++){

    for(int i=-2000 + d * k;i<=2000;i+=d * 2){
      int x = i;
      for(int y=-2000+k;y<=2000+k;y += d+1){
        for(int a=-(d/2);a<=d/2;a++)
          for(int b=-(d/2)+abs(a);b<=(d/2)-abs(a);b++)
            if(0 <= x+b && x+b < SIZE && 0 <= y+a && y+a < SIZE)
              ans[y+a][x+b] = k;
        x += d-1;
      }

    }

  }

  for(int k=0;k<2;k++){

    for(int i=-2000 + (d-1) + d * k;i<=2000 + (d-1);i+=d * 2){
      int x = i;
      for(int y=-2000 - (d-2)+k;y<=2000 - (d-2)+k;y += d+1){
