          for(int b=-(d/2)+abs(a);b<=(d/2)-abs(a);b++)
            if(0 <= x+b && x+b < SIZE && 0 <= y+a && y+a < SIZE)
              ans[y+a][x+b] = k + 2;
        x += d-1;
      }

    }

  }

}


