const char col[] = "RYGB";

int H, W, d;
vector <int> V[MAXN * MAXN];
int C[MAXN * MAXN];
int Used[MAXN];

int DFS(int i)
{
	for (C[i] = 0; C[i] < 4; C[i] ++)
	{
		int ok = 1;
		for (auto j: V[i])
		{
			if (C[j] == C[i])
			{
				ok = 0;
				break;
			}
		}
		if (! ok) continue;
		int full = 1;
		for (auto j: V[i])
			if (C[j] == -1)
				full = 0;
		if (full) return 1;
		for (auto j: V[i])
			if (C[j] == -1)
				if (DFS(j))
					return 1;
	}
	C[i] = -1;
	return 0;
}

void Work()
{
	scanf("%d%d%d", &H, &W, &d);
	for (int i = 0; i < H; i ++)
		for (int j = 0; j < W; j ++)
			for (int ii = 0; ii < H; ii ++)
			{
				int dd = d - abs(i - ii);
				if (dd < 0) continue;
				int jj;
				jj = j - dd;
				if (0 <= jj && jj < W)
					V[i * W + j].push_back(ii * W + jj);
				jj = j + dd;
				if (0 <= jj && jj < W)
					V[i * W + j].push_back(ii * W + jj);
			}

	memset(C, -1, sizeof(C));
	for (int i = 0; i < H; i ++)
		for (int j = 0; j < W; j ++)
			if (C[i * W + j] == -1)
				DFS(i * W + j);

	for (int i = 0; i < H; i ++)
	{
		for (int j = 0; j < W; j ++)
			printf("%c", col[C[i * W + j]]);
		printf("\n");
	}
}

int main()
{
	Work();
	return 0;
}

