int body(int &argc, char **argv) {
    using namespace debug;
    auto H = read<i32>();
    auto W = read<i32>();
    auto d = read<i64>();

    V<char> cs = { 'R', 'Y', 'G', 'B'};

    V<V<i32>> ans(H, V<i32>(W, -1));

    REP (i, H) {
        REP (j, W) {
            if (ans[i][j] >= 0) {
                continue ;
            }

            V<bool> use(4, true);
            // 左上
            REP (k, d + 1) {
                auto i2 = i - k;
                auto j2 = j - (d - k);
                if (i2 < 0 || j2 < 0) {
                    continue ;
                }
                if (ans[i2][j2] >= 0) {
                    use[ans[i2][j2]] = false;
                }
            }
            // 右上
            REP (k, d + 1) {
                auto i2 = i - k;
                auto j2 = j + (d - k);
                if (i2 < 0 || j2 >= W) {
                    continue ;
                }
                if (ans[i2][j2] >= 0) {
                    use[ans[i2][j2]] = false;
                }
            }
            // 左下
            REP (k, d + 1) {
                auto i2 = i + k;
                auto j2 = j - (d - k);
                if (i2 >= H || j2 < 0) {
                    continue ;
                }
                if (ans[i2][j2] >= 0) {
                    use[ans[i2][j2]] = false;
                }
            }
            // 右下
            REP (k, d + 1) {
                auto i2 = i + k;
                auto j2 = j + (d - k);
                if (i2 >= H || j2 >= W) {
                    continue ;
                }
                if (ans[i2][j2] >= 0) {
                    use[ans[i2][j2]] = false;
                }
            }

            i32 x = -1;
            REP (k, 4) {
                if (use[k]) {
                    x = k;
                    break;
                }
            }
            if (x != -1) {
                ans[i][j] = x;

                if (j + 2 * d < W) {
                    ans[i][j + 2 * d] = x;
                }
                if (i + 2 * d < H) {
                    ans[i + 2 * d][j] = x;
                }
            }
        }
    }

    REP (i, H) {
        REP (j, W) {
            cout << cs.at(ans[i][j]);
        }
        cout << endl;
    }

    return 0;
}

