void pri (int x, int y)
{
    for (int i = x; i < x + d; i ++)
    {
        for (int j = y; j < y + d; j ++)
        {
            if ((i <= n) && (j <= m))
            {
                w[i][j] = 0;
            }
        }
    }
    for (int i = x; i < x + d; i ++)
    {
        for (int j = y + d; j < y + d2; j ++)
        {
            if ((i <= n) && (j <= m))
            {
                w[i][j] = 1;
            }
        }
    }
    for (int i = x + d; i < x + d2; i ++)
    {
        for (int j = y; j < y + d; j ++)
        {
            if ((i <= n) && (j <= m))
            {
                w[i][j] = 2;
            }
        }
    }
    for (int i = x + d; i < x + d2; i ++)
    {
        for (int j = y + d; j < y + d2; j ++)
        {
            if ((i <= n) && (j <= m))
            {
                w[i][j] = 3;
            }
        }
    }
}

int main ()
{
    scanf ("%d%d%d", &n, &m, &d);
