int h,w,d;	
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {-1, 0, 1, 0};
char ans[500][500];
int num = 0;
bool solve(int px, int py){
	if(px*w+py>=h*w) return true;
	bool rflag,gflag,bflag,yflag;
	rflag = gflag = bflag = yflag = true;
	//全箇所調べる
	for(int i = 0; i <= d; i++){
		int nx = px + i;
		int ny = py + (d - i);
		if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
		if(ans[nx][ny] == 'x') continue;
		if(ans[nx][ny] == 'R'){rflag = false; continue;}
		if(ans[nx][ny] == 'G'){gflag = false; continue;}
		if(ans[nx][ny] == 'B'){bflag = false; continue;}
		if(ans[nx][ny] == 'Y'){yflag = false; continue;}
	}
	for(int i = 0; i <= d; i++){
		int nx = px - i;
		int ny = py + (d - i);
		if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
		if(ans[nx][ny] == 'x') continue;
		if(ans[nx][ny] == 'R'){rflag = false; continue;}
		if(ans[nx][ny] == 'G'){gflag = false; continue;}
		if(ans[nx][ny] == 'B'){bflag = false; continue;}
		if(ans[nx][ny] == 'Y'){yflag = false; continue;}
	}
	for(int i = 0; i <= d; i++){
		int nx = px + i;
		int ny = py - (d - i);
		if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
		if(ans[nx][ny] == 'x') continue;
		if(ans[nx][ny] == 'R'){rflag = false; continue;}
		if(ans[nx][ny] == 'G'){gflag = false; continue;}
		if(ans[nx][ny] == 'B'){bflag = false; continue;}
		if(ans[nx][ny] == 'Y'){yflag = false; continue;}
	}
	for(int i = 0; i <= d; i++){
		int nx = px - i;
		int ny = py - (d - i);
		if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
		if(ans[nx][ny] == 'x') continue;
		if(ans[nx][ny] == 'R'){rflag = false; continue;}
		if(ans[nx][ny] == 'G'){gflag = false; continue;}
		if(ans[nx][ny] == 'B'){bflag = false; continue;}
		if(ans[nx][ny] == 'Y'){yflag = false; continue;}
	}
	int ppx = (px * w + py + 1) / w;
	int ppy = (px * w + py + 1) % w;
	// cout << ppx << " " << ppy << endl;	
	if(rflag){
		ans[px][py] ='R';
		if(solve(ppx,ppy)) return true;
	}
	if(gflag){
		ans[px][py] ='G';
		if(solve(ppx,ppy)) return true;
	}
	if(bflag){
		ans[px][py] ='B';
		if(solve(ppx,ppy)) return true;
	}
	if(yflag){
		ans[px][py] ='Y';
		if(solve(ppx,ppy)) return true;
	}
	return false;
}
int main(){
	cin >> h >> w >> d;
	REP(i,h) REP(j,w) ans[i][j] = 'x';
	solve(0,0);
	REP(i,h){
		REP(j,w){
			cout << ans[i][j];
		}
		cout << endl;
	}

}

