using namespace std;
using VS = vector<string>;

void fill_block(int row, int col, char color, int d, VS &board) {
	for (int i = row + 1; i < row + d - 2; i++) {
		for (int j = col; j < col + 4; j++) {
			if (row < board.size() && col < board[0].size()) {
				board[i][j] = color;
			}
		}
	}
	board[row][col + 1] = color;
	board[row][col + 2] = color;
	board[row + d - 2][col + 1] = color;
	board[row + d - 2][col + 2] = color;
}

void fill_line(int row, int col, char col1, char col2, int d, VS &board) {
	int color = col2;
	for (int i = col; i < board[i].size() - 4; i += 4) {
		color = color == col1 ? col2 : col1;
		fill_block(row, i, color, d, board);
	}
}

vector<string> make_board(int h, int w, int d) {
	VS board(h + d + 10, string(w + 10, '-'));
	int type = -1;
	char c1, c2;
	int idx;

	for (int i = 0; i <= h; i += d - 2) {
		type = (type + 1) % 4;
		switch (type) {
			case 0: c1 = 'R'; c2 = 'G'; idx = 0; break;
			case 1: c1 = 'B'; c2 = 'Y'; idx = 2; break;
			case 2: c1 = 'G'; c2 = 'R'; idx = 0; break;
			case 3: c1 = 'Y'; c2 = 'B'; idx = 2; break;
		}

		fill_line(i, idx, c1, c2, d, board);
	}

	return board;
}


int main() {
	int h, w, d;
	cin >> h >> w >> d;

	if (d % 2 == 1) {
		vector<string> board(h, string(w, '-'));
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				board[i][j] = (i + j) % 2 == 0 ? 'R' : 'G';
			}
		}

		for (auto s : board) {
			cout << s << endl;
		}
		return 0;
	}

	auto board = make_board(h, w, d);
	for (int i = 1; i <= h; i++) {
		cout << board[i].substr(2, w) << endl;
	}
	// for (auto s : board) {
	// 	cout << s << endl;
	// }

	return 0;
}

