// YYBBBGGRRRRBBYYYYGGRRRRBBYYYYGGRRRRBBYYYYGGRRRRBBYYYYGGRRRRBBYYYYGGRRRRBBGGGGGGR
// YBBBBBRRRRRRYYYYYYRRRRRRYYYYYYRRRRRRYYYYYYRRRRRRYYYYYYRRRRRRYYYYYYRRRRRRYYGGGGRR
// RBBBBBYRRRRGGYYYYBBRRRRGGYYYYBBRRRRGGYYYYBBRRRRGGYYYYBBRRRRGGYYYYBBRRRRYYYYGGRRR

vector<vector<char> > solve(int h, int w, int d) {
    w = max(2 * h, w);
    auto f = vectors(h, w, char());
    if (d % 2 == 1) {
        repeat (y, h) repeat (x, w) {
            f[y][x] = (y + x) % 4 + 1;
        }
    } else {
        int k1 = d;
        int k2 = 0;
        int k3 = d;
        int k4 = 0;
        int dir = + 1;
        repeat (y, h) {
            string s = dir > 0 ?
                string(k1, '\x01') + string(k2, '\x02') + string(k3, '\x03') + string(k4, '\x04') :
                string(k2, '\x02') + string(k1, '\x01') + string(k4, '\x04') + string(k3, '\x03') ;
            repeat (x, w) {
                f[y][x] = s[((- y + x) % (2 * d) + 2 * d) % (2 * d)];
            }
            if (k1 - dir * 2 < 0 or k2 + dir * 2 < 0) dir *= -1;
            k1 -= dir * 2;
            k2 += dir * 2;
            k3 -= dir * 2;
            k4 += dir * 2;
        }
    }
    return f;
}

int main() {
    // input
    int h, w, d; scanf("%d%d%d", &h, &w, &d);

    // solve
    auto f = solve(h, w, d);

    // check
    repeat (y, h) {
        repeat (x, w) {
            if (not f[y][x]) continue;
            repeat (ny, h) {
                repeat (nx, w) {
                    if (abs(ny - y) + abs(nx - x) == d) {
                        if (f[ny][nx] == f[y][x]) {
                            fprintf(stderr, "conf %d %d and %d %d with %d\n", y, x, ny, nx, f[y][x]);
                        }
                    }
                }
            }
        }
    }

    // output
    repeat (y, h) {
        repeat (x, w) {
            printf("%c", ".RYGB"[f[y][x]]);
        }
        printf("\n");
    }
    return 0;
}

