		return (x.first + (x.second.first * P2 + x.second.second) % MM * P3) % MM;
	}
};

unordered_set<PIP, piphash> st;
int vis[MAXN][MAXN];

int ADD(int x, int y, int col, int cnt){
	st.erase(PIP(g[x][y][4], PII(x, y)));
	if (g[x][y][col] == 0){
		g[x][y][4]--;
	}
	g[x][y][col] += cnt;
	if (g[x][y][col] == 0){
		g[x][y][4]++;
	}
	st.insert(PIP(g[x][y][4], PII(x, y)));
	if (g[x][y][4] == 0) return 0;
	else return 1;
}

