ll h, w, d;

void dfs(int x, int y) {
	used[x][y] = 1;
	set<ll> s;

	for (int j = 0; j < w; j++) {
		ll dist = abs(x - j);
		if (dist > d) continue;

		ll need = (d - dist);
		ll y1 = y - need, y2 = y + need;
		if (y1 >= 0) {
			s.insert(col[j][y1]);
		}
		if (y2 < h) {
			s.insert(col[j][y2]);
		}
	}

	for (int j = 1; j <= 4; j++) {
		if (s.find(j) == s.end()) {
			col[x][y] = j;
			break;
		}
	}

	for (int j = 0; j < w; j++) {
		ll dist = abs(x - j);
		if (dist > d) continue;

		ll need = (d - dist);
		ll y1 = y - need, y2 = y + need;
		if (y1 >= 0) {
			if (!used[j][y1]) dfs(j, y1);
		}
		if (y2 < h) {
			if (!used[j][y2]) dfs(j, y2);
		}
	}


}

void sol() {
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) used[i][j] = 0;
	}

	if (d % 2 == 1) {
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if ((i + j) % 2) {
					grid[i][j] = 'R';
				}
				else {
					grid[i][j] = 'G';
				}
			}
		}
	}
	else {
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				col[i][j] = -1;
			}
		}

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (!used[i][j]) {
					dfs(i, j);
				}
				if (col[i][j] == 1) {
					grid[i][j] = 'R';
				}
				else if (col[i][j] == 2) {
					grid[i][j] = 'G';
				}
				else if (col[i][j] == 3) {
					grid[i][j] = 'B';
				}
				else {
					grid[i][j] = 'Y';
				}
			}
		}
	}
}

bool check() {
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			for (int i2 = 0; i2 < h; i2++) {
				for (int j2 = 0; j2 < w; j2++) {
					if (abs(i - i2) + abs(j - j2) == d && grid[i][j] == grid[i2][j2]) {
						return false;
					}
				}
			}
		}
	}

	return true;
}

