void fill_triangle(int cx, int cy, int dr, char cr)
{
    for (int i = cx - d / 2 + 1; i < cx + d / 2; i++)
    {
        int R = d / 2 - abs(cx - i);
        for (int j = 0; j < R; j++)
        {
            if (i >= 0 && i < h && cy + dr * j >= 0 && cy + dr * j < w)
                ans[i][cy + dr * j] = cr;
        }
