int H, W, D;
string s[500];
void ki() {
	REP(i, 0, H) {
		REP(j, 0, W) {
			if (i % 2 == j % 2) {
				s[i][j] = 'R';
			} else {
				s[i][j] = 'Y';
			}
		}
	}
}
void kigu() {
	REP(i, 0, H) {
		REP(j, 0, W) {
			s[i][j] = "RYGB"[(i % 4 + ((j / 2) % 2) * 2) % 4];
		}
	}
}
void gu() {
	REP(i, 0, H) {
		REP(j, 0, W) {
			bool b = i / D % 2 == j / D % 2;
			int p = b ? i % D : (D - 1 - i % D);
			int q = j % D;
			int r = 4;
			if (p <= q && p < D - q - 1)r = 0;
			if (p > q && p <= D - q - 1)r = 1;
			if (p < q && p >= D - q - 1)r = 2;
			if (p >= q && p > D - q - 1)r = 3;
			s[i][j] = b ? "RYGB."[r] : "RGYB."[r];
		}
	}
}

int main() {
	cin >> H >> W >> D;
	REP(i, 0, H) {
		s[i].resize(W);
	}
	if (D % 2 == 1) {
		ki();
	} else {
		if (D % 4 == 2) {
			kigu();
		} else {
			gu();
		}
	}


	REP(i, 0, H) {
		cout << s[i] << endl;
	}
	return 0;
}

