    void run(){
        char c[4] = {'R','Y','G','B'};
        int dx[4] = {-1,-1,1,1};
        int dy[4] = {-1,1,-1,1};

        vector<vector<int> > ret(H,vector<int>(W,-1));
        queue<pair<int ,int> > q;
        REP(i,D){
            q.push(make_pair(0,i));
