        while(!q.empty()){
            const pair<int,int> p = q.front();
            vector<bool> b(4,false);
            q.pop();
            REP(i,4){
                REP(j,D+1){
                    int xx = p.first + j * dx[i];
                    int yy = p.second + (D-j) * dy[i];
