                        if(ret[xx][yy] == -1){ q.push(make_pair(xx,yy)); ret[xx][yy]--;}
                        continue;
                    }
                    b[ret[xx][yy]] = true;
                }
            }
            REP(i,4){
                if(!b[i]){
                    ret[p.first][p.second] = i;
                    break;
                }
            }
            assert(ret[p.first][p.second]!=-1);
        }

        REP(i,H){
            FOR(j,W) cout<<c[ret[i][j]];
            cout<<endl;
        }
    }
};

