#include<bits/stdc++.h>
using namespace std;

int H,W;
int d;
char a[501][501];
int dx[4]={1,1,-1,-1},dy[4]={1,-1,1,-1};

void input(){
    cin >> H >> W >> d;
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            a[x][y]='0';
        }
    }
}

void dfs(int x,int y){
    if(a[x][y]=='0'){
        bool countR=0,countY=0,countG=0,countB=0;
        for(int i=0;i<=d;i++){
            for(int s=0;s<4;s++){
                int nx=x+dx[s]*i;
                int ny=y+dy[s]*(d-i);
                if(a[nx][ny]=='R') countR=1;
                if(a[nx][ny]=='Y') countY=1;
                if(a[nx][ny]=='G') countG=1;
                if(a[nx][ny]=='B') countB=1;
                }
            }
        if(countR==0) a[x][y]='R';
        else if(countY==0) a[x][y]='Y';
        else if(countG==0) a[x][y]='G';
        else if(countB==0) a[x][y]='B';
        for(int i=0;i<=d;i++){
            for(int s=0;s<4;s++){
                int nx=x+dx[s]*i;
                int ny=y+dy[s]*(d-i);
                if(nx>=0&&nx<W&&ny>=0&&ny<H&a[nx][ny]=='0'){
                    dfs(nx,ny);
                }
            }
        }
    }
}

int main(){
    input();
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            dfs(x,y);
        }
    }
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            cout << a[x][y] ;
        }
        cout << "\n";
    }
    return 0;
}

