#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAX_H = 2000;
const int MAX_W = 2000;
int dx[4] = { 1, 0, -1, 0 }, dy[4] = { 0, 1, 0, -1 };

bool In(int x, int y){
	return 0 <= x && x < MAX_W && 0 <= y && y < MAX_H;
}

char b[MAX_H][MAX_W];
int dist[MAX_H][MAX_W];

struct P{
	int x, y;
};

void bfs(int x, int y, char c, int D){
	queue<P> q;
	q.push({ x, y });
	b[y][x] = c;
	dist[y][x] = 0;
	while(q.size()){
		x = q.front().x, y = q.front().y;
		q.pop();
		if(dist[y][x] == D) break;
		for(int k = 0; k < 4; k++){
			int nx = x + dx[k], ny = y + dy[k];
			if(In(nx, ny) && b[ny][nx] == 0 && dist[ny][nx] > dist[y][x] + 1){
				b[ny][nx] = c;
				dist[ny][nx] = dist[y][x] + 1;
				q.push({ nx, ny });
			}
		}
	}
}

