vector<int> getlist(int y, int x){
  vector<int> out;
  for(int i = 0; i<=d;++i){
    int j = d - i;
    int ty = y - i;
    if(ty >=0 && ty < H){
      int tx = x - j;
      if(tx >=0){
	out.push_back(tx + ty*W);
      }
      if(i == 0 || i == d){continue;}
      int tx2 = x + j;
      if(tx2 <= W){
	out.push_back(tx2 + ty*W);
      }
    }
  }
  return out;
}

