  if(d&1) {
    for(int i=0;i<H;++i) {
      for(int j=0;j<W;++j) {
        if( (i+j)&1) {
          ret[i][j]='R';
        } else {
          ret[i][j] = 'Y';
        }
      }
    }
  } else {
    s[1] = 'R';
    s[2] = 'G';
    s[4] = 'B';
    s[8] = 'Y';
    for(int i=0;i<H;++i) {
      for(int j=0;j<W;++j) {
        remBit[i][j] = 15;
      }
    }

    int ny,nx,add;
    for(int i=0;i<H;++i) {
      for(int j=0;j<W;++j) {
        int t = remBit[i][j];

        t = t&(t-1);

        remBit[i][j] -= t;
        t = remBit[i][j];
        for(int st = max(0,i+d-H-1);st<=min(d,W-1-j);++st) {
          ny = i + d-st;
          nx = j + st;
          if(remBit[ny][nx]&t) {
            remBit[ny][nx] ^=t;
          }
        }
        for(int st = max(0,d-i);st<=min(d,W-1-j);++st) {
          ny = i - d+st;
          nx = j + st;
          if(remBit[ny][nx]&t) {
            remBit[ny][nx] ^=t;
          }
        }

        for(int st = max(0,i+d-H-1);st<=min(d,j);++st) {
          ny = i + d-st;
          nx = j - st;
          if(remBit[ny][nx]&t) {
            remBit[ny][nx] ^=t;
          }
        }
        for(int st = max(0,d-i);st<=min(d,j);++st) {
          ny = i - d+st;
          nx = j - st;
          if(remBit[ny][nx]&t) {
            remBit[ny][nx] ^=t;
          }
        }

      }
    }
  }
  for(int i=0;i<H;++i) {
    printf("%s\n", ret[i]);
  }
}

