			can.insert('R'); can.insert('B'); can.insert('G'); can.insert('Y');
			for (int p(0); p <= d; ++p)
			{
				if (i - p > 0 && j - d + p > 0)
					can.erase(ans[i - p][j - d + p]);
				if (i - p > 0 && j + d - p <= m)
					can.erase(ans[i - p][j + d - p]);
			}
			ans[i][j] = gmin(can);
