const int OFFSET=600;
const int SIZE=1800;
vector<vector<int>> f(SIZE,vector<int>(SIZE));
void init(){
    for(int i=0;i<SIZE;i++) fill(f[i].begin(),f[i].end(),-1);
}
int dx[]={1,0,-1,0};
int dy[]={0,1,0,-1};

int d;
int cnt=0;
void dfs1(){
    stack<tuple<int,int,int>> st;
    st.push({0,0,0});
    while(!st.empty()){
        auto tmp=st.top(); st.pop();
        int id=get<0>(tmp),x=get<1>(tmp),y=get<2>(tmp);
        if(x<0 || SIZE<=x || y<0 || SIZE<=y) continue;
        if(f[x][y]==id) continue;
        assert(f[x][y]==-1);
        f[x][y]=id;
        for(int i=0;i<(d+1)/2;i++){
            for(int j=0;j<=d/2-i;j++){
                if(x+i<SIZE && y+j<SIZE) f[x+i][y+j]=id;
                if(x+i<SIZE && 0<=y-j) f[x+i][y-j]=id;
                if(0<=x-i && y+j<SIZE) f[x-i][y+j]=id;
                if(0<=x-i && 0<=y-j) f[x-i][y-j]=id;
            }
        }
        for(int i=0;i<4;i++){
            int toid=(i==3 ? (id+2)%4 : (id+i+1)%4);
            int tox=x+dx[i]*(d/2+1)+dy[i]*(d/2);
            int toy=y+dx[(i+1)%4]*(d/2+1)+dy[(i+1)%4]*(d/2);
            st.push({toid,tox,toy});
        }
    }
}
void dfs0(){
    stack<tuple<int,int,int,bool>> st;
    st.push({0,OFFSET,OFFSET,false});
    while(!st.empty()){
        auto tmp=st.top(); st.pop();
        int id=get<0>(tmp),x=get<1>(tmp),y=get<2>(tmp),rev=get<3>(tmp);
        if(x<0 || SIZE<=x || y<0 || SIZE<=y) continue;
        if(f[x][y]==id) continue;
        assert(f[x][y]==-1);
        f[x][y]=id;
        for(int i=0;i<d/2;i++){
            for(int j=0;j<=(d-1)/2-i;j++){
                if(x+i<SIZE && y+j<SIZE) f[x+i][y+j]=id;
                if(x+i<SIZE && 0<=y-j) f[x+i][y-j]=id;
                if(0<=x-i && y+j<SIZE) f[x-i][y+j]=id;
                if(0<=x-i && 0<=y-j) f[x-i][y-j]=id;
            }
            if(i>0){
                int jp=(d-1)/2-i+1;
                if(rev){
                    if(0<=x-i && y+jp<SIZE) f[x-i][y+jp]=id;
                    if(0<=x-i && 0<=y-jp) f[x-i][y-jp]=id;
                }
                else{
                    if(x+i<SIZE && y+jp<SIZE) f[x+i][y+jp]=id;
                    if(x+i<SIZE && 0<=y-jp) f[x+i][y-jp]=id;
                }

            }
        }

        st.push({(id+2)%4,x+d-1,y,!rev});
        st.push({(id+2)%4,x-(d-1),y,!rev});
        if(rev){
            st.push({(id+1)%4,x+(d-1)/2,y+d/2,false});
        }
        else{
            st.push({(id+1)%4,x-(d-1),y-d/2,false});    
        }
    }
}

