int col[2510][2510];
int dfs(int x, int y) {
    if (col[y][x]) return col[y][x];

    vector<int> cnt(20, 0);
    int xx = x - d, yy = y;
    rep(i, 0, d) {
        if (0 <= xx && xx < W && 0 <= yy && yy < H) cnt[col[yy][xx]]++;
        xx++; yy++;
    }
    rep(i, 0, d + 1) {
        if (0 <= xx && xx < W && 0 <= yy && yy < H) cnt[col[yy][xx]]++;
        xx++; yy--;
    }

    xx = x - d, yy = y;
    rep(i, 0, d) {
        xx++; yy--;
        if (0 <= xx && xx < W && 0 <= yy && yy < H) cnt[col[yy][xx]]++;
    }
    rep(i, 0, d - 1) {
        xx++; yy++;
        if (0 <= xx && xx < W && 0 <= yy && yy < H) cnt[col[yy][xx]]++;

    }

    col[y][x] = 1;
    while (cnt[col[y][x]] != 0) col[y][x]++;
    //assert(col[y][x] <= 4);


    xx = x - d, yy = y;
    rep(i, 0, d) {
        if (0 <= xx && xx < W && 0 <= yy && yy < H) dfs(xx, yy);
        xx++; yy++;
    }
    rep(i, 0, d + 1) {
        if (0 <= xx && xx < W && 0 <= yy && yy < H) dfs(xx, yy);
        xx++; yy--;
    }

    xx = x - d, yy = y;
    rep(i, 0, d) {
        xx++; yy--;
        if (0 <= xx && xx < W && 0 <= yy && yy < H) dfs(xx, yy);
    }
    rep(i, 0, d - 1) {
        xx++; yy++;
        if (0 <= xx && xx < W && 0 <= yy && yy < H) dfs(xx, yy);

    }

    return col[y][x];
}
