void add(int ty, int p, int x, int val) {
	if(p < 0) return;
	if(ty == 0 && p >= n + m - 1) return;
	if(ty == 1 && p >= n + m + n + m - 2) return; 
	if(ty == 1 && p < n + m - 1) return; 
	//printf("%d %d\n", p, x);
	int lim = !ty ? m + m + 1 + m : n + n + 1 + n;
	for(; x <= lim; x += -x & x) a[p][x] += val;
}

int query(int p, int x) {
	int ans = 0;
	for(; x; x -= -x & x) ans += a[p][x];
	return ans;
}

void upd(int x, int y, int co) {
