      if (m[i][j] == 0) {
        for (int k = 0; k < 4; k++)
          if (fourColoring(i, j, colors[k]))
            break;
      }
    }
  }

  for (int i = 0; i < H; i++) {
    cout << m[i][0];
    for (int j = 1; j < W; j++)
      cout << m[i][j];
    cout << '\n';
  }
}

