int Mass[1000][1000];
int H, W, d;
bool Paint(int i, int j){
	if(i < 0 || i >= H || j < 0 || j >= W){
		return false;
	}
	if(Mass[i][j] != 0){
		return false;
	}
	// cout << i << "," << j << endl;

	set<int> st;
	for(int sgnI = -1; sgnI <= 1; sgnI += 2){
		for(int sgnJ = -1; sgnJ <= 1; sgnJ += 2){
			for(int k = 0; k <= d; k++){
				if(st.size() >= 3){
					break;
				}
				int I = i+sgnI*(d-k);
				int J = j+sgnJ*k;
				if(!(I < 0 || I >= H || J < 0 || J >= W) && Mass[I][J] != 0){
					st.insert(Mass[I][J]);
				}
			}
		}
	}
	int colorToPaint = 1;
	for(int color = 1; color <= 4; color++){
		if(st.find(color) != st.end() && st.find((color+1) <= 4 ? color+1 : 1) == st.end()){
			colorToPaint = color+1 <= 4 ? color+1 : 1;
		}
	}
	Mass[i][j] = colorToPaint;

	return true;
}

void BFS(int i, int j){
	if(Mass[i][j] > 0){
		return;
	}

	queue<pair<int,int> > que;
	que.push(make_pair(i, j));

	while(!que.empty()){
		pair<int, int> ij = que.front();
		que.pop();
		if(!Paint(ij.first, ij.second)){
			continue;
		}
		for(int sgnI = -1; sgnI <= 1; sgnI += 2){
			for(int sgnJ = -1; sgnJ <= 1; sgnJ += 2){
				for(int k = 0; k <= d; k++){
					int I = ij.first+sgnI*(d-k);
					int J = ij.second+sgnJ*k;
					if(!(I < 0 || I >= H || J < 0 || J >= W) && Mass[I][J] == 0){
						que.push(make_pair(I, J));
					}
				}
			}
		}
	}
}

int main()
{
	cin >> H >> W >> d;

	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			Mass[i][j] = 0;
		}
	}

	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			BFS(i, j);
		}
	}

	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			if(Mass[i][j] == 1){
				cout << "R";
			}else if(Mass[i][j] == 2){
				cout << "G";
			}else if(Mass[i][j] == 3){
				cout << "B";
			}else if(Mass[i][j] == 4){
				cout << "Y";
			}
		}
		cout << endl;
	}

	return 0;
}

