using namespace std;

struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

set< int > g[500 * 500];
int paint[500 * 500];
int added[500 * 500];
bool v[4][500 * 500];
bool dame[4][500 * 500];


void dfs(int idx, const int color)
{
  if(v[color][idx]) {
    return;
  }
  v[color][idx] = true;

  if(paint[idx] == -1 && !dame[color][idx]) {
    paint[idx] = color;
    for(auto &to : g[idx]) {
      dame[color][to] = true;
    }
  }

  for(auto &to : g[idx]) {
    dfs(to, color);
  }
}

int main()
{
  int H, W, d;

  cin >> H >> W >> d;
  UnionFind uf(H * W);
  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      for(int k = -d; k <= d; k++) {
        const int p = d - abs(k);
        for(int l : {-p, p}) {
          int y = i + k, x = j + l;
          if(y < 0 || x < 0 || y >= H || x >= W) continue;
          g[i * W + j].emplace(y * W + x);
          uf.unite(i * W + j, y * W + x);
        }
      }
    }
  }

  memset(paint, -1, sizeof(paint));

  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      if(paint[i * W + j] == -1) {
        dfs(i * W + j, added[uf.find(i * W + j)]++ % 4);
      }
    }
  }

  string s = "RYGB";
  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      int color = paint[i * W + j];
      cout << s[color];
    }
    cout << endl;
  }
}

