const int MR = 510;

int forbid[MR][MR];

bool done[MR][MR];

char res[MR][MR];

int cnt(int x)
{
	int res = 0;
	while (x)
	{
		res++;
		x &= (x - 1);
	}

	return res;
}

int main()
{
	int H, W, d;
	scanf("%d%d%d", &H, &W, &d);

	vector<PII> S[5];

	REP(i, H)REP(j, W)
		S[0].push_back(MP(i, j));

	vector < char > col = { 'R','G','Y','B' };

	int ile = 0;
	while (ile < H*W)
	{
		PII akt;
		FORD(i, 5, 0)
		{
			bool found = 0;
			while (!S[i].empty())
			{
				akt = S[i].back(); S[i].pop_back();
				if (!done[akt.first][akt.second])
				{
					found = 1;
					break;
				}
			}

			if (found)
				break;
		}

		int x = akt.first, y = akt.second;
		bool ok = 0;
		REP(i, col.size())
		{
