	string aa = "RYGB";

	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (c[i][j] == '.') {
				int r = 0;
				c[i][j] = aa[r];
				r++;
				for (int k = 0; k <= d; k++) {
					if (0 <= i + k && i + k < h && 0 <= j + (d - k) && j + (d - k) < w && c[i + k][j + (d - k)] == '.') {
						c[i + k][j + (d - k)] = aa[r];
						r++;
						r %= 4;
					} 
					if (0 <= i + k && i + k < h && 0 <= j - (d - k) && j - (d - k) < w && c[i + k][j - (d - k)] == '.') {
						c[i + k][j - (d - k)] = aa[r];
						r++;
						r %= 4;
					}
					if (0 <= i - k && i - k < h && 0 <= j + (d - k) && j + (d - k) < w && c[i - k][j + (d - k)] == '.') {
						c[i - k][j + (d - k)] = aa[r];
						r++;
						r %= 4;
					}
					if (0 <= i - k && i - k < h && 0 <= j - (d - k) && j - (d - k) < w && c[i - k][j - (d - k)] == '.') {
						c[i - k][j - (d - k)] = aa[r];
						r++;
						r %= 4;
					}
				}
			}
		}
	}

	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cout << c[i][j];
		}
		cout << endl;
	}

	return 0;
}

