#include <bits/stdc++.h>

#define endl '\n'
#define max_n 2002

using namespace std;

int side;
int co[max_n][max_n];

void dfs(int x, int y, int val) {
	if(x < 0 || y < 0 || x >= 2002 || y >= 2002) return;
	if(co[x][y] != 0) return;
	for(int i=x-side; i<=x+side; i++) {
		for(int j=y-side; j<=y+side; j++) {
			if(i < 0 || j < 0 || i >= 2002 || j >= 2002) continue;
			if(abs(x-i) + abs(y-j) <= side) co[i][j] = val;
		}
	}
	dfs(x + side + side + 1, y + side + side - 1, val);
	dfs(x - side - side - 1, y - side - side + 1, val);
	dfs(x + side + side - 1, y - side - side - 1, val);
	dfs(x - side - side + 1, y - side - side + 1, val);
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	int n, m, d;
	cin >> n >> m >> d;
	side = (d-1) / 2;
	memset(co, 0, sizeof co);
	dfs(1000, 1000, 1);
	dfs(1000+side+1, 1000+side, 2);
	dfs(1000+side, 1000-side-1, 3);
	dfs(1000+side+side+1, 1000-1, 4);
	for(int i=0; i<n; i++) {
		for(int j=0; j<m; j++) {
			if(co[1000+i][1000+j] == 1) {
				cout << 'R';
			}
			else if(co[1000+i][1000+j] == 2) {
				cout << 'G';
			}
			else if(co[1000+i][1000+j] == 3) {
				cout << 'Y';
			}
			else if(co[1000+i][1000+j] == 4) {
				cout << 'B';
			}
		}
		cout << endl;
	}
	return 0;
}

