using namespace std;

#define N 500

char mat[N + 1][N + 1];
int n, m, d;

bool inside(int x, int y){
	return 1 <= x and x <= n and 1 <= y and y <= m;
}

char vertical(char c){
	if (c == 'R'){
		return 'B';
	}

	if (c == 'B'){
		return 'R';
	}

	if (c == 'G'){
		return 'Y';
	}

	if (c == 'Y'){
		return 'G';
	}

	return 0;
}

char horizontal(char c){
	if (c == 'R'){
		return 'G';
	}

	if (c == 'G'){
		return 'R';
	}

	if (c == 'B'){
		return 'Y';
	}

	if (c == 'Y'){
		return 'B';
	}

	return 0;
}

void fill(int x, int y, char c){
	int i, j;

	for (i = x - (d - 1); i <= x + (d - 1); i++){
		for (j = y - (d - 1); j <= y + (d - 1); j++){
			if (inside(i, j) and abs(x - i) + abs(y - j) <= d - 1){
				mat[i][j] = c;
			}
		}
	}
}

void solve(int x, int y, char c){
	if (x <= n and y <= m){
		solve(x + d - 1, y + d, horizontal(c));
	}

	fill(x, y, c);
}

int main(){
	int i, j;
	char c;

	scanf("%d%d%d", &n, &m, &d);

	for (i = n, j = 1, c = 'R'; i >= 1;){
		solve(i, j, c);
		i = i - 2 * d + 1;
		j = j - 1;
		c = horizontal(vertical(c));
	}

	for (; j <= m;){
		solve(i, j, c);
		i = i - 1;
		j = j + 2 * d - 1;
		c = horizontal(vertical(c));
	}

	for (i = 1; i <= n; i++){
		for (j = 1; j <= m; j++){
			printf("%c", mat[i][j]);
		}

		printf("\n");
	}

	return 0;
}

