   void solve() {
      Int n, m, d; scan(n, m, d);
      char cs[] = "RGBY";
      if( d % 4 == 1 or d % 4 == 3 ) {
         for(Int i = 0; i < n; ++i) {
            for(Int k = 0; k < m; ++k) {
               putchar(cs[(i%2)*2+(k%2)]);
            }
            putchar('\n');
         }
         return;
      }
      Int ts[] = {0, 2, 1, 3};
      if( d % 4 == 2 ) {
         for(Int i = 0; i < n; ++i) {
            for(Int k = 0; k < m; ++k) {
               Int first = ts[i%4];
               Int y = i % 2 == 0 ? k/2 : (k+1)/2;
               putchar(cs[(first^(y%2))]);
            }
            putchar('\n');
         }
         return;
      }
      if( d % 4 == 0 ) {
         if( n <= 2 ) {
            for(Int i = 0; i < n; ++i) {
               for(Int k = 0; k < m; ++k) {
                  putchar(cs[i%2*2+k/d%2]);
               }
               putchar('\n');
