         else if( m <= 2 ) {
            for(Int i = 0; i < n; ++i) {
               for(Int k = 0; k < m; ++k) {
                  putchar(cs[k%2*2+i/d%2]);
               }
               putchar('\n');
            }
         }
         return;
      }
      assert(0);
   }
};

