		return 0 <= y && y < h && 0 <= x && x < w;
	};

	for (int phase = 0; phase < 4; ++phase) {
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				if (map[i][j] != phase) {
