						++map[i + dy][j + dx];

					if (dy > 0 && dx >= 0)
						--dy, ++dx;
					else if (dy <= 0 && dx > 0)
						--dy, --dx;
					else if (dy < 0 && dx <= 0)
						++dy, --dx;
					else
						++dy, ++dx;
				}
			}
		}
	};

	for (int i = 0; i < h; ++i) {
		for (int j = 0; j < w; ++j)
			std::cout << "RYGB"[map[i][j]];

