const char* col = "RYGB";

int main()
{
    int h, w, d;
    cin >> h >> w >> d;

    vector<string> bd(h, string(w, '.'));

    if (d % 2 == 1) {
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                bd[y][x] = col[(x + y) % 4];
            }
        }
    } else {
        int bw = d;
        int bh = d - 1;

        for (int y = 0; y < h + 2 * bw; y++) {
            // continue;
            for (int x = 0; x < w + 2 * bw; x++) {
                int dx = x % bw;
                int dy = y % bw;
                int ph = (x / bw % 2) ^ (y / bw % 2);
                if (dy == bw - 1)
                    continue;

                int tx = dx >= bw / 2 ? bw - 1 - dx : dx;
                int ty = dy > bh / 2 ? bh - 1 - dy : dy;

                // if (ph != 0)
                //     continue;

                if (!(tx + ty < bh / 2)) {
                    int cx = x - bw;
                    int cy = y - bw;

                    if (cx >= 0 && cx < w && cy >= 0 && cy < h)
                        bd[cy][cx] = col[ph + 0];
                }
            }
        }

        for (int y = 0; y < h + 2 * bw; y++) {
            for (int x = 0; x < w + 2 * bw; x++) {
                int dx = x % bw;
                int dy = y % bw;
                int ph = (x / bw % 2) ^ (y / bw % 2);
                if (dy == bw - 1)
                    continue;

                int tx = dx >= bw / 2 ? bw - 1 - dx : dx;
                int ty = dy > bh / 2 ? bh - 1 - dy : dy;

                if (!(tx + ty < bh / 2)) {
                    int cx = x + bw / 2 - bw;
                    int cy = y + bw / 2 - bw;

                    if (cx >= 0 && cx < w && cy >= 0 && cy < h)
