int H, W, d;
int board[510][510];
bool pattern[1000][1000];

bool inBoard(int x, int y) {
	return x >= 0 && x < W && y >= 0 && y < H;
}

signed main() {
	cin >> H >> W >> d;

	if (d % 2) {
		rep(y, H) {
			rep(x, W) cout << ((x + y) % 2 ? 'R' : 'Y');
			cout << endl;
		}
		return 0;
	}

	int pH = d - 1;
	int pW = d;
	rep(y, pH) rep(x, pW) pattern[y][x] = true;
	rep(y, pH) {
		int num = abs(pH / 2 - y);
		rep(i, num) {
			pattern[y][i] = false;
			pattern[y][pW - i - 1] = false;
		}
	}

	int cnt = 0;
	for (int ty = 0; ty < H + 2 * d; ty += d / 2) {
		int tx = 0;
		if (cnt % 2) tx -= d / 2;

		int color = cnt % 2 ? 0 : 2;
		color += (cnt / 2) % 2 ? 0 : 1;
		while (tx < W) {
			rep(py, pH) rep(px, pW) {
				if (!inBoard(tx + px, ty + py)) continue;
				if (!pattern[py][px]) continue;
				board[ty + py][tx + px] = color;
			}

			color += color % 2 ? -1 : 1;
			tx += pW;
		}

		cnt++;
	}

	char ch[4] = { 'R', 'Y', 'G', 'B' };
	rep(y, H) {
		rep(x, W) cout << ch[board[y][x]];
		cout << endl;
	}

    return 0;
}

