const int maxn = 500 + 5;
int n, m, d;
int a[maxn][maxn];
int vis[maxn][maxn];

int inside(int u, int v) {
    if (!(u >= 0 && u < n)) return 0;
    if (!(v >= 0 && v < m)) return 0;
    return 1;
}

int getmask(int u, int v) {
    int res = 0;
    FOR(x, 0, d + 1) {
        int y = d - x;
        for (int s1 = -1; s1 <= 1; s1 += 2) {
            for (int s2 = -1; s2 <= 1; s2 += 2) {
                int nu = u + x * s1;
                int nv = v + y * s2;
                if (inside(nu, nv) && vis[nu][nv]) {
                    res |= 1 << a[nu][nv];
                    if (bitcount(res) == 3) {
                        return res;
                    }
                }
            }
        }
    }
    return res;
}

void solve() {
    cin >> n >> m >> d;
    if (d & 1) {
        FOR(i, 0, n) FOR(j, 0, m) a[i][j] = (i + j) & 1;
    }
    else {
        FOR(i, 0, n) FOR(j, 0, m) if (!vis[i][j]) {
            queue<int> que;
            vis[i][j] = 1, que.push(i), que.push(j);
            while (sz(que)) {
                int u = que.front(); que.pop();
                int v = que.front(); que.pop();
                FOR(x, 0, d + 1) {
                    int y = d - x;
                    for (int s1 = -1; s1 <= 1; s1 += 2) {
                        for (int s2 = -1; s2 <= 1; s2 += 2) {
                            int nu = u + x * s1;
                            int nv = v + y * s2;
                            if (inside(nu, nv) && !vis[nu][nv]) {
                                vis[nu][nv] = 1, que.push(nu), que.push(nv);
                                int t = (s1 + 1) / 2 + (s2 + 1);
                                a[nu][nv] = (a[u][v] + t) % 4;
                            }
                        }
                    }
                }
            }
        }
    }
    char color[] = {'R', 'B', 'G', 'Y'};
    FOR(i, 0, n) {
        FOR(j, 0, m) cout << color[a[i][j]];
        cout << "\n";
    }
}

