class Solver {
  public:
    bool solve() {
        int H, W, d; cin >> H >> W >> d;
        vector<vector<int>> G(H, vector<int>(W, 4));
        vector<vector<int>> R(H, vector<int>(W));
        priority_queue<tuple<int, pii>> que;
        que.emplace(0, make_pair(H / 2, W / 2));

        while(true) {
            while(que.size()) {
                int r; pii pos; 
                tie(r, pos) = que.top(); que.pop();
                int x = pos.second; int y = pos.first;
                int c = G[y][x];
                if(c < 4) continue;
                rep(i, 4) if((R[y][x] & (1 << i)) == 0) {
                    c = i;
                    break;
                }
                assert(c < 4);
                G[y][x] = c;
                repeat(dy, -d, d + 1) {
                    vector<int> dxs = {d - abs(dy), -1 * (d - abs(dy))};
                    if(abs(dy) == d) dxs.pop_back();
                    for(int dx : dxs) {
                        int ny = y + dy, nx = x + dx;
                        if(0 <= ny and ny < H and 0 <= nx and nx < W) {
                            assert(G[ny][nx] != c);
                            R[ny][nx] |= (1 << c);
                            int r = __builtin_popcount(R[ny][nx]);
                            que.emplace(r, make_pair(ny, nx));
                        }
                    }
                }
            }
            rep(i, H) rep(j, W) if(G[i][j] == 4) {
                que.emplace(0, make_pair(i, j));
                goto NEXT;
            }
            break;
      NEXT:;
        }
        vector<char> colors = {'R', 'G', 'B', 'Y'};
        rep(i, H) {
            rep(j, W) {
                cout << colors[G[i][j]];
            }
            cout << endl;
        }
        return 0;
    }
};

