void fill(vector<vector<char>> &pat, int d, char c, int i, int j) {
	int dimI = pat.size();
	int dimJ = pat[0].size();
	for(int k = 0; k < d/2; k++) {
		for(int l = k; l < d-k; l++) {
			if(j+l < 0 || j+l >= dimJ) continue;
			if(i+k >= 0 && i+k < dimI) pat[i + k][j + l] = c;
			if(i-k >= 0 && i-k < dimI) pat[i - k][j + l] = c;
		}
	}
}

