	if(d % 2 == 1) {
		for(int i = 0; i < H; i++) {
			for(int j = 0; j < W; j++) {
				int v = (i % 2) ^ (j % 2);
				if(v) {
					cout << 'R';
				} else {
					cout << 'Y';
				}
			}
			cout << endl;
		}
	} else {
		vector<vector<char> > pat(2*d, vector<char>(2*d));
		fill(pat, d, 'R', 0, 0);
		fill(pat, d, 'R', d, d);
		fill(pat, d, 'R', 2*d, 0);
		fill(pat, d, 'Y', d, 0);
		fill(pat, d, 'Y', 0, d);
		fill(pat, d, 'Y', 2*d, d);
		fill(pat, d, 'G', d/2, d/2);
		fill(pat, d, 'G', 3*d/2, -d/2);
		fill(pat, d, 'G', 3*d/2, 3*d/2);
		fill(pat, d, 'B', d/2, -d/2);
		fill(pat, d, 'B', d/2, 3*d/2);
