#include <bits/stdc++.h>
using namespace std;

void solve_odd(int H, int W, int d){
    for (int h = 0; h < H; ++h){
        for (int w = 0; w < W; ++w){
            if ((h + w) & 1){
                cout << 'R';
            }else{
                cout << 'Y';
            }
        }
        cout << endl;
    }
}

void f(int offset, int c, int H, int W, int d, int dd, vector<vector<int>> & A){
    int x = 0;
    int y = 0;
    if (c == 1){
        x = dd;
        y = -dd;
    }else if (c == 2){
        x = d;
        y = 0;
    }else if (c == 3){
        x = dd;
        y = dd;
    }
    x += offset;
    for (int i = 0; i < dd; ++i){
        for (int j = 0; j < dd; ++j){
            int h = i + j + x;
            int w = dd - 1 - i + j + y;
            for (int k = 0; k * d + h < H + 4 * d; ++k){
                for (int m = 0; m * d + w < W + 4 * d; ++m){
                    if ((k + m) & 1) continue;
                    if (h + k * d >= 0 and w + m * d > 0) A[h + k * d][w + m * d] = c;
                }
            }
        }
    }
}

void solve_even(int H, int W, int d){
    int dd = d / 2;
    vector<vector<int>> A(H + 4 * d, vector<int>(W + 4 * d, 0));
    for (int offset = 0; offset <= 1; ++offset){
        for (int c = 0; c < 4; ++c){
            f(offset, c, H, W, d, dd, A);
        }
    }
    string s = "RYGB";
    for (int h = d; h < H + d; ++h){
        for (int w = d; w < W + d; ++w){
            cout << s[A[h][w]];
        }
        cout << endl;
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H, W, d;
    cin >> H >> W >> d;
    if ((d % 2) == 1){
        solve_odd(H, W, d);
    }else{
        solve_even(H, W, d);
    }
    return 0;
}

