int h , w, d;

char color[4] = {'R', 'Y', 'G', 'B'};
int dx[4] = {1, -1, 1, -1};
int dy[4] = {1, -1, -1, 1};
bitset<510> block[4][510];
char ans[510][510];
int reach[510][510];

void paint(int i , int j) {
	vector<int> v;
	for (int k = 0 ; k < 4 ; k++) {
		if (!block[k][i][j])v.push_back(k);
	}
	assert(v.size() > 0);
	int ava = v[0];
	for (int u = 0 ; u < 4 ; u++) {
		for (int aX = 0; aX <= d ; aX++) {
			int aY = d - aX;
			int newX = i + aX * dx[u];
			int newY = j + aY * dy[u];
			if (newX >= 0 && newX < h && newY >= 0 && newY < w) {
				if (abs(newX - i) + abs(newY - j) == d)
					block[ava][newX][newY] = 1;
			}
		}
	}
	ans[i][j] = color[ava];
}
int main() {
	//freopen("input.txt", "r", stdin);
	cin >> h >> w >> d;
	for (int i = 0; i < h; ++i) {
		for (int j = 0 ; j < w ; ++j) {
			for (int u = 0 ; u < 4 ; u++) {
				for (int aX = 0; aX <= d ; aX++) {
					int aY = d - aX;
					int newX = i + aX * dx[u];
					int newY = j + aY * dy[u];
					if (newX >= 0 && newX < h && newY >= 0 && newY < w) {
						if (abs(newX - i) + abs(newY - j) == d)
							reach[newX][newY] = 1;
					}
				}
			}
		}
	}
	vector < pair<int, pair<int, int> > > cells;
	for (int i = 0; i < h; ++i) {
		for (int j = 0 ; j < w ; j++) {
			cells.push_back(make_pair(reach[i][j],make_pair(i,j)));
		}
	}
	sort(cells.begin(),cells.end());
	reverse(cells.begin(),cells.end());
	for (int i = 0; i < cells.size(); ++i){
		paint(cells[i].second.first,cells[i].second.second);
	}
	for (int i = 0; i < h; ++i) {
		for (int j = 0 ; j < w ; j++) {
			printf("%c", ans[i][j]);
		}
		puts("");
	}
	return 0;
}

