	int W = w * 3 + 1000;
	int D = d / 2;
	std::vector<std::vector<char>> ans(H, std::vector<char>(W, ' '));
	if (d % 2 == 1) {
		// R, B
		for (int y = 0; y < H; y += d) {
			for (int x = 0; x < W; x += d) {
				int t = (x + y) / d;
				char c = (t % 2 == 0 ? 'R' : 'B');
				FOR(i, -D, D + 1) {
					int dd = D - (int)std::abs(i);
					FOR(j, -dd, dd + 1) {
						if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
						ans[i + y][j + x] = c;
					}
				}
			}
		}
		// G, Y
		for (int y = D; y < H; y += d) {
			for (int x = D; x < W; x += d) {
				int t = (x - D + y - D) / d;
				char c = (t % 2 == 0 ? 'G' : 'Y');
				ans[y][x] = c;
				FOR(i, -(D - 1), D + 1) {
					int dd = D - (int)std::abs(i);
					if (i <= 0) {
						FOR(j, -(dd - 1), dd + 1) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
					else {
						FOR(j, -dd, dd + 2) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
	}
	else { // d % 2 == 0
	   // R, B
		for (int y = 0; y < H; y += d) {
			for (int x = 0; x < W; x += d + 2) {
				int t = (x + y) / d;
				char c = (t % 2 == 0 ? 'R' : 'B');
				FOR(i, -(D - 1), D + 1) {
					int dd = D - (int)std::abs(i);
					if (i <= 0) {
						FOR(j, -(dd - 1), dd + 1) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
					else {
						FOR(j, -dd, dd + 2) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
		// G, Y
		for (int y = D; y < H; y += d) {
			for (int x = D + 1; x < W; x += d + 2) {
				int t = (x - D + y - D) / d;
				char c = (t % 2 == 0 ? 'G' : 'Y');
				ans[y][x] = c;
				FOR(i, -(D - 1), D + 1) {
					int dd = D - (int)std::abs(i);
					if (i <= 0) {
						FOR(j, -(dd - 1), dd + 1) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
					else {
						FOR(j, -dd, dd + 2) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
	}
	REP(i, h) {
		REP(j, w) {
			OUT(ans[i + 200][j + 200]);
		}BR;
	}
	return 0;
}

