inline void draw(int i, int j, char c){
	if (0 <= i && i < n && 0 <= j && j < m)
		a[i][j] = c;
}

int main(){
	scanf("%d%d%d", &n, &m, &K);
	if (K & 1){
		for (int i = 0; i < n; ++i){
			for (int j = 0; j < m; ++j)
				putchar("RG"[i + j & 1]);
			puts("");
		}
	}
	else{
		char cc[4] = {'R', 'Y', 'G', 'B'};
		int K0 = K >> 1;
		for (int j = -K; j < m + K; j += K){
			for (int i = -K; i < n + K; i += K << 1){
				for (int k = 0; k < K0; ++k){
					for (int l = -k; l <= k; ++l){
						draw(i + k, j - l, cc[0]);
						draw(i + k, j + l, cc[0]);
						draw(i + K - 1 - k, j - l, cc[0]);
						draw(i + K - 1 - k, j + l, cc[0]);

						draw(K + i + k, j - l, cc[1]);
						draw(K + i + k, j + l, cc[1]);
						draw(K + i + K - 1 - k, j - l, cc[1]);
						draw(K + i + K - 1 - k, j + l, cc[1]);

						draw(K0 + i + k, K0 + j - l, cc[2]);
						draw(K0 + i + k, K0 + j + l, cc[2]);
						draw(K0 + i + K - 1 - k, K0 + j - l, cc[2]);
						draw(K0 + i + K - 1 - k, K0 + j + l, cc[2]);

						draw(K + K0 + i + k, K0 + j - l, cc[3]);
						draw(K + K0 + i + k, K0 + j + l, cc[3]);
						draw(K + K0 + i + K - 1 - k, K0 + j - l, cc[3]);
						draw(K + K0 + i + K - 1 - k, K0 + j + l, cc[3]);
					}
				}
			}
			swap(cc[0], cc[1]);
			swap(cc[2], cc[3]);
		}
		for (int i = 0; i < n; ++i){
			for (int j = 0; j < m; ++j)
				putchar(a[i][j] ? a[i][j] : ' ');
			puts("");
		}
//			puts(a[i]);
	}
	return 0;
}

