// complex
typedef complex<double> xy_t;
double dot_product(xy_t a, xy_t b){ return (conj(a) * b).real(); }
double cross_product(xy_t a, xy_t b){ return (conj(a) * b).imag(); }
xy_t projection(xy_t p, xy_t b) {return b * dot_product(p,b) / norm(b);}

// GCD
int gcd(int a, int b) {
  if(b == 0) { return a; }
  return gcd(b, a % b);
}

// Prime
bool is_prime(int n) {
  for(int i = 2; i * i <= n; ++i) {
    if(n % i == 0) { return false; }
  }
  return n != 1;
}
VI divisor(int n) {
  VI res;
  for(int i = 1; i * i <= n; ++i) {
    if(n % i == 0) {
      res.pb(i);
      if(i != n / i) { res.pb(n / i); }
    }
  }
  return res;
}
map<int, int> prime_factor(int n) {
  map<int, int> res;
  for(int i = 2; i * i <= n; ++i) {
    while(n % i == 0) {
      ++res[i];
      n /= i;
    }
  }
  if(n != 1) { res[n] = 1; }
  return res;
}
int sieve(int n) {
  VI prime;
  VB is_prime(n + 1, true);
  is_prime[0] = is_prime[1] = false;
  for(int i = 2; i <= n; ++i) {
    if(is_prime[i]) {
      prime.pb(i);
      for(int j = 2 * i; j <= n; j += i) { is_prime[j] = false; }
    }
  }
  return prime.size();
}

