			for(int j=0;j*d<w;j++) {
				int c = (i%2)^(j%2);
				g[i*d][j*d] = c;
				que.emplace(i*d,j*d,c);
				if(i*d+1<h) {
					g[i*d+1][j*d] = c;
					que.emplace(i*d+1,j*d,c);
				}
			}
		}
