void color(int i, int j) {
	if(colored[i][j]) {
		return;
	}
	int coll = 0;
	while(!canbe[i][j][coll]) {
		coll++;
	}
	col[i][j] = coll;
	int curri = i+d;
	int currj = j;
	int endi = i;
	int endj = j+d;
	vector<pair<int,int>> tocol;
	for(;currj <= endj; curri--, currj++) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
			tocol.push_back(make_pair(curri,currj));
		}
	}
	curri = i;
	currj = j+d;
	endi = i-d;
	endj = j;
	for(;curri >= endi; curri--, currj--) {
		if(curri >= 0 && curri < 501 && currj >= 0 && currj < 501) {
			canbe[curri][currj][coll] = false;
			tocol.push_back(make_pair(curri,currj));
