void solve2() {
    REP (h, H) {
        REP (w, W) {
            cout << COLORS[(w+(h&2))%4];
        }
        cout << "\n";
    }
}

void solveOdd() {
    REP (h, H) {
        REP (w, W) {
            cout << COLORS[(w+h)%2];
        }
        cout << "\n";
    }
}

inline int diff(int h, int w, int ch, int cw) {
    return abs(h-ch) + abs(w-cw);
}

void solveEven() {
    int ch = D/2-1;
    int cw = D/2-1;
    REP (h, H) {
        REP (w, W) {
            int k = (w/D+h/D)%2;
            int hh = h-h/D*D;
            int ww = w-w/D*D;
            if (diff(hh,ww,ch,cw)<D/2 || diff(hh,ww,ch,cw+1)<D/2) {
                cout << COLORS[k];
            } else if ((hh-ch)*(ww-cw) > 0) {
                cout << COLORS[2+k];
            } else {
                cout << COLORS[3-k];
            }
        }
        cout << "\n";
    }
}

void solve() {
    if (D == 2) {
        solve2();
    } else if (D%2 == 1) {
        solveOdd();
    } else {
        solveEven();
    }
}

