{
	fastInp;

	cin >> h >> w >> d;

	if (d % 2 == 1) {
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if ((i + j) % 2) {
					cout << "R";
				}
				else {
					cout << "G";
				}
			}
			cout << "\n";
		}
	}
	else {
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				col[i][j] = -1;
			}
		}

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (!used[i][j]) {
					dfs(i, j);
				}
				if (col[i][j] == 1) {
					cout << "R";
				}
				else if (col[i][j] == 2) {
					cout << "G";
				}
				else if (col[i][j] == 3) {
					cout << "B";
				}
				else {
					cout << "Y";
				}
			}
			cout << "\n";
		}
	}

	return 0;
}

