inline bool valid(int x, int y)
{
    return (0<=x&&x<n and 0<=y&&y<m);
}
void solve(int x, int y, int z, int zz)
{
    if( zz > n*m ) return;
    mp[x][y] = z+1;
    for(int i = 0 ; i <= d ; i++ )
    {
        int j = d-i;
        if( valid(x+i, y+j) and mp[x+i][y+j] != z+1 )
            solve(x+i, y+j, (z+1)%4, zz+1);
        if( valid(x-i, y+j) and mp[x-i][y+j] != z+1 )
            solve(x-i, y+j, (z+1)%4, zz+1);
        if( valid(x+i, y-j) and mp[x+i][y-j] != z+1 )
            solve(x+i, y-j, (z+1)%4, zz+1);
        if( valid(x-i, y-j) and mp[x-i][y-j] != z+1 )
            solve(x-i, y-j, (z+1)%4, zz+1);
    }
}
