void solve() {

    while(cin >> h) {
        cin >> w >> d;
        memset(a, 0, sizeof a);
        for (int i = 0; i <= min(h - 1, d); i++) {
            for (int j = 0; j <= min(w - 1, d); j++) {
                int a1 = i + 1, b1 = j - d - 1;//a2 = i - k, b2 = j;
                int t = 0;
                //cout << i << " " << j << endl;
                for (int i = 0; i <= d; i++) {
                    a1--; b1++;
                    //cout << a1 << " " << b1 << " ,";
                    if(check(a1, b1)) {
                        t |= a[a1][b1];
                    }
                }
                for (int i = 0; i < d; i++) {
                    a1++; b1++;
                    if(check(a1, b1)) {
                        t |= a[a1][b1];
                    }
                }
                //cout << endl;
                for (int x = 0; x < 4; x++) {
                    if(t & (1 << x)) continue;
                    a[i][j] = 1 << x; break;
                }
            }
        }
        for (int i = 0; i <= min(h - 1, d); i++) {
            for (int j = min(w - 1, d) + 1; j <= min(w - 1, d * 2); j++) {
                a[i][j] = a[i][d * 2 - j];
            }
        }
        for (int i = min(h - 1, d) + 1; i <= min(h - 1, d * 2); i++) {
            for (int j = 0; j <= min(w - 1, d); j++) {
                a[i][j] = a[d * 2 - i][j];
            }
        }
        for (int i = min(h - 1, d) + 1; i <= min(h - 1, d * 2); i++) {
            for (int j = min(w - 1, d) + 1; j <= min(w - 1, d * 2); j++) {
                a[i][j] = a[i][d * 2 - j];
            }
        }
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                a[i][j] = a[ i % (2 * d + 1)][j % (2 * d + 1)];
            }
        }
        pr();
    }
}

