const double pi = 3.141592653589793238462643383279502884197169399375105820974944592307816406286208998628034825342;

const int MR = 510;

int forbid[MR][MR];

bool done[MR][MR];

char res[MR][MR];

int cnt(int x)
{
	int res = 0;
	while (x)
	{
		res++;
		x &= (x - 1);
	}

	return res;
}

vector<PII> S[5];

void go(int H, int W, int d, PII start)
{
	REP(i, H)REP(j, W)
		if (MP(i, j) != start)
			S[0].push_back(MP(i, j));
	S[0].push_back(start);


	vector < char > col = { 'R','G','Y','B' };

	int ile = 0;
	while (ile < H*W)
	{
		PII akt;
		FORD(i, 5, 0)
		{
			bool found = 0;
			while (!S[i].empty())
			{
				akt = S[i].back(); S[i].pop_back();
				if (!done[akt.first][akt.second])
				{
					found = 1;
					break;
				}
			}

			if (found)
				break;
		}

		int x = akt.first, y = akt.second;
		bool ok = 0;
		REP(i, col.size())
		{
			char c = col[i];

			if ((forbid[x][y] & (1 << i)) == 0)
			{
				res[x][y] = c;
				ok = done[x][y] = 1;
				ile++;

				REP(k, d + 1)
				{
					if (x + k < H && y + d - k < W && !done[x + k][y + d - k])
					{
						if ((forbid[x + k][y + d - k] & (1 << i)) == 0)
						{
							forbid[x + k][y + d - k] |= (1 << i);
							S[cnt(forbid[x + k][y + d - k])].push_back(MP(x + k, y + d - k));
						}
					}

					if (x + k < H && y - d + k >= 0 && !done[x + k][y - d + k])
					{
						if ((forbid[x + k][y - d + k] & (1 << i)) == 0)
						{
							forbid[x + k][y - d + k] |= (1 << i);
							S[cnt(forbid[x + k][y - d + k])].push_back(MP(x + k, y - d + k));
						}
					}

					if (x - k >= 0 && y + d - k < W && !done[x - k][y + d - k])
					{
						if ((forbid[x - k][y + d - k] & (1 << i)) == 0)
						{
							forbid[x - k][y + d - k] |= (1 << i);
							S[cnt(forbid[x - k][y + d - k])].push_back(MP(x - k, y + d - k));
						}
					}

					if (x - k >= 0 && y - d + k >= 0 && !done[x - k][y - d + k])
					{
						if ((forbid[x - k][y - d + k] & (1 << i)) == 0)
						{
							forbid[x - k][y - d + k] |= (1 << i);
							S[cnt(forbid[x - k][y - d + k])].push_back(MP(x - k, y - d + k));
						}
					}
				}

				break;
			}
		}

		assert(ok);

		if (!ok)
		{
			REP(i, 5)
				S[i].clear();
			memset(done, 0, sizeof(done));
			memset(forbid, 0, sizeof(forbid));
			go(H, W, d, akt);
			return;
		}
	}
}

int main()
{
	int H, W, d;
	scanf("%d%d%d", &H, &W, &d);

	go(H, W, d, MP(H/2, W/2));

	REP(i, H)
		printf("%s\n", res[i]);

	return 0;
}

