string COLOR = "RGBY";

int H, W, D;
char MAT[MAX_H][MAX_H + 1];

int idx(char x) {
  for (int i = 0; i < COLOR.size(); i++)
    if (x == COLOR[i]) return i;
  return -1;
}

bool is_inside(int r , int c) {
  return (0 <= r && r < H) && (0 <= c && c < W);
}

void solve() {
  for (int i = 0; i < H; i++)
    for (int j = 0; j <= W; j++) MAT[i][j] = '\0';


  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (MAT[i][j] != '\0') continue;
      int k = 0;
#ifdef DEBUG
cout << i << " " << j << endl;
#endif
      queue<Pi> q;
      q.push(Pi(i, j));
      MAT[i][j] = COLOR[k];
      while(!q.empty()) {
        Pi rc = q.front(); q.pop();
        int r = rc.FST, c = rc.SND;
#ifdef DEBUG
cout << "\t" << r << " " << c << endl;
#endif

        for (int i = 0; i < D; i++) {
          int nr = r + i, nc = c + D - i;
          if (is_inside(nr, nc) && MAT[nr][nc] == '\0') {
            k++;
            MAT[nr][nc] = COLOR[k];
            q.push(Pi(nr, nc));
          }
          nr = r + D - i, nc = c - i;
          if (is_inside(nr, nc) && MAT[nr][nc] == '\0') {
            k++;
            MAT[nr][nc] = COLOR[k];
            q.push(Pi(nr, nc));
          }
          nr = r - i, nc = c - D + i;
          if (is_inside(nr, nc) && MAT[nr][nc] == '\0') {
            k++;
            MAT[nr][nc] = COLOR[k];
            q.push(Pi(nr, nc));
          }
          nr = r - D + i, nc = c + i;
          if (is_inside(nr, nc) && MAT[nr][nc] == '\0') {
            k++;
            MAT[nr][nc] = COLOR[k];
            q.push(Pi(nr, nc));
          }
        }
      }
    }
  }

  for (int i = 0; i < H; i++)
    cout << MAT[i] << endl;

}

int main() {
  cin >> H >> W >> D;

  solve();

  return 0;
}

