void setc(int x,int y,int color)
{
  c[x][y]=v[color];
  able[x][y][color]=1;
  for (int i=max(x-d,1);i<=min(x+d,n);i++)
  {
    int dis=d-abs(x-i);
    if (y+dis>0&&y+dis<=m)
    {
      able[i][y+dis][color]=1;
      //printf("+ %d %d %d\n",i,y+dis,color);
    }
    if (y-dis>0&&y-dis<=m)
    {
      able[i][y-dis][color]=1;
      //printf("- %d %d %d\n",i,y-dis,color);
    }
  }
}
