    for (int j=1;j<=m;j++)
    {
      for (int k=0;k<=3;k++)
      {
        if (able[i][j][k]==0)
        {
          setc(i,j,k);
          //printf("set %d %d to %c\n",i,j,v[k]);
          break;
        }
        //if (k==3) assert(false);
      }
    }
  }
  //system("pause");
