#define N 505
using namespace std;

int h, w, d;
int ans[N][N];

int main(){

  cin>>h>>w>>d;

  for(int i=0;i<h;i++){

    for(int j=0;j<w;j++){

      int used[5]={};
      int color=-1, color2=-1, color3=-1;

      for(int k=0;k<=d;k++){

	int l=d-k;

	if(i-k>=0&&j-l>=0){
	  used[ans[i-k][j-l]]=true;
	  if(ans[i-k][j-l]){
	    if(k==l) color3=ans[i-k][j-l];
	    else color=ans[i-k][j-l];
	  }
	}

	if(i-k>=0&&j+l<w){
	  used[ans[i-k][j+l]]=true;
	  if(ans[i-k][j+l]){
	    if(k==l) color2=ans[i-k][j+l];
	    else color=ans[i-k][j+l];
	  }
	}

	if(i+k<h&&j-l>=0){
	  used[ans[i+k][j-l]]=true;
	  if(ans[i+k][j-l]){
	    if(k==l) color2=ans[i+k][j-l];
	    else color=ans[i+k][j-l];
	  }
	}

	if(i+k<h&&j+l<w){
	  used[ans[i+k][j+l]]=true;
	  if(ans[i+k][j+l]){
	    if(k==l) color3=ans[i+k][j+l];
	    else color=ans[i+k][j+l];
	  }
	}

      }

      used[ans[i][j]]=true;

      if(!ans[i][j]){
	for(int k=1;k<=4;k++)
	  if(!used[k]){
	    ans[i][j]=k;
	    used[k]=true;
	    break;
	  }
      }

      if(color==-1){

	for(int k=1;k<=4;k++)
	  if(!used[k]){
	    color=k;
	    used[k]=true;
	    break;
	  }

      }

      if(color2==-1){

	for(int k=1;k<=4;k++)
	  if(!used[k]){
	    color2=k;
	    used[k]=true;
	    break;
	  }

      }

      if(color3==-1){

	for(int k=1;k<=4;k++)
	  if(!used[k]){
	    color3=k;
	    used[k]=true;
	    break;
	  }

      }


      for(int k=0;k<=d;k++){

	int l=d-k;

	if(ans[i-k][j-l]) continue;

	if(i-k>=0&&j-l>=0){
	  if(k==l) ans[i-k][j-l]=color3;
	  else ans[i-k][j-l]=color;
	}

	if(i-k>=0&&j+l<w){
	  if(k==l) ans[i-k][j+l]=color2;
	  else ans[i-k][j+l]=color;
	}

	if(i+k<h&&j-l>=0){
	  if(k==l) ans[i+k][j-l]=color2;
	  else ans[i+k][j-l]=color;
	}

	if(i+k<h&&j+l<w){
	  if(k==l) ans[i+k][j+l]=color3;
	  else ans[i+k][j+l]=color;
	}

      }


    }

  }

  char color[5]={'x','R','Y','B','G'};

  assert(!(d%2));

  for(int i=0;i<h;i++){

    for(int j=0;j<w;j++) cout<<color[ans[i][j]];
    cout<<endl;

  }

  return 0;
}

