				if(chk(i + d, j)) ins(id[i][j], id[i + d][j]);
				if(chk(i - d, j)) ins(id[i][j], id[i - d][j]);
				if(chk(i, j + d)) ins(id[i][j], id[i][j + d]);
				if(chk(i, j - d)) ins(id[i][j], id[i][j - d]);
			} 
		paint();
		for(i = 1; i <= h; i++, puts(""))
			for(j = 1; j <= w; j++)
				cout << (col[id[i][j]] ? "R" : "Y");
	}
	return 0;
}

