template<class T>
T rem(const T &a, const T &b){
	return (a%b+b)%b;
}

template<class T>
T floor_div(const T &a,const T &b){
	assert(b>0);
	T ret = (a-rem(a,b))/b;
	if(not (ret*b<=a and a<(ret+1)*b)){
		cout<<a<<" "<<b<<endl;
		assert(false);
	}
	return ret;
}

template<class T>
T ceil_div(const T &a,const T &b){
	return (a+b-T(1))/b;
}

void solve(long long H, long long W, long long d){
	REP(i,H){
		REP(j,W){
			int k = d;
			int i0 = floor_div(i-j,k), j0 = floor_div(i+j,k);
			if(i0%2==0){
				if(j0%2==0){
					fout<<"R";
				}else{
					fout<<"Y";
				}
			}else{
				if(j0%2==0){
					fout<<"G";
				}else{
					fout<<"B";
				}

			}
		}
		fout<<endl;
	}
}

