void solve(int x, int y, int z)
{
    mp[x][y] = z+1;
    for(int i = 0 ; i <= d ; i++ )
    {
        int j = d-i;
        if( valid(x+i, y+j) and mp[x+i][y+j] != z+1 )
            solve(x+i, y+j, (z+1)%4);
        if( valid(x-i, y+j) and mp[x-i][y+j] != z+1 )
            solve(x-i, y+j, (z+1)%4);
        if( valid(x+i, y-j) and mp[x+i][y-j] != z+1 )
            solve(x+i, y-j, (z+1)%4);
        if( valid(x-i, y-j) and mp[x-i][y-j] != z+1 )
            solve(x-i, y-j, (z+1)%4);
    }
}
