  ll H,W,d; cin>>H>>W>>d;
  if(d%2){
    REP(i,H){
      REP(j,W){
        if(i%2){
          if(j%2) cout<<"R";
          else cout<<"G";
        }else {
          if(j%2) cout<<"B";
          else cout<<"Y";
        }
      }
