          }
          if(0<=j+k&&j+k<H&&0<=i-d+k&&i-d+k<W){
            cnt[mp[j+k][i-d+k]]+=1;
          }
        }
        REP(k,4) if(cnt[k]==0) {mp[j][i]=k;break;}
      }
    }
    if(swapped==false){
      REP(i,H) {
        REP(j,W){
          if(mp[i][j]==0) cout<<"R";
          else if(mp[i][j]==1) cout<<"G";
          else if(mp[i][j]==2) cout<<"B";
          else if(mp[i][j]==3) cout<<"Y";
        }
        cout<<endl;
      }
