    Int H, W, d;

    void solve() {
        cin >> H >> W >> d;
        vector<vector<char>> col(H + W, vector<char>(H + W));
        for (int i = 0; i < H + W; ++i) {
            for (int j = 0; j < H + W; ++j) {
                string cnv[2] = {"RG", "BY"};

                Int r = (i / d) % 2;
                Int c = (j / d) % 2;
                col[i][j] = cnv[r][c];
            }
        }

        vector<vector<char>> ans(H, vector<char>(W));
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                ans[i][j] = col[i + j][i - j + W];
                cout << ans[i][j];
            }
            cout << endl;
        }


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

