int mass[512][512];
int H, W, d;
string color = "RYGB";

const int dx[4] = {1, -1, -1, 1};
const int dy[4] = {-1, 1,-1, 1};

void dfs(int x, int y){
  int color = -1;
  for(int i=0;i<=d;i++){
    for(int j=0;j<4;j++){
      int nx = x + i*dx[j], ny = y + (d-i)*dy[j];
      if(nx < 0 || ny < 0 || nx >= H || ny >= W) continue;
      color = max(color, mass[nx][ny]);
    }
  }
  mass[x][y] = color+1;      
  for(int i=0;i<=d;i++){
    for(int j=0;j<4;j++){
      int nx = x + i*dx[j], ny = y + (d-i)*dy[j];
      if(nx < 0 || ny < 0 || nx >= H || ny >= W) continue;
      if(mass[nx][ny] != -1) continue;
      dfs(nx, ny);
    }
  }
}

int main()
{
  cin >> H >> W >> d;

  memset(mass, -1, sizeof(mass));

  for(int i=0;i<H;i++){
    for(int j=0;j<W;j++){
      if(mass[i][j] == -1){
	dfs(i, j);
      }
    }
  }

  for(int i=0;i<H;i++){
    for(int j=0;j<W;j++){
      cout << color[mass[i][j]];
    }
    cout << endl;
  }
  return 0;
}

