int H, W, d;
vector<vector<int> > che;

void init()
{
	cin >> H >> W >> d;
	int n = H + W - 1;
	che.resize(n);
	rep(i, n) {
		che[i].resize(n);
	}
	int col[2][2] = {{0, 1}, {2, 3}};
	rep(i, n) {
		int rcol = (i / d) % 2;
		rep(j, n) {
			int ccol = (j / d) % 2;
			che[i][j] = col[rcol][ccol];
		}
	}
}

void solve()
{
	char col[4] = {'R', 'B', 'G', 'Y'};
	int r = 0;
	int c = H - 1;
	rep(i, H) {
		rep(j, W) {
			cout << col[che[r][c]];
			r++;
			c++;
		}
		r = i + 1;
		c = H - i - 1;
		cout << endl;
	}
}

