struct Edge {
	int to, nxt;
} edge[maxm];
int tot, head[maxn], vis[maxn], n, m, w, c[maxn];
void init() {
	tot = 0;
	memset(head, -1, sizeof head);
}
void add(int u, int v) {
	edge[tot].to = v;
	edge[tot].nxt = head[u];
	head[u] = tot++;
}
void work(int x, int y) {
	for (int i = x - w; i <= x + w; i++) {
		if (i < 0 || i > n) continue;
		int j = w - abs(x - i);
		int ey = y - j;
		if (ey >= 0) {
			add(x * m + y, i * m + ey);
			add(i * m + ey, x * m + y);
		}
		ey = y + j;
		if (ey < m) {
			add(x * m + y, i * m + ey);
			add(i * m + ey, x * m + y);
		}
	}
}
void dfs(int x, int p, int col) {
	c[x] = col;
	vis[x] = 1;
	for (int i = head[x]; i != -1; i = edge[i].nxt) {
		int u = edge[i].to;
		if (u == p) continue;
		if (!vis[u]) dfs(u, x, (col + 1) % 4);
	}
}
