vector<vector<char> > solve(int h, int w, int d) {
    w = max(2 * h, w);
    auto f = vectors(h, w, char());
    if (d % 2 == 1) {
        repeat (y, h) repeat (x, w) {
            f[y][x] = (y + x) % 4 + 1;
        }
    } else {
        repeat (y, h) repeat (x, w) {
            int y1 = y % (d + 2);
            int x1 = (x - y1) % (2 * d);
            if (x1 < (d - 2 * y1)) {
                f[y][x] = 1;
            } else if (x1 < d) {
                f[y][x] = 2;
            } else if (x1 - d < (d - 2 * y1)) {
                f[y][x] = 3;
            } else {
                f[y][x] = 4;
            }
        }
    }
    return f;
}

