inline bool inside(int nh, int nw) {
    return 0 <= nh && nh < h && 0 <= nw && nw < w;
}

inline bool inside(int nn, bool f) {
    if (f) return 0 <= nn && nn < h;
    else return 0 <= nn && nn < w;
}

void dfs(int nh, int nw) {
    if (c[nh][nw] != 0) {
        return;
    }
    unordered_set<char> se;
    FORE(e, cc) se.insert(e);
    VPII v;
    REP(i, d + 1) {
        REP(j, 4) {
            int hh = nh + i * dh[j];
            int ww = nw + (d - i) * dw[j];
            bool in = inside(hh, ww);
            if (in && c[hh][ww] != 0) {
                se.erase(c[hh][ww]);
            } else if (in) {
                v.EB(MP(hh, ww));
            }

            hh = nh + (d - i) * dh[j];
            ww = nw + i * dw[j];
            in = inside(hh, ww);
            if (in && c[hh][ww] != 0) {
                se.erase(c[hh][ww]);
            } else if (in) {
                v.EB(MP(hh, ww));
            }
        }
    }
    assert(!se.empty());
    c[nh][nw] = *se.begin();
    FORE(e, v) {
        dfs(e.first, e.second);
    }
}

