#define PII pair < int , int >
#define st first
#define nd second
const char mod[] = "RGYB";
const int dir[4][2] = {0,1,0,-1,1,0,-1,0};
char col[503][503];
int N , M , D;
map < PII , int > vised;

void paint(int x , int y , int ind){
    if(vised[PII(x , y)] || x <= -D || y <= -D || x > N + D || y > M + D)
	return;
    vised[PII(x,y)] = 1;
    queue < PII > q;
    if(x > 0 && x <= N && y > 0 && y <= M)
	col[x][y] = mod[ind];
    q.push(PII(x , y));
    for(int i = 1 ; i < D ; ++i)
	for(int j = q.size() ; j ; --j){
	    PII t = q.front();
	    q.pop();
	    for(int k = 0 ; k < 4 ; ++k){
		PII n = PII(t.st + dir[k][0] , t.nd + dir[k][1]);
		if(n.st > 0 && n.st <= N && n.nd > 0 && n.nd <= M && !col[n.st][n.nd]){
		    col[n.st][n.nd] = mod[ind];
		    q.push(n);
		}
		else
		    if(!(n.st > 0 && n.st <= N && n.nd > 0 && n.nd <= M && col[n.st][n.nd]))
			q.push(n);
	    }
	}
    paint(x + D , y + D - 1 , ind ^ 2);
    paint(x - D , y - D + 1 , ind ^ 2);
    paint(x + D - 1 , y - D , ind ^ 1);
    paint(x - D + 1 , y + D , ind ^ 1);
}

