const int MaxN = 500;
int n, m, D, col[MaxN + 5][MaxN + 5];
struct Node {
	int x, y;
}seq[MaxN * MaxN + 5];
bool flag[MaxN + 5][MaxN + 5][5];
bool vis[MaxN + 5][MaxN + 5];

bool Check(int x, int y)
{
	if (x < 1) return false;
	if (x > n) return false;
	if (y < 1) return false;
	if (y > m) return false;
	return true;
}

void Bfs(int sx, int sy)
{
	int head = 1, tail = 0; seq[++tail].x = sx; seq[tail].y = sy; vis[sx][sy] = true;
	while (head <= tail) {
		Node now = seq[head];
		for (int i = 1; i <= 4; i++) 
			if (!flag[now.x][now.y][i]) {
				col[now.x][now.y] = i;
				break;
			}
		for (int x = now.x - D, y = now.y; x <= now.x && y >= now.y - D; x++, y--) {
			if (!Check(x, y)) continue;
			flag[x][y][col[now.x][now.y]] = true;
			if (!vis[x][y]) seq[++tail].x = x, seq[tail].y = y, vis[x][y] = true;
		}
		for (int x = now.x - D, y = now.y; x <= now.x && y <= now.y + D; x++, y++) {
			if (!Check(x, y)) continue;
			flag[x][y][col[now.x][now.y]] = true;
			if (!vis[x][y]) seq[++tail].x = x, seq[tail].y = y, vis[x][y] = true;
		}
		for (int x = now.x + D, y = now.y; x >= now.x && y >= now.y - D; x--, y--) {
			if (!Check(x, y)) continue;
			flag[x][y][col[now.x][now.y]] = true;
			if (!vis[x][y]) seq[++tail].x = x, seq[tail].y = y, vis[x][y] = true;
		}
		for (int x = now.x + D, y = now.y; x >= now.x && y <= now.y + D; x--, y++) {
			if (!Check(x, y)) continue;
			flag[x][y][col[now.x][now.y]] = true;
			if (!vis[x][y]) seq[++tail].x = x, seq[tail].y = y, vis[x][y] = true;
		}
		head++;
	}
}

