const int dx[] = { -1, 0, 1, 0 }, dy[] = { 0, -1, 0, 1 };
bool valid(int x, int y, int h, int w) { return (x >= 0 && y >= 0 && x < h&&y < w); }
int place(int x, int y, int w) { return w*x + y; }


int main()
{
	cin.sync_with_stdio(false); cout << fixed << setprecision(10);
	int h, w; cin >> h >> w;
	int d; cin >> d;
	vi v(h * w);
	vi ans;
	if (d % 2 == 1)
	{
		REP(x, h)REP(y, w)
		{
			int p = place(x, y, w);
			int c = -1;
			if (p % 2 == 0)
			{
				REP(k, 4)
				{
					if ((v[p] >> k) & 1) continue;
					c = k;
					break;
				}
			}
			else
			{
				for (int k = 3; k >= 0; k--)
				{
					if ((v[p] >> k) & 1) continue;
					c = k;
					break;
				}
			}

			assert(c >= 0);
			ans.push_back(c);
			REP(i, d + 1)
			{
				int dx = i;
				int dy = d - i;
				if (x + dx >= h || y + dy >= w) continue;
				int q = place(x + dx, y + dy, w);
				v[q] |= 1 << c;
			}
			REP(i, d + 1)
			{
				int dx = i;
				int dy = d - i;
				if (x + dx >= h || y - dy < 0) continue;
				int q = place(x + dx, y - dy, w);
				v[q] |= 1 << c;
			}
		}
		int p = 0;
		REP(i, h)
		{
			REP(j, w)
			{
				if (ans[p] == 0) cout << "R";
				if (ans[p] == 1) cout << "Y";
				if (ans[p] == 2) cout << "G";
				if (ans[p] == 3) cout << "B";
				p++;
			}
			cout << endl;
		}
	}
	else
	{
		vs ans(h, string(w, '.'));
		REP(i, h)REP(j, w)
		{
			if (ans[i][j] != '.') continue;
			queue<pii> que;
			que.emplace(i, j);
			while (!que.empty())
			{
				int x = que.front().first;
				int y = que.front().second;
				que.pop();
				if (!valid(x, y, h, w)) continue;
				if (ans[x][y] != '.') continue;
				ans[x][y] = 'R';
				REP(k, 4)
				{
					int nx = x + dx[k] * d;
					int ny = y + dy[k] * d;
					if (!valid(nx, ny, h, w) || ans[nx][ny] != '.') continue;
					ans[nx][ny] = 'Y';
				}

				int nx, ny;
				nx = x - d / 2, ny = y - d / 2;
				if (valid(nx, ny, h, w) && ans[nx][ny] == '.')  ans[nx][ny] = 'G';
				nx = x + d / 2, ny = y + d / 2;
				if (valid(nx, ny, h, w) && ans[nx][ny] == '.')  ans[nx][ny] = 'G';
				nx = x + d / 2, ny = y - d / 2;
				if (valid(nx, ny, h, w) && ans[nx][ny] == '.')  ans[nx][ny] = 'B';
				nx = x - d / 2, ny = y + d / 2;
				if (valid(nx, ny, h, w) && ans[nx][ny] == '.')  ans[nx][ny] = 'B';

				que.emplace(x + d, y + d);
				que.emplace(x, y + d * 2);
				que.emplace(x + d * 2, y);
			}
		}
		cout << ans << endl;
	}
	return 0;
}

