                    masu[i][j] = k;
                    in_line[line][k] = true;
                    flag = true;
                    break;
                }
            }
        }
        if(!flag){
            REP(k, 4){
                if(can_use[k]){
                    masu[i][j] = k;
                    in_line[line][k] = true;
                    in_line2[line2][k] = true;
                    flag = true;
                    break;
                }
            }
        }
        if(!flag) assert(false);
    }

    REP(i, h){
        REP(j, w){
            cout << color[masu[i][j]];
        }
        cout << endl;
    }
}

