                for(int i=d; i; i--){
                    if(r-i<0 || r-i>=h)continue;
                    if(c+d-i<0 || c+d-i>=w)continue;
                    assert(a[r-i][c+d-i]!=2);
                    a[r-i][c+d-i]=0;
                }
                //[R, D)
                for(int i=d; i; i--){
                    if(r+d-i<0 || r+d-i>=h)continue;
                    if(c+i<0 || c+i>=w)continue;
                    assert(a[r+d-i][c+i]!=2);
                    a[r+d-i][c+i]=0;
                }
                //[D, L)
                for(int i=d; i; i--){
                    if(r+i<0 || r+i>=h)continue;
                    if(c-d+i<0 || c-d+i>=w)continue;
