}

int check(const int r, const int c, const int f){
    int idx=-1;
    int hlf=d>>1;
    //[L, U)
    for(int i=d; i; i--){
        idx++;
        if(r-d+i<0 || r-d+i>=h)continue;
        if(c-i<0 || c-i>=w)continue;
        if(!~a[r-d+i][c-i])continue;
        if(a[r-d+i][c-i]!=(((idx/hlf)&1)^f))return 0;
    }
    //[U, R)
    for(int i=d; i; i--){
        idx++;
        if(r-i<0 || r-i>=h)continue;
        if(c+d-i<0 || c+d-i>=w)continue;
        if(!~a[r-i][c+d-i])continue;
        int goal=((idx/hlf)&1)^f;
        if(goal)goal|=2;
        if(a[r-i][c+d-i]!=goal)return 0;
    }
    //[R, D)
    for(int i=d; i; i--){
        idx++;
        if(r+d-i<0 || r+d-i>=h)continue;
        if(c+i<0 || c+i>=w)continue;
        if(!~a[r+d-i][c+i])continue;
        int goal=((idx/hlf)&1)^f;
        if(goal)goal|=2;
        if(a[r+d-i][c+i]!=goal)return 0;
    }
    //[D, L)
    for(int i=d; i; i--){
        idx++;
        if(r+i<0 || r+i>=h)continue;
        if(c-d+i<0 || c-d+i>=w)continue;
        if(!~a[r+i][c-d+i])continue;
        if(a[r+i][c-d+i]!=(((idx/hlf)&1)^f))return 0;
    }
    return 1;
}

