    unordered_map<int, char> color; color.emplace(0, 'R'); color.emplace(1, 'G'); color.emplace(2, 'B'); color.emplace(3, 'Y');
    unordered_map<char, int> rev; rev.emplace('R', 0); rev.emplace('G', 1); rev.emplace('B', 2); rev.emplace('Y', 3);
    bool end_flag = false;
    function<int(int, int)> search = [&](int i, int j){
        if (D + 1 <= i || D + 1 <= j){
            end_flag = true;
            return 0;
        }
        array<bool, 4> flag = {true, true, true, true};
        for (int h = i; 0 <= h; --h){
            if (h == i){
                int w = j - D;
                flag[rev[board[h % (D + 1)][w % (D + 1)]]] = false;
            }else{
                int w;
                w = j - (D - (i - h));
                flag[rev[board[h % (D + 1)][w % (D + 1)]]] = false;
                w = j + (D - (i - h));
                flag[rev[board[h % (D + 1)][w % (D + 1)]]] = false;
            }
        }
        if (flag[0] == false && flag[1] == false && flag[2] == false && flag[3] == false) return D - 1;
        loop(c, 4){
            if (flag[c] == false) continue;
            board[i][j] = color[c];
            int back = search(i + ((j + 1) / (D + 1)), (j + 1) % (D + 1));
            if (end_flag){
                return 0;
            }else{
                board[i][j] = ' ';
                if (0 < back) return back - 1;
            }
        }
    };
    search(0, 0);
    loop(i, H){
        loop(j, W){
            putchar(board[i % (D + 1)][j % (D + 1)]);
        }
        puts("");
    }
}

