int n, m, d;
int col[1001][1001];
int note[550][550][5];
queue<int> q;
int haha(int i, int j){return i*1000 + j;}
void bfs(){
    while(!q.empty()){
        int u = q.front(); q.pop();
        int x = u / 1000, y = u % 1000;
        for(int i = 1; i <= 4; i ++){
            if(note[x][y][i] == 0){
                col[x][y] = i;
                break;
            }
        }
        int xx = x - d, yy = y;
        for(int i = 0; i <= d; i ++){
            if(1 <= xx && xx <= n && 1 <= yy && yy <= m){
                if(!col[xx][yy]){
                    note[xx][yy][col[x][y]] = 1;
                    q.push(haha(xx,yy));
                }
            }
            xx ++;
            yy ++;
        }
        xx = x - d + 1, yy = y - 1;

        for(int i = 0; i <= d; i ++){
            if(1 <= xx && xx <= n && 1 <= yy && yy <= m){
                if(!col[xx][yy]){
                    note[xx][yy][col[x][y]] = 1;
                    q.push(haha(xx,yy));
                }
            }
            xx ++;
            yy --;
        }

        xx = x + d, yy = y;


        for(int i = 0; i <= d; i ++){
            if(1 <= xx && xx <= n && 1 <= yy && yy <= m){
                if(!col[xx][yy]){
                    note[xx][yy][col[x][y]] = 1;
                    q.push(haha(xx,yy));
                }
            }
            xx --;
            yy ++;
        }

        xx = x + d - 1, yy = y - 1;
        for(int i = 1; i <= d; i ++){
            if(1 <= xx && xx <= n && 1 <= yy && yy <= m){
                if(!col[xx][yy]){
                    note[xx][yy][col[x][y]] = 1;
                    q.push(haha(xx,yy));
                }
            }
            xx --;
            yy --;
        }
    }
}

