char grid[505][505];
int h,w,d;

void place_tile(int x0, int y0, char c) 
{
    //pr("place tile") pr(x0) pr(y0) pr(c) nl
    for (int col=0; col<d; col++) {
        int col_h = min(col+1,d-col);
        for (int row=-col_h; row<=col_h; row++) {
            int x = x0+col, y = y0+row;
            if (0 <= x and x < w and 0 <= y and y < h)
                grid[y][x] = c;
        }
    }
}

int32_t main()
{
    #ifdef DEBUG
    freopen("D.txt","r",stdin);
    //freopen("","w",stdout);
    #endif

    cin >> h >> w >> d;
    if (d%2 == 1) {
        for (int y=0; y<h; y++) {
            for (int x=0; x<w; x++) {
                if ((x+y)%2 == 0)
                    grid[y][x] = 'R';
                else 
                    grid[y][x] = 'G';
            }
        }
    }
    else if (d%4 == 2) {
        for (int y=0; y<h; y++) {
            for (int x=0; x<w; x++) {
                if (y%4 < 2)
                    grid[y][x] = "RGYB"[x%4];
                else 
                    grid[y][x] = "YBRG"[x%4];
            }
        }
    }
    else {
        int y_id=0;
        for (int y=0; y<h+d; y+=d/2) {
            y_id = (y_id+1) %4;
            string chars;
            switch(y_id) {
            case 0: 
                chars = "RG";
                break;
            case 1: 
                chars = "YB";
                break;
            case 2: 
                chars = "GR";
                break;
            case 3: 
                chars = "BY";
                break;
            }            
            int startx = y_id%2 == 0 ? 0 : -d/2;

            int x_id = 0;
            for (int x=startx; x<=w+d; x+=d) {
                x_id = (x_id+1)%2;
                char c = chars[x_id];
                place_tile(x,y,c);
            }
        }
    }

    for0(y,h) {
        for0(x,w) {
            putchar(grid[y][x]);
        }
        putchar('\n');
    }
    return 0;
}

