void solve(istream& cin, ostream& cout) {
  l n, m, k; cin >> n >> m >> k;
  vvl v(n, vl(m, (1 << 4) - 1));
  vvb visited(n, vb(m));
  F(i, 0, n) {
    F(j, 0, m) {
      if (visited[i][j]) continue;
      queue<ll> q;
      q.emplace(i, j);
      visited[i][j] = true;
      while (!q.empty()) {
        l x, y; tie(x, y) = q.front(); q.pop();
        l c = 1; while (c < 16 and ((c & v[x][y]) == 0)) c++;
        assert(c < 16);
        v[x][y] = c;
        // mark neighbours
        F(x1, x-k, x + k + 1) {
          l y1 = y + k - abs(x1 - x);
          if (x1 >= 0 and x1 < n and y1 >= 0 and y1 < m) {
            if (v[x1][y1] & c) v[x1][y1] -= c;
            if (not visited[x1][y1]) {
              visited[x1][y1] = true;
              q.emplace(x1, y1);
            }
          }
          y1 = y - k + abs(x1 - x);
          if (x1 >= 0 and x1 < n and y1 >= 0 and y1 < m) {
            if (v[x1][y1] & c) v[x1][y1] -= c;
            if (not visited[x1][y1]) {
              visited[x1][y1] = true;
              q.emplace(x1, y1);
            }
          }
        }
      }
    }
  }
  string colors = "0RG3B567Y";
  F(i, 0, n) {
    F(j, 0, m) {
      assert(v[i][j]);
      cout << colors[v[i][j]];
    }
    cout << lf;
  }
}

