/* grid 4-coloring, Chebyshev Distance */
/*
 * 曼哈顿距离是一个立着的正方形, 不方便处理.    d = |xi-xj|+|yi-yj|
 * 将矩阵旋转45°, 转为切比雪夫距离(正方形).     d = max{|xi-xj|,|yi-yj|}
 */

const int maxn = 3e3;
char color[maxn][maxn];
int H,W,d;

int main()
{
/* #ifndef ONLINE_JUDGE */
/*     freopen("foo", "rt", stdin); */
/* #endif */
    while (cin >> H >> W >> d) {
        const char C[2][2] = { {'R','G'}, {'B','Y'} };
        int row,col; row = col = 0;
        for (int i = 0; i < maxn; i += d) {
            for (int j = 0; j < maxn; j += d) {
                for (int x = i; x < i+d; x++) {
                    for (int y = j; y < j+d; y++) {
                        color[x][y] = C[row][col];
                    }
                }
                col ^= 1;
            }
            row ^= 1;
        }
        row = 0;
        FOR(i,0,H) {
            FOR(j,0,W) {
                const int x = i+j + row;
                const int y = i-j + W;
                cout << color[x][y];
                row ^= 1;
            }
            cout << endl;
        }
    }
    return 0;
}

