void dfs(int y,int x,int cur) {
	if(y<0 || y>=H || x<0 || x>=W) return;
	if(R[y][x]!=4) return;
	R[y][x]=cur;
	dfs(y+D,x,cur^2);
	dfs(y-D,x,cur^2);
	dfs(y,x+D,cur^1);
	dfs(y,x-D,cur^1);
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>H>>W>>D;

	if(D%2) {
		FOR(y,H) FOR(x,W) R[y][x]=(y+x)%2;
	}
	else if(D%4==2) {
		FOR(y,H) FOR(x,W) R[y][x]=(y%2*2)+(y/2+x/2)%2;
	}
	else {
		FOR(y,H) FOR(x,H) {
			if(D%8==0) {
				int dy=y+x+1000;
