using namespace std;
using vi=vector<int>;
using vvi=vector<vi>;
using vc=vector<char>;
using vvc=vector<vc>;


struct f_t
{
	int n;
	int x, y, f;
	bool operator<(const f_t&rhs) const
	{
		if(n!=rhs.n) return n>rhs.n;
		if(x!=rhs.x) return x>rhs.x;
		return y>rhs.y;
	}
};


bool cmp(f_t*a, f_t*b)
{
	if(a->n!=b->n) return a->n>b->n;
	if(a->x!=b->x) return a->x<b->x;
	return a->y<b->y;
}


void solve(vvc&ans, int d)
{
	int h=ans.size();
	int w=ans[0].size();
	char s[]="RYGBxyz";

	if(d%2)
	{
		for(int y=0;y<h;y++)
		{
			for(int x=0;x<w;x++)
			{
				ans[y][x]=s[(x+y)%2];
			}
		}
		return;
	}

	vector<vector<f_t>> f(h);
	vector<f_t*> p;
	for(auto&fe:f) fe.resize(w);

	for(int y=0;y<h;y++)
	{
		for(int x=0;x<w;x++)
		{
			f[y][x]=(f_t){4, x, y, 0x0F};
			p.push_back(&f[y][x]);
		}
	}
	f[0][0]=(f_t){1, 0, 0, 0x01};
	for(;!p.empty();)
	{
		if(p.back()->n>1) sort(p.begin(), p.end(), cmp);
		f_t fe=*p.back();
		p.pop_back();

		int nx, ny, i;

		for(i=0;i<4;i++)
		{
			if((fe.f>>i)&1) break;
		}
		ans[fe.y][fe.x]=s[i];

		for(int y=-d;y<=d;y++)
		{
			ny=fe.y+y;
			nx=fe.x+d-abs(y);
			if((0<=nx && nx<w) && (0<=ny && ny<h))
			{
				if(f[ny][nx].f&(1<<i))
				{
					f[ny][nx].f^=(1<<i);
					f[ny][nx].n--;
				}
			}

			ny=fe.y+y;
			nx=fe.x-d+abs(y);
			if((0<=nx && nx<w) && (0<=ny && ny<h))
			{
				if(f[ny][nx].f&(1<<i))
				{
					f[ny][nx].f^=(1<<i);
					f[ny][nx].n--;
				}
			}
		}
	}

}


int main(void)
{
	int h, w, d;

	while(scanf("%d%d%d", &h, &w, &d)==3)
	{
		vvi f(h);
		vvc ans(h);

		for(int y=0;y<h;y++)
		{
			f[y].assign(w, 0x0F);
			ans[y].assign(w, '#');
		}

		solve(ans, d);

		for(int y=0;y<h;y++)
		{
			printf("%.*s\n", w, &ans[y][0]);
		}
	}

	return 0;
}

