int H, W, D;
char F[512][512];
const char* S = "RYGB";

void place(int t, int d, int s) {
  int p = 0;
  for (int c = 0; c < W; ++c) {
    int r = t - c;
    if (0 <= r && r < H) {
      F[r][c] = S[s + (p >= d)];
    }
    p = (p + 1) % (2 * d);
  }
}

int main() {
  H = in();
  W = in();
  D = in();
  if (D % 2 == 1) {
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        putchar("RY"[(i + j) % 2]);
      }
      puts("");
    }
  } else {
    int p = 0;
    for (int t = 0; t <= H + W - 2; t += 2) {
      place(t, D / 2, (p >= D / 2) * 2);
      p = (p + 1) % D;
    }
    p = 0;
    for (int t = 1; t <= H + W - 2; t += 2) {
      place(t, D / 2, (p >= D / 2) * 2);
      p = (p + 1) % D;
    }
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        putchar(F[i][j]);
      }
      puts("");
    }
  }

