    {
        int j = d-i;
        if( valid(x+i, y+j) and mp[x+i][y+j] != z+1 and !chk[x+i][y+j] )
            solve(x+i, y+j, (z+1)%4);
        if( valid(x-i, y+j) and mp[x-i][y+j] != z+1 and !chk[x-i][y+j])
            solve(x-i, y+j, (z+1)%4);
        if( valid(x+i, y-j) and mp[x+i][y-j] != z+1 and !chk[x+i][y-j])
            solve(x+i, y-j, (z+1)%4);
        if( valid(x-i, y-j) and mp[x-i][y-j] != z+1 and !chk[x-i][y-j])
            solve(x-i, y-j, (z+1)%4);
    }
}
