int cal(int x,int y){
	if(x%2==1){
		if(y%2==1)
			return 1;
		else
			return 2;
	}
	else{
		if(y%2==1)
			return 3;
		else
			return 4;
	}
}

int locx(int x,int y){
	if((x+y-1)%d==0){
		return (x+y-1)/d;
	}
	else
		return (x+y-1)/d+1;
}

int locy(int x,int y){
	if((y-x+m)%d==0)
		return (y-x+m)/d;
	else
		return (y-x+m)/d+1;
}

