	vis[y + M][x + M] = 1;

	fill(y, x + d, 1);
	fill(y + d / 2, x + d / 2, 2);
	fill(y + d / 2, x - d / 2, 3);

	dfs(y - 1, x - d - d + 1);
	dfs(y + 1, x + d + d - 1);
	dfs(y + d + 1, x + d - 1);
	dfs(y - d - 1, x - d + 1);
}


