template<unsigned int size_>
class Index{
public:
	array<int,size_> sizes;
	size_t sz;
	Index(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		sz = 1;
		for(int i = 0; i < (int)size_; ++i) {
			sizes[i] = arg;
			sz *= arg;
			arg = va_arg(args,int);
		}

	}

	size_t size() {
		return sz;
	}

	int operator()(int first, ...){
		va_list args;
		va_start(args, first);
		int arg = first;
		int res = 0;
		int d = 1;
		for(int i = 0; i < (int)size_; ++i) {
			res += arg*d;
			d *= sizes[i];
			arg = va_arg(args,int);
		}
		return res;
	}
};

