const int kMaxN = 500 + 5;
const int kMaxColors = 4;

int N, M, D;
int marked[kMaxN][kMaxN][kMaxColors];
char color[kMaxColors];

char answer[kMaxN][kMaxN];

void Color(int x, int y, int pattern);
void Mark(int x, int y, int pattern);

void ActualMark(int x, int y, int pattern) {
    if(0 <= x && x < N && 0 <= y && y < M) {
        marked[x][y][pattern] = true;
    }
}

void Mark(int x, int y, int pattern) {
    if(0 <= x && x < N && 0 <= y && y < M) {
        marked[x][y][pattern] = true;
        if(answer[x][y] < 'A' || 'Z' < answer[x][y]) {
            for(int i = 0; i < 4; i++) {
                if(!marked[x][y][i]) {
                    Color(x, y, i); return;
                }
            }
        }
    }
}

void Color(int x, int y, int pattern) {
    answer[x][y] = color[pattern];

    for(int dx = 0, dy = D; dx <= D; dx++, dy--) {
        ActualMark(x - dx, y - dy, pattern);
        ActualMark(x - dx, y + dy, pattern);
        ActualMark(x + dx, y - dy, pattern);
        ActualMark(x + dx, y + dy, pattern);

        Mark(x - dx, y - dy, pattern);
        Mark(x - dx, y + dy, pattern);
        Mark(x + dx, y - dy, pattern);
        Mark(x + dx, y + dy, pattern);
    }
}

void Solve() {
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < M; j++) {
            if(answer[i][j] < 'A' || 'Z' < answer[i][j]) {
                for(int k = 0; k < 4; k++) {
                    if(!marked[i][j][k]) {
                        Color(i, j, k);
                    }
                }
            }
        }
    }
}

void WriteOutput() {
    for(int i = 0; i < N; i++) {
        printf("%s\n", answer[i]);
    }
}

int main() {
    scanf("%d%d%d", &N, &M, &D);
    color[0] = 'R'; color[1] = 'Y'; color[2] = 'G'; color[3] = 'B';

    Solve();

    WriteOutput();

	return 0;
}

