    input();
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            dfs(x,y);
        }
    }
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            cout << a[x][y] ;
        }
        cout << "\n";
    }
    return 0;
}

