void solve()
{
	int n, m, d;
	cin >> n >> m >> d;
	char ans[n][d]; CLR(ans);
	for (int i(0); i < n; ++i)
	{
		int c(0), r(i);
		while (c < m && r >= 0)
		{
			set <char> can = { 'G', 'B', 'R','Y' };
			for (int p(0); p <= d; ++p)
				if (r - p >= 0 && c - d + p >= 0)
					can.erase(ans[r - p][c - d + p]);
			ans[r--][c++] = gmin(can);
		}
	}
	for (int i(1); i < m; ++i)
	{
		int c(i), r(n - 1);
		while (c < m && r >= 0)
		{
			set <char> can = { 'G', 'B', 'R','Y' };
			for (int p(0); p <= d; ++p)
				if (r - p >= 0 && c - d + p >= 0)
					can.erase(ans[r - p][c - d + p]);
			ans[r--][c++] = gmin(can);
		}
	}
	for (int i(0); i < n; ++i)
	{
		for (int j(0); j < m; ++j)
		{
			assert(ans[i][j]);
			cout << ans[i][j];
		}
		cout << '\n';
	}
}

