// N^P mod M（ただしM == -1の時はmodを取らない）
template<typename T>
T RS(T N, T P, T M){
    if(P == 0) {
        return 1;
    }
    if(P < 0) {
        return 0;
    }
    if(P % 2 == 0){
        ll t = RS(N, P/2, M);
        if(M == -1) return t * t;
        return t * t % M;
    }
    if(M == -1) {
        return N * RS(N,P - 1,M);
    }
    return N * RS(N, P-1, M) % M;
}

int H, W, d;
int ret[550][550];
queue<P> que;

void solve(int x, int y) {
    vector<bool> used(4);
    for(int i = -d;i <= d;i++) {
        int ny = x + i;
        int nx = y - (d - abs(i));
        if(0 <= ny && ny < H && 0 <= nx && nx < W) {
            if(ret[ny][nx] == -1) {
                que.push(P(ny, nx));
            }
            else {
                used.at(ret[ny][nx]) = true;
            }
        }
        nx = y + (d - abs(i));
        if(0 <= ny && ny < H && 0 <= nx && nx < W) {
            if(ret[ny][nx] == -1) {
                que.push(P(ny, nx));
            }
            else {
                used.at(ret[ny][nx]) = true;
            }
        }
    }
    int res = -1;
    for(int i = 0;i < 4;i++) {
        if(used.at(i) == false) {
            res = i;
            break;
        }
    }
    ret[x][y] = res;
    while(!que.empty()) {
        P p = que.front();
        que.pop();
        if(ret[p.first][p.second] == -1) {
            solve(p.first, p.second);
        }
    }
    return;
}

