    }
    for(int i = 0;i < 550;i++) {
        for(int j = 0;j < 550;j++) {
            if(ret[i][j] == -1) {
                solve(i, j);
            }
        }
    }
    for(int i = 0;i < H;i++) {
        for(int j = 0;j < W;j++) {
