void encolor(int x, int y, int c) {
	for (int i = 0; i < d / 2; ++i) {
		if (x + i < 0 || x + i >= n)
			continue;
		for (int j = -i; j <= i; ++j) {
			if (y + j < 0 || y + j >= m)
				continue;
			table[x + i][y + j] = c;
		}
	}
	for (int i = d / 2 - 1; i >= 0; --i) {
		if (x + d / 2 + (d / 2 - i - 1) < 0 || x + d / 2 + (d / 2 - i - 1) >= n)
			continue;
		for (int j = -i; j <= i; ++j) {
			if (y + j < 0 || y + j >= m)
				continue;
			table[x + d / 2 + (d / 2 - i - 1)][y + j] = c;
		}
	}
}

