bool pc(int x, int y, int cl){
	if((c[y][x] & cl) == 0) return false;
	c[y][x] = cl;
	for(int i = 0; i <= d; ++i){
		if(y - (d - i) >= 0){
			if(x - i >= 0){
				if((cl & c[y - d + i][x - i]) != 0) c[y - d + i][x - i] ^= cl;
			}
			if(x + i < w){
				if((cl & c[y - d + i][x + i]) != 0) c[y - d + i][x + i] ^= cl;
			}
		}
		if(y + (d - i) < h){
			if(x - i >= 0){
				if((cl & c[y + d - i][x - i]) != 0) c[y + d - i][x - i] ^= cl;
			}
			if(x + i < w){
				if((cl & c[y + d - i][x + i]) != 0) c[y + d - i][x + i] ^= cl;
			}
		}
	}
	return true;
}

