typedef long long ll;

struct COLOR {
	bool r, g, b,y;

	COLOR() {
		r = true;
		g = true;
		b = true;
		y = true;
	}
};

int check(COLOR c) {
	if (c.r && !c.g && !c.b && !c.y)return 1;
	if (!c.r && c.g && !c.b && !c.y)return 2;
	if (!c.r && !c.g && c.b && !c.y)return 3;
	if (!c.r && !c.g && !c.b && c.y)return 4;
	return 0;
}

int H, W, d;

bool over(int i, int j) {
	if (i < 0 || j < 0 || i >= H || j >= W)return true;
	return false;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> H >> W >> d;
	vector<vector<char>>used(H, vector<char>(W));
	vector<vector<COLOR>>color(H, vector<COLOR>(W));

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (check(color[i][j]) == 0) {
				if (color[i][j].r) {
					color[i][j].g = false;
					color[i][j].b = false;
					color[i][j].y = false;
				}
				else if (color[i][j].g) {
					color[i][j].r = false;
					color[i][j].b = false;
					color[i][j].y = false;
				}
				else if (color[i][j].b) {
					color[i][j].g = false;
					color[i][j].r = false;
					color[i][j].y = false;
				}
				else if (color[i][j].y) {
					color[i][j].g = false;
					color[i][j].b = false;
					color[i][j].r = false;
				}
			}

			if (used[i][j])continue;

			int c = check(color[i][j]);
			used[i][j] = true;

			for (int k = -d; k <= d; k++) {
				int w = d - abs(k);

				if (w == 0) {
					int ni, nj;
					ni = i + k;
					nj = j;
					if (!over(ni, nj)) {
						if (c == 1)color[ni][nj].r = false;
						else if (c == 2)color[ni][nj].g = false;
						else if (c == 3)color[ni][nj].b = false;
						else if (c == 4)color[ni][nj].y = false;
					}
				}
				else {
					int ni, nj;
					ni = i + k;
					nj = j - w;
					if (!over(ni, nj)) {
						if (c == 1)color[ni][nj].r = false;
						else if (c == 2)color[ni][nj].g = false;
						else if (c == 3)color[ni][nj].b = false;
						else if (c == 4)color[ni][nj].y = false;
					}

					nj = j + w;
					if (!over(ni, nj)) {
						if (c == 1)color[ni][nj].r = false;
						else if (c == 2)color[ni][nj].g = false;
						else if (c == 3)color[ni][nj].b = false;
						else if (c == 4)color[ni][nj].y = false;
					}
				}
			}
		}
	}

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int c = check(color[i][j]);
			if (c == 1)cerr << "R";
			else if (c == 2)cerr << "G";
			else if (c == 3)cerr << "B";
			else if (c == 4)cerr << "Y";
		}
		cerr << endl;
	}

	return 0;
}

