                    auto i2 = i - k;
                    auto j2 = j + (d - k);
                    if (i2 < 0 || j2 >= W) {
                        continue;
                    }
                    if (ans[i2][j2] >= 0) {
                        use[ans[i2][j2]] = false;
                    }
                }
                // 左下
                REP (k, d + 1) {
                    auto i2 = i + k;
                    auto j2 = j - (d - k);
                    if (i2 >= H || j2 < 0) {
                        continue;
                    }
                    if (ans[i2][j2] >= 0) {
                        use[ans[i2][j2]] = false;
                    }
                }
                // 右下
                REP (k, d + 1) {
                    auto i2 = i + k;
                    auto j2 = j + (d - k);
                    if (i2 >= H || j2 >= W) {
                        continue;
                    }
                    if (ans[i2][j2] >= 0) {
                        use[ans[i2][j2]] = false;
                    }
