                i32 x = -1;
                REP (k, 4) {
                    if (use[k]) {
                        x = k;
                        break;
                    }
                }
                if (x != -1) {
                    ans[i][j] = x;
                }
            }

            if (j + 2 * d < W) {
                ans[i][j + 2 * d] = ans[i][j];
            }
            if (i + 2 * d < H) {
                ans[i + 2 * d][j] = ans[i][j];
            }
        }
