set<pii> vis;
void stamp(int x, int y, char c) {
  if (vis.count(mp(x, y))) return;
  if(x<-d || y<-d || x>n+d || y>m+d) return;
  vis.insert(mp(x, y));
  // cout<<x<<' '<<y<<' '<<c<<endl;
  bool ok = 0;
  for (int dec = 0; d - dec * 2 > 0; dec++) {
    for (int j = y + dec; j < y + d - dec; j++) {
      ok |= paint(x - dec, j, c);
      ok |= paint(x + dec, j, c);
    }
  }
  for (int k = 0; k < 4; k++) {
    stamp(x + dx[k] * d, y + dy[k] * d, c);
  }
}

