void solve(){
    int H,W,d;cin>>H>>W>>d;
    char t[4]={'R','G','B','Y'};
    vector<int> dx,dy;
    rep(i,-d,d+1){
        dx.push_back(i);
        dy.push_back(d-abs(i));
        if(abs(i)-d!=0){
            dx.push_back(i);
            dy.push_back(abs(i)-d);
        }
    }
    vector<vector<int>> col(H,vector<int>(W,-1));
    int i=0,k=0;
    REP(i,H) REP(k,W){
        if(col[i][k]!=-1) continue;
        queue<P> que;
        que.push(P(i,k));
        col[i][k]=0;
        while(!que.empty()){
            P p=que.front();que.pop();
            int x=p.first,y=p.second;
            REP(j,dx.size()){
                int nx=x+dx[j],ny=y+dy[j];
                if(0<=nx&&nx<H&&0<=ny&&ny<W&&col[nx][ny]==-1){
                    que.push(P(nx,ny));
                    bool V[4]={};
                    REP(l,dx.size()){
                        int gx=nx+dx[l],gy=ny+dy[l];
                        if(0<=gx&&gx<H&&0<=gy&&gy<W&&col[gx][gy]!=-1){
                            V[col[gx][gy]]=true;
                        }
                    }
                    REP(l,4) if(!V[l]){ 
                        col[nx][ny]=l;
                        break;
                    }
                }
            }
        }
    }

    REP(i,H){ 
        REP(j,W) cout<<t[col[i][j]];
        cout<<endl;
    }
}

