#include <iostream>

using namespace std;

int H, W, d;
short ct[510][510][5];
short matrix[510][510];

int myabs(int v) {
    if(v < 0) {
        return -v;
    }
    return v;
}

void solve(int x, int y) {
    if(x > W) {
        x = 1;
        y++;
    }
    if(y > H) {
        throw NULL;
    }

    for(int color = 1; color <= 4; color++) {
        if(ct[x][y][color]) continue;
        matrix[x][y] = color;

        bool invalid = false;

        for(int i = -d; i <= d; i++) {
            int cx = x + i;
            int cy1 = y + (d - myabs(i));
            int cy2 = y - (d - myabs(i));
            if(cx > 0) {
                if(cy1 > 0) {
                    ct[cx][cy1][color]++;
                    if(
                        ct[cx][cy1][1]
                        && ct[cx][cy1][2]
                        && ct[cx][cy1][3]
                        && ct[cx][cy1][4]
                    ) {
                        invalid = true;
                    }
                }
                if(cy2 > 0) {
                    ct[cx][cy2][color]++;
                    if(
                        ct[cx][cy2][1]
                        && ct[cx][cy2][2]
                        && ct[cx][cy2][3]
                        && ct[cx][cy2][4]
                    ) {
                        invalid = true;
                    }
                }
            }
        }

        if(!invalid) solve(x + 1, y);

        for(int i = -d; i <= d; i++) {
            int cx = x + i;
            int cy1 = y + (d - myabs(i));
            int cy2 = y - (d - myabs(i));
            if(cx > 0) {
                if(cy1 > 0) {
                    ct[cx][cy1][color]--;
                }
                if(cy2 > 0) {
                    ct[cx][cy2][color]--;
                }
            }
        }

        matrix[x][y] = 0;
    }
}

int main() {
    cin >> H >> W >> d;

    try {
