using namespace std;

int h, w, d;
char colors[4] = { 'R', 'Y', 'G', 'B' };

void geten(vector < vector<set<pair<int, int>>> >& ne) {
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			for (int k = 0; k <= d; k++) {
				int xd = k, yd = d - k;
				int x1 = i + xd, x2 = i - xd;
				int y1 = j + yd, y2 = j - yd;
				if (x1 >= 0 && x1 < h && y1 >= 0 && y1 < w) {
					ne[i][j].insert(make_pair(x1, y1));
				}
				if (x1 >= 0 && x1 < h && y2 >= 0 && y2 < w) {
					ne[i][j].insert(make_pair(x1, y2));
				}
				if (x2 >= 0 && x2 < h && y1 >= 0 && y1 < w) {
					ne[i][j].insert(make_pair(x2, y1));
				}
				if (x2 >= 0 && x2 < h && y2 >= 0 && y2 < w) {
					ne[i][j].insert(make_pair(x2, y2));
				}
			}
		}
	}
}

void dfs(vector<vector<bool>>& vi, vector<vector<char>>& ans, int x, int y,
	vector < vector<set<pair<int, int>>> >& ne) {
	set<pair<int, int>> us = ne[x][y];
	auto iter = us.begin();
	vi[x][y] = true;
	for (int i = 0; i < 4; i++) {
		bool found = true;
		while (iter != us.end()) {
			if (ans[iter->first][iter->second] == colors[i]) {
				found = false;
				break;
			}
			iter++;
		}
		if (found) {
			ans[x][y] = colors[i];
			break;
		}
	}
	iter = us.begin();
	while (iter != us.end()) {
		if (vi[iter->first][iter->second] == false) {
			dfs(vi, ans, iter->first, iter->second, ne);
		}
		iter++;
	}
}

int main() {
	cin >> h >> w >> d;
	vector < vector<set<pair<int, int>>> > ne(h, vector<set<pair<int, int>>>(w, set<pair<int, int>>()));
	geten(ne);
	vector<vector<char>> ans(h, vector<char>(w, 'W'));
	vector<vector<bool>> vi(h, vector<bool>(w, false));
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (vi[i][j] == false) {
				dfs(vi, ans, i, j, ne);
			}
		}
	}
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cout << ans[i][j];
		}
		cout << endl;
	}
}

