int zf[500+10][500+10];
int symbol[4]={0};
int H,W;
void ss(int row,int colomn)
{
	if(zf[row][colomn]=='R')
		symbol[0]=1;
	if(zf[row][colomn]=='Y')
		symbol[1]=1;
	if(zf[row][colomn]=='G')
		symbol[2]=1;
	if(zf[row][colomn]=='B')
		symbol[3]=1;
}
char dd(int num)
{
	if(num==0)
		return 'R';
	if(num==1)
		return 'Y';
	if(num==2)
		return 'G';
	if(num==3)
		return 'B';
}
void ddd(int now_row,int now_colomn,int distance)
{
	int	a_row=now_row+distance;
	int a_colomn=now_colomn+distance;
	for(int i=now_colomn;i<=a_colomn;i++,a_row--)
	{
		int row1,colomn1,row2,colomn2,row3,colomn3,row4,colomn4;
		row1=a_row;
		colomn1=i;
		row2=now_row*2-a_row;
		colomn2=i;
		row3=a_row;
		colomn3=now_colomn*2-i;
		row4=now_row*2-a_row;
		colomn4=now_colomn*2-i;
		if(row1>=1 && row1<=H && colomn1>=1 && colomn1<=W)
			ss(row1,colomn1);
		if(row2>=1 && row2<=H && colomn2>=1 && colomn2<=W)
			ss(row2,colomn2);
		if(row3>=1 && row3<=H && colomn3>=1 && colomn3<=W)
			ss(row3,colomn3);
		if(row4>=1 && row4<=H && colomn4>=1 && colomn4<=W)
			ss(row4,colomn4);
		for(int i=0;i<4;i++)
			if(symbol[i]==0)
				zf[now_row][now_colomn]=dd(i);
	} 
}
int main()
{
	memset(zf,-1,sizeof(zf));
	int K;
	scanf("%d %d %d",&H,&W,&K);
	for(int i=1;i<=H;i++)
	{
		for(int k=1;k<=W;k++)
		{
			memset(symbol,0,sizeof(symbol));
			ddd(i,k,K);
			printf("%c",zf[i][k]);
		 } 
		 printf("\n");
	}
	return 0;
}

