							ans[i + y][j + x] = c;
						}
					}
					else {
						FOR(j, -dd, dd + 2) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
