using namespace std;

int n, m, d;
uint8_t a[505][505];

inline int aps(int x) {
	return x < 0 ? -x : x;
}

inline bool valid(int i, int j) {
	for (int x=-d; x<=d; x++) {
		for (int y=-d; y<=d; y++) {

			int u = i+x;
			int v = j+y;

			if (aps(u-i) + aps(v-j) != d) {
				continue;
			}

			if (u >= 1 && v >= 1 && u <= n && v <= m) {
				if (a[u][v] == a[i][j]) {
					return false;
				}
			}
		}


	}
	return true;
}

vector<pair<int, int>> fig1, fig2;

inline bool ok(int i, int j) {
	return (i > 0 && j > 0 && i <= n && j <= m);
}

template<class T>
void crtaj(const T& fig, int x, int y, int c) {
	for (auto p : fig) {
		int u = p.first + x;
		int v = p.second + y;
		if (ok(u, v)) {
			a[u][v] = c;
		}
	}
}



int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	cerr.tie(nullptr);

	cin >> n >> m >> d;

	memset(a, 4, sizeof(a));

	if (d == 1) {
		for (int i=1; i<=n; i++) {
			for (int j=1; j<=m; j++) {
				a[i][j] = (i+j) % 2;
			}
		}
	} else {
		if (d % 2 == 1) {
			for (int x=-d-2; x<=d+2; x++) {
				for (int y=-d-2; y<=d+2; y++) {
					if (aps(x) + aps(y) <= d/2) {
						fig1.push_back({x, y});
					}

					if (aps(x) + aps(y) < d/2 ||
						aps(x-1) + aps(y) < d/2 ||
						aps(x) + aps(y-1) < d/2 ||
						aps(x-1) + aps(y-1) < d/2)
					{
						fig2.push_back({x, y});
					}
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=d) {
				for (int j=-4*d; j<=m+4*d; j+=d) {
					int c = (i/d + j/d + 16) % 2;
					crtaj(fig1, i, j, c);
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=d) {
				for (int j=-4*d; j<=m+4*d; j+=d) {
					int c = (i/d + j/d + 16) % 2;
					crtaj(fig2, i+d/2, j+d/2, 2 + c);
				}
			}

		} else {

			for (int x=-d-2; x<=d+2; x++) {
				for (int y=-d-2; y<=d+2; y++) {
					if (aps(x) + aps(y) < d/2 ||
						aps(x) + aps(y-1) < d/2)
					{
						fig1.push_back({x, y});
					}

					if (aps(x) + aps(y) < d/2 ||
						aps(x-1) + aps(y) < d/2)
					{
						fig2.push_back({x, y});
					}
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=2*d) {
				for (int j=-4*d; j<=m+4*d; j+=2*d) {

					crtaj(fig1, i, j, 0);
					crtaj(fig1, i+d, j+d, 0);

					crtaj(fig1, i+d-1, j, 1);
					crtaj(fig1, i+d+d-1, j+d, 1);


					crtaj(fig2, i+d/2-1, j+d/2+1, 2);
					crtaj(fig2, i-d/2-1, j-d/2+1, 2);

					crtaj(fig2, i+d/2-1, j+d/2+d, 3);
					crtaj(fig2, i-d/2-1, j-d/2+d, 3);

				}
			}
		}
	}

	bool invalid = false;

	// validate
	/*
	for (int i=1; i<=n; i++) {
		for (int j=1; j<=m; j++) {
			if (!valid(i, j)) {
				invalid = true;
			}
		}
	}
	*/

	if (invalid) {
		cerr << "invalid\n";
	}

	for (int i=1; i<=n; i++) {
		for (int j=1; j<=m; j++) {
			cout << "RGBY "[a[i][j]];
		}
		cout << '\n';
	}
}

