int n,m,d;
int mpp[1000][1000][4],As[1000][1000];
int main()
{
	scanf("%d%d%d",&n,&m,&d);
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			for(int k=0;k<4;k++)
			{
				if(!mpp[i][j][k])
				{
					As[i][j]=k;break;
				}
			}
			for(int k=0;k<=d;k++)
			{
				int mx=i+k,my=j+d-k;
				if(mx<1||mx>n||my<1||my>m) continue;
				mpp[mx][my][As[i][j]]=1;
			}
			for(int k=0;k<=d;k++)
			{
				int mx=i-k,my=j+d-k;
				if(mx<1||mx>n||my<1||my>m) continue;
				mpp[mx][my][As[i][j]]=1;
			}
			for(int k=0;k<=d;k++)
			{
				int mx=i+k,my=j-d+k;
				if(mx<1||mx>n||my<1||my>m) continue;
				mpp[mx][my][As[i][j]]=1;
			}
			for(int k=0;k<=d;k++)
			{
				int mx=i-k,my=j-d+k;
				if(mx<1||mx>n||my<1||my>m) continue;
				mpp[mx][my][As[i][j]]=1;
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			if(As[i][j]==0) putchar('R');
			else if(As[i][j]==2) putchar('B');
			else if(As[i][j]==1) putchar('G');
			else if(As[i][j]==3) putchar('Y');		
		}
		puts("");
	}
	return 0;
}

