using namespace std;

int powmp(long long x,long long n){
	const long long p = 1000000007;
	if(n==0) return 1;
	long long y = x%p;
	if(n==1) return y;
	long long tmp = (powmp(y,n/2))%p;
	if(n%2==0) return (tmp*tmp)%p;
	else return (powmp(y,n-1)*y)%p;
}

int col(int n){
	int t=n;
	if(t%2==0){
		return 0;
	}
	else if((t-1)%4==0){
		return 1;
	}
	else if((t-3)%8==0){
		return 2;
	}
	else return 3;
}

