vector<vector<int>> small(int n) {
  map<int,int> plus, minus;
  vector<vint> v(n, vint(n));
  REP(i,n) REP(j,n) {
    bool ok = false;
    REP(k,4) {
      int pp = i + j;
      int mp = i - j;
      if (((plus[pp + n] | plus[pp - n]) & (1 << k)) ||
	  ((minus[mp + n] | minus[mp - n]) & (1 << k))) continue;
      plus[pp] = plus[pp] | (1 << k);
      minus[mp] = minus[mp] | (1 << k);
      v[i][j] = k;
      ok = true;
      break;
    }
    if (!ok) {
      cout << "Fail " << i << ' ' << j << endl;
    }
  }

  // REP(i,n) pp(result[i]);
  return v;
}

