    memset(ok, 0, sizeof(ok));
    for(i = a; i <= b; i++) {
        int c1 = d + c - abs(l - i);
        int c2 = c + abs(l - i) - d;
        if(c1 >= 1 && c1 <= m && sol[i][c1] > -1)
            ok[sol[i][c1]] = 1;
        if(c2 >= 1 && c2 <= m && sol[i][c2] > -1)
            ok[sol[i][c2]] = 1;
    }
    vector <int> v;
    i = 0;
    while(i < 4) {
        if(ok[i] == 0)
            v.push_back(i);
        i++;
    }
    sol[l][c] = v[rand() % v.size()];
    for(i = a; i <= b; i++) {
        int c1 = d + c - abs(l - i);
        int c2 = c + abs(l - i) - d;
        if(c1 >= 1 && c1 <= m && sol[i][c1] == -1)
            dfs(i, c1);
        if(c2 >= 1 && c2 <= m && sol[i][c2] == -1)
            dfs(i, c2);
    }
}

