        rec(l - i, r - (d - i), (x + 1) % 4);
    }
    for (int i = 0; i <= d; i++) {
        rec(l - i, r + (d - i), (x + 1) % 4);
    }
    for (int i = 0; i <= d; i++) {
        rec(l + i, r - (d - i), (x + 1) % 4);
    }
    for (int i = 0; i <= d; i++) {
        rec(l + i, r + (d - i), (x + 1) % 4);
    }
}

