    // input
    int h, w, d; scanf("%d%d%d", &h, &w, &d);

    // solve
    auto f = solve(h, w, d);

    // output
    repeat (y, h) {
        repeat (x, w) {
            printf("%c", ".RYGB"[f[y][x]]);
        }
        printf("\n");
    }
    return 0;
}

