int DFS(int i, int j)
{
	if (j == W)
		return DFS(i + 1, 0);
	if (i == H)
		return 1;
	int used[4] = {0, 0, 0, 0};
	for (int ii = 0; ii <= i; ii ++)
	{
		int dd = d - (i - ii);
		if (dd < 0) continue;
		int jj;

		jj = j - dd;
		if (0 <= j && j < W)
			if (ii != i || jj < j) used[C[ii][jj]] = 1;
		jj = j + dd;
		if (0 <= j && j < W)
			if (ii != i || jj < j) used[C[ii][jj]] = 1;
	}
	for (int cc = 0; cc < 4; cc ++)
		if (! used[cc])
		{
			C[i][j] = cc;
			if (DFS(i, j + 1))
				return 1;
		}
	return 0;
}

