void solveodd(int H, int W, int d){
    d = d/2;
    vector<string> c(H);
    for(int i=0; i<H; i++){
        string s = "";
        for(int j=0; j<W; j++) s += "*";
        c[i] = s;
    }

    vector<pair<int, int>> rygb[4];
    for(int i=-H; i<=H; i++){
        for(int j=-W; j<=W; j++){
            int y = i*(d-1)+j*d;
            int x = i*d-j*(d-1);
            if(x<-d||x>W+d||y<-d||y>H+d) continue;
            if((i+2*H)%2==0&&(j+2*W)%2==0) rygb[0].push_back(make_pair(y, x));
            else if((i+2*H)%2==0&&(j+2*W)%2==1) rygb[1].push_back(make_pair(y, x));
            else if((i+2*H)%2==1&&(j+2*W)%2==0) rygb[2].push_back(make_pair(y, x));
            else if((i+2*H)%2==1&&(j+2*W)%2==1) rygb[3].push_back(make_pair(y, x));
        }
    }

    string RYGB = "RYGB";
    for(int k=0; k<4; k++){
        for(auto p : rygb[k]){
            for(int i=-d+1; i<d; i++){
                for(int j=-d+1; j<d; j++){
                    if(abs(i)+abs(j)>=d) continue;
                    int y = p.first+i;
                    int x = p.second+j;
                    if(x < 0 || x >= W || y < 0 || y >= H) continue;
                    c[y][x] = RYGB[k];
                }
            }
        }
    }

    for(int i=0; i<H; i++)
        cout << c[i] << endl;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H, W, d;
    cin >> H >> W >> d;

    if(d%2==1){
        solveodd(H, W, d);
        return 0;
    }

    vector<string> c(H);
    for(int i=0; i<H; i++){
        string s = "";
        for(int j=0; j<W; j++) s += "*";
        c[i] = s;
    }

    vector<pair<int, int>> rygb[4];
    for(int i=-H; i<=H; i++){
        for(int j=-W; j<=W; j++){
            int y = i*(-1)+j*d;
            int x = i*(2*d-2)+j*d;
            if(x<-4*d||x>W+4*d||y<-4*d||y>H+4*d) continue;
            rygb[0].push_back(make_pair(y, x));
            rygb[1].push_back(make_pair(y-(d-1), x+d));
            rygb[2].push_back(make_pair(y+1, x+d));
            rygb[3].push_back(make_pair(y+1, x+d-1));
        }
    }

    string RYGB = "RYGB";
    for(auto p : rygb[0]){
        for(int i=0; i<d; i++){
            int tmp = min(abs(i), abs(i-(d-1)));
            for(int j=-tmp; j<=tmp; j++){
                int y = p.first+j;
                int x = p.second+i;
                if(x < 0 || x >= W || y < 0 || y >= H) continue;
                c[y][x] = 'R';
            }
        }
    }

    for(auto p : rygb[2]){
        for(int i=0; i<d; i++){
            int tmp = min(abs(i), abs(i-(d-1)));
            for(int j=-tmp; j<=tmp; j++){
                int y = p.first+j;
                int x = p.second+i;
                if(x < 0 || x >= W || y < 0 || y >= H) continue;
                c[y][x] = 'G';
            }
        }
    }

    for(auto p : rygb[1]){
        for(int i=0; i<d; i++){
            int tmp = min(abs(i), abs(i-(d-1)));
            for(int j=-tmp; j<=tmp; j++){
                int y = p.first+i;
                int x = p.second+j;
                if(x < 0 || x >= W || y < 0 || y >= H) continue;
                c[y][x] = 'Y';
            }
        }
    }

    for(auto p : rygb[3]){
        for(int i=0; i<d; i++){
            int tmp = min(abs(i), abs(i-(d-1)));
            for(int j=-tmp; j<=tmp; j++){
                int y = p.first+i;
                int x = p.second+j;
                if(x < 0 || x >= W || y < 0 || y >= H) continue;
                c[y][x] = 'B';
            }
        }
    }


    for(int i=0; i<H; i++)
        cout << c[i] << endl;
    return 0;
}

#include <bits/stdc++.h>
#define INT long long
#define oo 987654321
using namespace std;
INT n, m, d, mp[550][550], chk[550][550], col;
char color[10] = " RYGB";
inline bool valid(int x, int y)
{
    return (0<=x&&x<n and 0<=y&&y<m);
}
void solve(int x, int y, int z)
{
    mp[x][y] = z+1;
    chk[x][y] = 1;
    for(int i = 0 ; i <= d ; i++ )
    {
        int j = d-i;
        if( valid(x+i, y+j) and chk[x+i][y+j] == 0 )
            solve(x+i, y+j, (z+1)%4);
        if( valid(x-i, y+j) and chk[x-i][y+j] == 0 )
            solve(x-i, y+j, (z+1)%4);
        if( valid(x+i, y-j) and chk[x+i][y-j] == 0 )
            solve(x+i, y-j, (z+1)%4);
        if( valid(x-i, y-j) and chk[x-i][y-j] == 0 )
            solve(x-i, y-j, (z+1)%4);
    }
    chk[x][y] = 0;
}
int main()
{
	ios::sync_with_stdio(false);
    cin>>n>>m>>d;
    for(int i = 0 ; i < n ; i++ )
        for(int j = 0 ; j < m ; j++ )
            if( mp[i][j] == 0 ) solve(i, j, 0);
    for(int i = 0 ; i < n ; i++, cout<<endl )
        for(int j = 0 ; j < m ; j++)
            cout<<color[mp[i][j]];
    return 0;
}

