int setColor(int h, int w) {
	if (HW[h][w].color>0) return HW[h][w].color;

	int ncolor = HW[h][w].ncolor;
	if (!(ncolor&0x01)) return 1;
	if (!(ncolor&0x02)) return 2;
	if (!(ncolor&0x04)) return 3;
	if (!(ncolor&0x08)) return 4;
}


void setnColor(int h, int w, int color) {
	int down, right;
	for (down = 0; down <= d; down++) {
		right = d - down;
		int nw = w+right;
		int nh = h+down;
		if (nh<=H && nw<=W) {
			HW[nh][nw].ncolor |= (1<<(color-1));
		}
		nw = w-right;
		if (nh<=H && 0<nw) {
			HW[nh][nw].ncolor |= (1<<(color-1));
		}
	}
}

