					if (j + d < w && dpc[i][j + d] < 4 && ((((dp[i][j + d]) >> k) & 1) == 0)) {
						// printf("%d, %d\n", i, j + d);
						dpc[i][j + d]++;
						dp[i][j + d] = dp[i][j + d] | (1 << k);
					}
					if (j + d >= 0 && dpc[i][j - d] < 4 && ((((dp[i][j - d]) >> k) & 1) == 0)) {
						dpc[i][j - d]++;
						dp[i][j - d] = dp[i][j - d] | (1 << k);
					}
					if (i + d < h && dpc[i + d][j] < 4 && ((((dp[i + d][j]) >> k) & 1) == 0)) {
						dpc[i + d][j]++;
						dp[i + d][j] = dp[i + d][j] | (1 << k);
					}
					if (i - d >= 0 && dpc[i - d][j] < 4 && ((((dp[i - d][j]) >> k) & 1) == 0)) {
						dpc[i - d][j]++;
						dp[i - d][j] = dp[i - d][j] | (1 << k);
					}
					for (size_t kx = 1; kx < d; kx++) {
						int ky = d - kx;
						if (i + ky < h && j + kx < w && dpc[i + ky][j + kx] < 4 && ((((dp[i + ky][j + kx]) >> k) & 1) == 0)) {
							dpc[i + ky][j + kx]++;
							dp[i + ky][j + kx] = dp[i + ky][j + kx] | (1 << k);
						}
						if (i - ky >= 0 && j - kx >= 0 && dpc[i - ky][j - kx] < 4 && ((((dp[i - ky][j - kx]) >> k) & 1) == 0)) {
							dpc[i - ky][j - kx]++;
							dp[i - ky][j - kx] = dp[i - ky][j - kx] | (1 << k);
						}
						if (i - ky >= 0 && j + kx < w && dpc[i - ky][j + kx] < 4 && ((((dp[i - ky][j + kx]) >> k) & 1) == 0)) {
							dpc[i - ky][j + kx]++;
							dp[i - ky][j + kx] = dp[i - ky][j + kx] | (1 << k);
						}
						if (i + ky < h && j - kx >= 0 && dpc[i + ky][j - kx] < 4 && ((((dp[i + ky][j - kx]) >> k) & 1) == 0)) {
							dpc[i + ky][j - kx]++;
							dp[i + ky][j - kx] = dp[i + ky][j - kx] | (1 << k);
						}
					}
				}
			}
		}
		if (change == 0) {
			// cout << "nochange" << endl;
			bool ok = false;
			for (size_t i = 0; i < h && !ok; i++) {
				for (size_t j = 0; j < w; j++) {
