						dp[i][j] = k;
						dpc[i][j] = 3;
						ok = true;
						break;
					}
				}
			}
		}
	}
	for (size_t i = 0; i < h; i++) {
		for (size_t j = 0; j < w; j++) {
			cout << "RYGB"[a[i][j]];
		}
		cout << endl;
	}
}

