constexpr int INF = 1e9;

int main() {
    int H, W, d;
    cin >> H >> W >> d;
    int R = 1, Y = 1 << 1, G = 1 << 2, B = 1 << 3;
    string color = "RYGB";
    vector<vector<int>> c(H, vector<int>(W, (1 << 4) - 1));
    c[0][0] = R;
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(__builtin_popcount(c[i][j]) != 1) {
                vector<int> cnt(4, INF);
                for(int k = 0; k < 4; ++k) {
                    if((c[i][j] >> k) & 1) {
                        cnt[k] = 0;
                    }
                }
                int mask = c[i][j];
                for(int dx = 0; dx <= d; ++dx) {
                    for(int f1 = -1; f1 <= 1; f1 += 2) { for(int f2 = -1; f2 <= 1; f2 += 2) {

                        int ny = i + f1 * (d - dx);
                        int nx = j + f2 * dx;
                        if(0 <= ny && ny < H && 0 <= nx && nx < W) {
                            mask &= ~c[ny][nx];
                            for(int k = 0; k < 4; ++k) {
                                if((c[ny][nx] >> k) & 1) {
                                    cnt[k]++;
                                }
                            }
                        }
                    }}
                }
                if(mask == 0) {
                    int idx = 0, mi = INF;
                    for(int k = 0; k < 4; ++k) {
                        if(cnt[k] < INF && mi > cnt[k]) {
                            idx = k;
                            mi = cnt[k];
                        }
                    }
                    c[i][j] = (1 << idx);
                } else {
                    for(int k = 0; k < 4; ++k) {
                        if((mask >> k) & 1) {
                            c[i][j] = (1 << k);
                            break;
                        }
                    }
                }
            }
            for(int dx = 0; dx <= d; ++dx) {
                int dy = d - dx;
                int mask2 = ((1 << 4) - 1) & (~c[i][j]);
                if(i - dy >= 0 && j - dx >= 0) {
                    c[i - dy][j - dx] &= mask2;
                }
                if(i - dy >= 0 && j + dx < W) {
                    c[i - dy][j + dx] &= mask2;
                }
                if(i + dy < H && j - dx >= 0) {
                    c[i + dy][j - dx] &= mask2;
                }
                if(i + dy < H && j + dx < W) {
                    c[i + dy][j + dx] &= mask2;
                }
            }
        }
    }

    vector<vector<char>> res(H, vector<char>(W, '$'));
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            for(int k = 0; k < 4; ++k) {
                if((c[i][j] >> k) & 1) {
                    res[i][j] = color[k];
                    break;
                }
            }
            assert(res[i][j] != '$');
        }
    }

    for(auto& s : res) {
        for(auto c : s) {
            cout << c;
        }
        cout << endl;
    }
}

