    rep(i, d + 1) {
        ns.push_back({i, d - i});
        if (i) ns.push_back({-i, d - i});
        if (d - i) ns.push_back({i, -(d - i)});
        if (i && (d - i)) ns.push_back({-i, -(d - i)});
    }

    tb[0][0] = 1;
    int count = 1;

    auto in_rng = [&](int x, int y) {
        return x >= 0 && y >= 0 && x < h && y < w;
    };
    while (count) {
        count = 0;
        rep(i, h) rep(j, w) {
            if (tb[i][j] == 0) {
                for (int k = 1; k < 5; k++) {
                    if (std::all_of(
                            ns.begin(), ns.end(),
                            [&](const std::pair<int, int> n) {
                                return !in_rng(i + n.first, j + n.second) ||
                                       tb[i + n.first][j + n.second] != k;
                            })) {
                        tb[i][j] = k;
                        count++;
                        break;
                    }
                }
            }
        }
    }

    rep(i, h) {
        rep(j, w) {
            std::cout << (tb[i][j] == 1
