inline int uniquecolor(node n){
    vi::iterator it;
    vi vec(n.color_no);
    if(find(vec.bg, vec.ed, 0)==vec.ed){
        return 0;
    }
    if(find(vec.bg, vec.ed, 1)==vec.ed){
        return 1;
    }
    if(find(vec.bg, vec.ed, 2)==vec.ed){
        return 2;
    }
    if(find(vec.bg, vec.ed, 3)==vec.ed){
        return 3;
    }
}

