int kol2(int a,int b,int d){
  a += d * 10000;
  b += d * 10000;
  return 2 * ((a / d) % 2) + ((b / d) % 2) ; 
}

int kol(int a,int b,int d){
  if(d & 1){
    return (a + b) & 1;
  }else{
    if((a + b) & 1){
      a--;
    }
    return kol2((a+b) >> 1, (a - b) >> 1,d/2);
  }

}

