	for(int i=0;i<h;i++) {
		for(int j=0;j<w;j++) {
			int st = i - d;
			st = (st < 0) ? 0 : st;
			memset(vis, 0, sizeof(vis));
			for(int k=st;k<=i;k++) {
				int t = i - k;
