int sign[] = {0, 1, 1, -1, -1};
int signC[] = {0, -1, 1, -1, 1};

int wasted;

void pune(int i, int j, int x)
{
    int addL, nl, nc;
    for(addL = 0; addL <= d; addL ++)
    {
        int l = addL;
        int c = d - addL;

        for(int h = 1; h <= 4; h ++)
        {
            nl = i + l * sign[h];
            nc = j + c * signC[h];

            if(nl >= 1 && nl <= n && nc >= 1 && nc <= m)
                pos[nl][nc][x] = 1;

           // else
            //    wasted ++;
        }
    }

}

