{
    return v[nr];
}

int cul[5];

void mix()
{
    int i;
    for(i = 1; i <= 4; i ++)
    {
        int poz = rand() % 4 + 1;

        int aux = cul[poz];
        cul[poz] = cul[i];
        cul[i] = aux;
    }
}

void do2()
{


    int i, j, h;
    for(i = 1; i <= n; i ++)
    {
        for(j = 1; j <= m; j ++)
        {
            for(h = 1; h <= 4; h ++)
            {
                pos[i][j][h] = 0;
                a[i][j] = 0;
            }
        }
    }

    for(i = 1; i <= n; i ++)
    {
        for(j = 1; j <= m; j ++)
        {
            for(h = 1; h <= 4; h ++)
            {
                if(pos[i][j][h] == 0)
                {
                    pune(i, j, h);

                    a[i][j] = h;

                    break;
                }
            }
        }
    }


    for(i = 1; i <= n; i ++)
    {
        for(j = 1; j <= m; j ++)
        {
            printf("%c", charul(a[i][j]));
        }

        printf("\n");
    }
}

