int h, w, d;
void dfs(int i, int j, int col){
    if(ans[i][j] != 0) return;
    ans[i][j] = col;

    for(int k=0; k<h; k++){
        for(int l=0; l<w; l++){
            if(adj[i*h+j][k*h+l] == 1){
                if(col == 1){
                    ans[k][l] = 2;
                    dfs(k, l, 2);
                }else{
                    ans[k][l] = 1;
                    dfs(k, l, 1);
                }

            }
        }
    }
}

