//http://shogo82148.github.io/homepage/memo/geometry/circle-cross.html
vector<Point> circle_cross(Point A,double RA,Point B,double RB){
	Point C = B-A;
	double CC = C.dot(C);
	double ter = (CC+RA*RA-RB*RB)/2;
	double D = CC * RA * RA - ter * ter;
	D = sqrt(D);

	vector<Point> ans(2);
	ans[0].x = (ter*C.x+C.y*D)/CC;
	ans[0].y = (ter*C.y-C.x*D)/CC;
	ans[1].x = (ter*C.x-C.y*D)/CC;
	ans[1].y = (ter*C.y+C.x*D)/CC;
	ans[0] += A;
	ans[1] += A;
	if( ans[0] == ans[1] ){
		ans.resize(1);
		return ans;
	}
	if( ans[0] > ans[1] ){
		swap( ans[0],ans[1] );
	}
	return ans;
}
