void solve(){
	int H,W,D;
	cin >> H >> W >> D;
	vector< vector<int> > fld(H,vector<int>(W,-1) );
	if( D&1 ){
		for(int h=0;h<H;++h){
			for(int w=0;w<W;++w){
				fld[h][w] = (h+w)%2;
			}
		}
	}else{//dが偶数
		int c = 0;
		vector<bool> hist(4,false);
		for(int h=0;h<H;++h){
			for(int w=0;w<W;++w){
				hist.assign(4,false);
				int hh,ww;
				for(int k=0;k<=D;++k){
					hh = h-D+k;
					ww = w+k;
					if( hh<0 || H <= hh )continue;
					if( ww<0 || W <= ww )continue;
					if( fld[hh][ww] != -1 ){
						hist[ fld[hh][ww] ] = true;
					}
				}
				for(int k=0;k>=-D;--k){
					hh = h-D -k;
					ww = w+k;
					if( hh<0 || H <= hh )continue;
					if( ww<0 || W <= ww )continue;
					if( fld[hh][ww] != -1 ){
						hist[ fld[hh][ww] ] = true;
					}
				}
				for(int k=0;k<4;++k){
					int res = (c+1+k)%4;
					if( hist[ res ] == false ){
						fld[h][w] = res;
						c = res;
						break;
					}
				}
			}
		}
	}
	string word = "RGBY";
	for(int h=0;h<H;++h){
		for(int w=0;w<W;++w){
			cout << word[ fld[h][w] ];
		}
		cout << "\n";
	}
	cout << flush;
}

