				}
			} else {
				if (i % d < d / 2) {
					if (d / 2 - 1 - i % (d / 2) < j % d && j % d <= d / 2 + i % (d / 2)) {
						if (j % (d + d) < d) pat[i][j] = 'B';
						else pat[i][j] = 'R';
					}
					else {
						if (j % (d + d) < d / 2 || j % (d + d) >= d + d / 2) pat[i][j] = 'Y';
						else pat[i][j] = 'G';
					}
				} else {
					if ((i % d - d / 2) < j % d && j % d <= d - 1 - (i % d - d / 2)) {
						if (j % (d + d) < d) pat[i][j] = 'B';
						else pat[i][j] = 'R';
					}
					else {
						if (j % (d + d) < d / 2 || j % (d + d) >= d + d / 2) pat[i][j] = 'G';
						else pat[i][j] = 'Y';
					}
				}
			}
		}
	}

	auto check = [&]() {
		for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
			for (int ii = 0; ii < n; ii++) for (int jj = 0; jj < m; jj++) {
				if (abs(i - ii) + abs(j - jj) == d) {
					assert(pat[i][j] != pat[ii][jj]);
				}
			}
		}
	};

//	check();

	for (int i = 0; i < n; i++, cout << "\n") for (int j = 0; j < m; j++) cout << pat[i][j];

	return 0;
}

