int main(void) {
	scanf("%d%d%d", &n, &m, &d);
	for (int i = -510; i <= 510; i += d) {
		c1 ^= 1;
		for (int j = -510; j <= 510; j++) {
			if (i + j < 0 || i - j < 0) continue;
			p1 = i + j >> 1;
			p2 = i - j >> 1;
			for (int x = 0; x < d; x++)
				for (int y = 0; y < d; y++) {
					c2 ^= 1; c = ch[c1 << 1 | c2];
					ans[p1 + x][p2 + y] = c;
				}
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++)
			putchar(ans[i][j]);
		putchar('\n');
	}
	return 0;
}

