bool used[502][502];
ll col[502][502];


ll h, w, d;

void dfs(int x, int y) {
	used[x][y] = 1;
	set<ll> s;

	for (int j = 0; j < w; j++) {
		ll dist = abs(x - j);
		if (dist > d) continue;

		ll need = (d - dist);
		ll y1 = y - need, y2 = y + need;
		if (y1 >= 0) {
			s.insert(col[j][y1]);
		}
		if (y2 < w) {
			s.insert(col[j][y2]);
		}
	}

	for (int j = 1; j <= 4; j++) {
		if (s.find(j) == s.end()) {
			col[x][y] = j;
			break;
		}
	}

	for (int j = 0; j < w; j++) {
		ll dist = abs(x - j);
		if (dist > d) continue;

		ll need = (d - dist);
		ll y1 = y - need, y2 = y + need;
		if (y1 >= 0) {
			if (!used[j][y1]) dfs(j, y1);
		}
		if (y2 < w) {
			if (!used[j][y2]) dfs(j, y2);
		}
	}


}

