struct Colors {
    bool r, y, g, b;
    bool done;
    bool pushed;

    Colors() : r(true), y(true), g(true), b(true), done(false), pushed(false) {}
};

Colors colors[510][510];
int H, W, d;
char ans[510][510];
queue<pii> que;

//col:r0 y1 g2 b3
void allD(int y, int x, int col) {
    for (int h = y - d; h <= y + d; ++h) {
        if (h < 0)continue;
        if (h >= H)continue;
        int w1 = x + d - abs(h - y);
        if (0 <= w1 && w1 < W) {
            if (!colors[h][w1].pushed) {
                colors[h][w1].pushed = true;
                que.push(pii(h, w1));
            }
            if (col == 0) {
                //r
                colors[h][w1].r = false;
            } else if (col == 1) {
                //y
                colors[h][w1].y = false;
            } else if (col == 2) {
                //g
                colors[h][w1].g = false;
            } else if (col == 3) {
                //b
                colors[h][w1].b = false;
            }
        }
        w1 = x - d + abs(h - y);
        if (0 <= w1 && w1 < W) {
            if (!colors[h][w1].pushed) {
                colors[h][w1].pushed = true;
                que.push(pii(h, w1));
            }
            if (col == 0) {
                //r
                colors[h][w1].r = false;
            } else if (col == 1) {
                //y
                colors[h][w1].y = false;
            } else if (col == 2) {
                //g
                colors[h][w1].g = false;
            } else if (col == 3) {
                //b
                colors[h][w1].b = false;
            }
        }
    }
}

void f() {
    while (!que.empty()) {
        pii p = que.front();
        que.pop();
        int y = p.FI;
        int x = p.SE;
        Colors &c = colors[y][x];

        if (c.done)continue;
        c.done = true;


        if (c.r) {
            ans[y][x] = 'R';
            allD(y, x, 0);
        } else if (c.y) {
            ans[y][x] = 'Y';
            allD(y, x, 1);
        } else if (c.g) {
            ans[y][x] = 'G';
            allD(y, x, 2);
        } else if (c.b) {
            ans[y][x] = 'B';
            allD(y, x, 3);
        }

    }
}

signed main() {
    srand((unsigned int) time(NULL));
    cin >> H >> W >> d;
    if (d % 2 == 0)assert(0);
    ans[0][0] = 'R';
    colors[0][0].done = true;
    colors[0][0].pushed = true;
    allD(0, 0, 0);
    for (;;) {
        x:
        f();
        rep(i, H) {
            rep(j, W) {
                Colors c = colors[i][j];
                if (!c.done) {
                    c.done = true;
                    c.pushed = true;
                    ans[i][j] = 'R';
                    allD(i, j, 0);
                    if (!que.empty()) {
                        goto x;
                    }
                }
            }
        }
        if (que.empty())break;
    }
    rep(i, H) {
        rep(j, W) {
            cout << ans[i][j];
        }
        cout << endl;
    }
}

