			if(ans[i][j]=='*' and i-unit>=0 and j+unit <w){
				if(ans[i-unit][j+unit]=='R') ans[i][j]='B';
				if(ans[i-unit][j+unit]=='G') ans[i][j]='Y';
				if(ans[i-unit][j+unit]=='Y') ans[i][j]='G';
				if(ans[i-unit][j+unit]=='B') ans[i][j]='R';
			}

			if(ans[i][j]=='*') ans[i][j]='R';
		}
	}

	rep(i,h){
		rep(j,w) cout << ans[i][j];
		cout << endl;
	}


	return 0;
}

