void encolor(int x, int y, int c) {
	for (int i = 0; i < d / 2; ++i) {
		for (int j = -i; j <= i; ++j) {
			pair <int, int> pos = {x + i, y + j};
			assert(!table.count(pos));
			table[pos] = c;
		}
	}
	for (int i = d / 2 - 1; i >= 0; --i) {
		for (int j = -i; j <= i; ++j) {
			pair <int, int> pos = { x + d / 2 + (d / 2 - i - 1), y + j };
			assert(!table.count(pos));
			table[pos] = c;
		}
	}
}

