	memset( a, -1, sizeof(a) );
	if( d & 1 ) solve_odd();
	else solve_even();
	for( int i = 1; i <= n; ++i, puts("") )
		for( int j = 1; j <= m; ++j )
			putchar( c[a[i][j]] );
	return 0;
}

