	if (d % 2) {
		for (int i = 0; i < v.size(); i++) {
			for (int j = 0; j < v[i].size(); j++) {
				v[i][j] = (i + j) % 4 + 'a';
			}
		}
	}

	else if (d % 6) {
		for (int i = 0; i < v.size(); i++) {
			for (int j = 0; j < v[i].size(); j++) {
				v[i][j] = (j + 2 * (i % 2)) % 4 + 'a';
			}
		}
	}

	else {
		if (n >= d and k >= d) {
			vector <int> (1000000000, 4);

		}

		if (n >= d) {
			swap(n, k);
			reversed = true;
		} 

		v = vector <vector <char> > (n + 10, vector <char> (k  + 10));

		int a1 = 0, b1 = 0;
		int a2 = d/2, b2 = d / 2;

		char t1 = 'a', t2 = 'b';	
		for (int j = 0; j < k; j++) {
			for (int i = 0; i < n; i++) {
				if (i == 0 and j == b1 + d) {
					b1 = j;
