                //    if((c[i][j] >> k) & 1) {
                //        cnt[k] = INF;
                //    }
                //}
                int mask = c[i][j];
                for(int dx = 0; dx <= d; ++dx) {
                    for(int f1 = -1; f1 <= 1; f1 += 2) { for(int f2 = -1; f2 <= 1; f2 += 2) {

                        int ny = i + f1 * (d - dx);
