//--------------8---------------->> coding space <<-----------------8-------------//

int H, W, d;
int col[555][555], dame[555][555];

void solve() {
	minit(col, -1);
	minit(dame, 0);

	for_(y,0,H) for_(x,0,W) {
		for_(c,0,4) {
			if (dame[y][x] >> c & 1) continue;
			col[y][x] = c;

			for_(i,-d,1) {
				int dx = -d - i, dy = i;
				if (in_range(x+dx, 0, W) && in_range(y+dy, 0,H)) dame[y+dy][x+dx] |= (1 << c);
				dy = d - abs(i);
				if (in_range(x+dx, 0, W) && in_range(y+dy, 0,H)) dame[y+dy][x+dx] |= (1 << c);
			}

			for_(i,0,d+1) {
				int dx = d - i, dy = i;
				if (in_range(x+dx, 0, W) && in_range(y+dy, 0,H)) dame[y+dy][x+dx] |= (1 << c);
				dx = -d + i;
				if (in_range(x+dx, 0, W) && in_range(y+dy, 0,H)) dame[y+dy][x+dx] |= (1 << c);
			}

			break;
		}
	}

	string cs = "RGBY";
	for_(y,0,H) for_(x,0,W) cout << cs[col[y][x]] << (x < W-1 ? "" : "\n");
}

int main() {
	cin >> H >> W >> d;
	solve();
}
