struct Data {
  int x,y,deg;
  bool operator < ( const Data & data ) const {
    if( deg != data.deg ) return deg < data.deg;
    if( x != data.x ) return x > data.x;
    return y > data.y;
  }
};

int h,w,d;
char c[510][510];

void compute() {
  priority_queue<Data> Q;
  rep(i,h) {
    rep(j,w) {
      Data data;
      data.x = j, data.y = i;
      data.deg = 0;
      if( j-d >= 0 ) data.deg += ( min(h-1,i+d) - max(0,i-d) + 1 );
      if( i-d >= 0 ) data.deg += ( min(w-1,j+d) - max(0,i-d) + 1 );
      if( i+d <  h ) data.deg += ( min(w-1,j+d) - max(0,i-d) + 1 );
      if( j+d <  w ) data.deg += ( min(h-1,i+d-1) - max(0,i-d+1) + 1 );
      /*
      for(int y=max(0,i-d);y<=min(h-1,i+d);++y) {
	++data.deg;
      }
      for(int x=max(0,j-d+1);x<=min(w-1,j+d);++x) {
	if( i-d >= 0 ) ++data.deg;
	if( i+d < h ) ++data.deg;
      }
      for(int y=max(0,i-d+1);y<=min(h-1,i+d-1);++y) {
	++data.deg;
      }
      */

      Q.push(data);
    }
  }
  rep(i,h) rep(j,w) c[i][j] = '$';
  while( !Q.empty() ) {
    Data data = Q.top(); Q.pop();
    int i = data.y, j = data.x;
    unordered_set<char> S;
    if( j-d >= 0 ) {
      for(int y=max(0,i-d);y<=min(h-1,i+d);++y) {
	S.insert(c[y][j-d]);
      }
    }

    for(int x=max(0,j-d+1);x<=min(w-1,j+d);++x) {
      if( i-d >= 0 ) {
	S.insert(c[i-d][x]);
      }
      if( i+d < h ) {
	S.insert(c[i+d][x]);
      }
    }
    if( j+d < w ) {
      for(int y=max(0,i-d+1);y<=min(h-1,i+d-1);++y) {
	S.insert(c[y][j+d]);
      }    
    }
    rep(k,4) {
      if( S.count(base[k]) == 0 ) {
	c[data.y][data.x] = base[k];
	break;
      }
    }
  }
  rep(i,h) {
    rep(j,w) {
      cout << c[i][j];
    }
    puts("");
  }
}

int main(){
  cin >> h >> w >> d;
  compute();
  return 0;
}

