void dfs(int x,int y)
{
	for (int i=max(1,x-d);i<=min(h,x+d);i++)
	{
		int j=y-(d-abs(i-x));
		if (j>=1 && ditu[i][j]==0)
			for (int k=1;k<=4;k++)
			{
				bool flag=true;
				for (int p=max(1,i-d);p<=min(h,i+d);p++)
					for (int q=max(1,j-d);q<=min(w,j+d);q++)
				if (abs(p-i)+abs(q-j)==d) if (k==ditu[p][q]) {p=h+1;q=w+1;flag=false;}
				if (flag) {
				ditu[i][j]=k;
				dfs(i,j);
				};
			};	
		j=y+(d-abs(i-x));
		if (j<=w && ditu[i][j]==0)
			for (int k=1;k<=4;k++)
			{
				bool flag=true;
				for (int p=max(1,i-d);p<=min(h,i+d);p++)
					for (int q=max(1,j-d);q<=min(w,j+d);q++)
				if (abs(p-i)+abs(q-j)==d) if (k==ditu[p][q]) {p=h+1;q=w+1;flag=false;}
				if (flag) {
				ditu[i][j]=k;
				dfs(i,j);
				};
			};	
	}
	return;
}
