int chk(int x, int y) {
	return 1 <= x && x <= h && 1 <= y && y <= w;
} 

int id[MaxN][MaxN], in, col[MaxN * MaxN];

vector<int> e[MaxN * MaxN];

void ins(int u, int v) {
	e[u].push_back(v);
	e[v].push_back(u);
} 

bool bfs(int x) {
	queue<int> q;
	q.push(x); col[x] = 1;
	while(!q.empty()) {
		int c = q.front(); q.pop();
		for(auto y : e[c]) {
			if(!~col[y]) {
				q.push(y);
				col[y] = !col[c];
			}
			if(col[y] == col[c]) 
				return 0;
		}
	}
	return 1;
}

