					int c = d - k;
					if(chk(i + k, j - c)) ins(id[i][j], id[i + k][j - c]);
					if(chk(i - k, j + c)) ins(id[i][j], id[i - k][j + c]);
					if(chk(i - c, j + k)) ins(id[i][j], id[i - c][j + k]);
					if(chk(i + c, j - k)) ins(id[i][j], id[i + c][j - k]);

					if(chk(i + k, j + c)) ins(id[i][j], id[i + k][j + c]);
					if(chk(i - k, j - c)) ins(id[i][j], id[i - k][j - c]);
					if(chk(i + c, j + k)) ins(id[i][j], id[i + c][j + k]);
					if(chk(i - c, j - k)) ins(id[i][j], id[i - c][j - k]);
