int H, W, d;

int main(){
  cin >> H >> W >> d;
  int epoch = -2;
  bool eadd = true;
  for(int i=0;i<H;++i){
    int cnt = 0;
    if(eadd){
      epoch += 2;
      if(epoch >= d-1 ){
	eadd = false;
      }
    }else{
      epoch -=2;
      if(epoch <= 1){
	eadd = true;
      }
    }
    for(int j=0;j<epoch/2;++j){
      cout<<"G";
    }
    cnt = epoch/2;
    int gen = 0;
    while(true){
      if(gen%2==0){

	for(int j=0;j<min((W-cnt),d-epoch);++j){
	  cout<<"R";
	}
	cnt+=min((W-cnt),d-epoch);

	for(int j=0;j<min((W-cnt),epoch);++j){
	  cout<<"B";  
	}
	cnt += min((W-cnt),epoch);
      }else{
	for(int j=0;j<min((W-cnt),d-epoch);++j){
	  cout<<"Y";
	}
	cnt+=min((W-cnt),d-epoch);
	for(int j=0;j<min((W-cnt),epoch);++j){
	  cout<<"G";
	}
	cnt +=min((W-cnt),epoch);
      }
      if(cnt == W){cout<<endl;break;}
      gen++;
    }
  }
  return 0;
}

