    int r = (d - 1) / 2;

    vector<pair<pii, int>> arr;
    for (int q = 0; q < 4; ++q) {
        int x = 0, y = 0;

        if (q == 1) {
            x = r + 1, y = r;
            if (d % 2 == 0)  {
                ++y;
            }
        } else if (q == 2) {
            x = -r, y = r + 1;
            if (d % 2 == 0)  {
                ++y;
            }
        } else if (q == 3) {
            x = 1, y = 2 * r + 1;
            if (d % 2 == 0)  {
                y += 2;
            }
        }

        for (int i = -r; i <= r; ++i) {
            for (int j = -r; j <= r + 1; ++j) {
                int tmp = abs(i) + abs(j);
                if (d % 2 == 0 && j > 0) {
                    --tmp;
                }
                if (tmp <= r) {
                    arr.puba({{x + i, y + j}, q});
                }
            }
        }
    }

    int dx1 = 2 * r + 2, dy1 = 2 * r;
    int dx2 = -2 * r, dy2 = 2 * r + 2;

    if (d % 2 == 0) {
        dy1 += 2;
        dy2 += 2;
    }

    for (int i = 0; ; ++i) {
        int x = dx1 * i, y = dy1 * i;
        bool gflag = false;
        while (true) {
            bool flag = false;
            for (auto p : arr) {
                int nx = x + p.ff.ff, ny = y + p.ff.ss;
                if (on_field(nx, ny)) {
                    field[nx][ny] = p.ss;
                    flag = true;
                    gflag = true;
                }
            }
            if (!flag) {
                break;
            }
            x += dx2;
            y += dy2;
        }

        x = dx1 * i - dx2, y = dy1 * i - dy2;
        while (true) {
            bool flag = false;
            for (auto p : arr) {
                int nx = x + p.ff.ff, ny = y + p.ff.ss;
                if (on_field(nx, ny)) {
                    field[nx][ny] = p.ss;
                    flag = true;
                    gflag = true;
                }
            }
            if (!flag) {
                break;
            }
            x -= dx2;
            y -= dy2;
        }
        if (!gflag) {
            break;
        }
    }

    string colors = "RYGB";

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cout << colors[field[i][j]];
        }
        cout << "\n";
    }

    #ifdef LOCAL
        cerr << "time: " << clock() << endl;
    #endif
    return 0;
}

