        for (int i = -maxn*2; i <= maxn*2; i += d) {
            for (int j = -maxn*2; j <= maxn*2; j += d) {
                FOR(x,0,d) FOR(y,0,d) {
                    const int c = color[c1][c2];
                    const int I = i+x;
                    const int J = j+y;
                    const int ii = (I+J)/2;
                    const int jj = (I-J)/2;
                    if (0 <= ii && ii < H && 0 <= jj && jj < W)
