//manhattan distance trick, constructive algorithm (partitioning area)
//https://code-festival-2017-quala.contest.atcoder.jp/tasks/code_festival_2017_quala_d

#include <iostream>
#include <vector>

using namespace std;

const int INF = 1231231234;

struct pt
{
    int x, y;
};

pt toChebyshev(pt p)
{
    return {p.x + p.y, p.x - p.y};
}

char getColor(pt p, int minx, int miny, int d)
{
    int xPartition = (p.x - minx) / d, yPartition = (p.y - miny) / d;
    if (xPartition & 1)
    {
        return yPartition & 1 ? 'R' : 'B';
    }
    else
    {
        return yPartition & 1 ? 'G' : 'Y';
    }
}

int main()
{
    int h, w, d;
    cin>>h>>w>>d;

    vector <pt> corners = {{0, 0}, {h, 0}, {0, w}, {h, w}};
    int minX = INF, minY = INF;
    for (int i = 0; i < 4; i++)
    {
        pt p = toChebyshev(corners[i]);
        minX = min(minX, p.x);
        minY = min(minY, p.y);
    }

    char grid[h][w];
    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            pt p = toChebyshev({i, j});
            grid[i][j] = getColor(p, minX, minY, d);
        }
    }

    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            cout<<grid[i][j];
        }
        cout<<'\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int maxN = 510;
const char ch[8] = "RYGB";

int h, w;
char str[maxN][maxN];

inline void mark(int x, int y, int k){
	if(0 <= x && x < h && 0 <= y && y < w)
	if(!str[x][y])
		str[x][y] = ch[k];
}

int main (){
	int d, i, j;
	//freopen("out.txt", "w", stdout);
	scanf("%d%d%d", &h, &w, &d);
	if(d & 1){
		for(i = 0; i < h; ++i){
			for(j = 0; j < w; ++j)
				printf("%c", ch[(i + j) & 1]);
			puts("");
		}
	}
	else{
		if(d & 2){
			for(i = 0; i < h; ++i){
				for(j = 0; j < w; ++j)
					printf("%c", ch[((i & 3) + (j & 2)) & 3]);
				puts("");
			}
		}
		else{
			int s, t, p, q, k, dm = d / 2;
			for(p = -1; p <= max(1, h / dm); ++p){
			for(q = -1; q <= max(1, w / dm); ++q){
				s = p * dm, t = q * d;
				if(p & 1) t += dm;
				k = (p & 1) + ((p / 2 + q) & 1) * 2;
				for(i = 0; i < dm; ++i){
					for(j = 0; j < dm - i; ++j){
						mark(s + i, t + dm - j - 1, k);
						mark(s + i, t + dm + j, k);
