void dfs(int x, int y, int val) {
	if(x < 0 || y < 0 || x >= 2002 || y >= 2002) continue;
	if(co[x][y] != 0) return;
	for(int i=x-side; i<=x+side; i++) {
		for(int j=y-side; j<=y+side; j++) {
			if(i < 0 || j < 0 || i >= 2002 || j >= 2002) continue;
			if(abs(x-i) + abs(y-j) <= side) co[i][j] = val;
		}
	}
	dfs(x + side + side + 1, y + side + side - 1, val);
	dfs(x - side - side - 1, y - side - side + 1, val);

	dfs(x + side + side - 1, y - side - side - 1, val);
	dfs(x - side - side + 1, y - side - side + 1, val);
}

