    addedge(id0 * 8 + 6, id1 * 8 + 7);
}

void add(int x, int y) {

    for(int i = 0; i <= d; ++i) {
        if(x - i >= 0) {
            if(y + (d - i) < m) lim (x, y, x - i, y + (d - i));
            if(y - (d - i) >=0) lim (x, y, x - i, y - (d - i));
        }
        if(x + i < n) {
            if(y + (d - i) < m) lim (x, y, x + i, y + (d - i));
            if(y - (d - i) >=0) lim (x, y, x + i, y - (d - i));
        }
    }
}

