char mm[500+5][500+5];
bool visit[500+5][500+5]={{false}};
char color[4]={'R','Y','G','B'};

int n,m,d;
bool finish=false;

bool judge(int i,int j)
{
  if((i>=0&&i<n)&&(j>=0&&j<m)) return true;
  else return false;     
}

int abs(int x)
{
  if(x>=0) return x;
  else return -x;    
}

bool check(int i,int j)
{
  int cnt=0;
  for(int x=i-d;x<=i;x++)
  {
    int y1=j+cnt;
    int y2=j-cnt;
    cnt++;       
    if(judge(x,y1)&&mm[i][j]==mm[x][y1]) return false;
    if(judge(x,y2)&&mm[i][j]==mm[x][y2]) return false;   
  }            
  for(int x=i+d;x>=i;x--)
  {
    int dy=(i+d)-x;
    int y1=j+dy;
    int y2=j-dy;
    if(judge(x,y1)&&mm[i][j]==mm[x][y1]) return false;
    if(judge(x,y2)&&mm[i][j]==mm[x][y2]) return false;         
  }
  return true;
}

void dfs(int x,int y,int k)
{
  if(finish==true) return;
  if(x==n)
  {
    for(int i=0;i<n;i++)
    {
      for(int j=0;j<m;j++)
      {
        cout<<mm[i][j];        
      }        
      cout<<endl;
    }      
    finish=true;  
    return;
  }
  for(int i=0;i<k;i++)
  {
    mm[x][y]=color[i];
    if(check(x,y)&&(!visit[x][y]))
    {
      visit[x][y]=true;
      if((y+1)%m==0) dfs(x+1,0,k);
      else dfs(x,y+1,k);              
    }            
  }     
  return;
}

