vector<pair<int, int>> fig1, fig2;

inline bool ok(int i, int j) {
	return (i > 0 && j > 0 && i <= n && j <= m);
}

template<class T>
void crtaj(const T& fig, int x, int y, int c) {
	for (auto p : fig) {
		int u = p.first + x;
		int v = p.second + y;
		if (ok(u, v)) {
			a[u][v] = c;
		}
	}
}



