		for (int i=1; i<=n; i++) {
			for (int j=1; j<=m; j++) {
				a[i][j] = (i+j) % 2;
			}
		}
	} else {
		if (d % 2 == 1) {
			for (int x=-d-2; x<=d+2; x++) {
				for (int y=-d-2; y<=d+2; y++) {
					if (aps(x) + aps(y) <= d/2) {
						fig1.push_back({x, y});
					}

					if (aps(x) + aps(y) < d/2 ||
						aps(x-1) + aps(y) < d/2 ||
						aps(x) + aps(y-1) < d/2 ||
						aps(x-1) + aps(y-1) < d/2)
					{
						fig2.push_back({x, y});
					}
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=d) {
				for (int j=-4*d; j<=m+4*d; j+=d) {
					int c = (i/d + j/d + 16) % 2;
					crtaj(fig1, i, j, c);
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=d) {
				for (int j=-4*d; j<=m+4*d; j+=d) {
					int c = (i/d + j/d + 16) % 2;
					crtaj(fig2, i+d/2, j+d/2, 2 + c);
				}
			}

		} else {

			for (int x=-d-2; x<=d+2; x++) {
				for (int y=-d-2; y<=d+2; y++) {
					if (aps(x) + aps(y) < d/2 ||
						aps(x) + aps(y-1) < d/2)
					{
						fig1.push_back({x, y});
					}

					if (aps(x) + aps(y) < d/2 ||
						aps(x-1) + aps(y) < d/2)
					{
						fig2.push_back({x, y});
					}
				}
			}

			for (int i=-4*d; i<=n+4*d; i+=2*d) {
				for (int j=-4*d; j<=m+4*d; j+=2*d) {

					crtaj(fig1, i, j, 0);
					crtaj(fig1, i+d, j+d, 0);

					crtaj(fig1, i+d-1, j, 1);
					crtaj(fig1, i+d+d-1, j+d, 1);


					crtaj(fig2, i+d/2-1, j+d/2+1, 2);
					crtaj(fig2, i-d/2-1, j-d/2+1, 2);

					crtaj(fig2, i+d/2-1, j+d/2+d, 3);
					crtaj(fig2, i-d/2-1, j-d/2+d, 3);

				}
			}
		}
	}

	bool invalid = false;

	// validate
	for (int i=1; i<=n; i++) {
