    if(i>0 && i<=n && j>0 && j<=m)return true;
    return false;
}

void gget(int x,int y){
    int i1=x,i2=x,j=y+k;
    while(j>=y){
        if(check(i1,j))s1.insert(c[i1][j]);
        if(check(i2,j))s1.insert(c[i2][j]);
        i1++;
        i2--;
        j--;
    }
    j=y-k;
    i1=x;i2=x;
    while(j<=y){
        if(check(i1,j))s1.insert(c[i1][j]);
        if(check(i2,j))s1.insert(c[i2][j]);
        i1--;
        i2++;
        j++;
    }
}

void get(int x,int y){
    s.clear();
    s1.clear();
    v.clear();
    while(x<=n){
        int i=x,j=y;
        while(j<=m){
            v.pb(mp(i,j));
            j+=2*k;
        }
        j=y-2*k;
        while(j>0){
            v.pb(mp(i,j));
            j-=2*k;
        }
        x+=k;
        if(y+k<=m)
            y+=k;
        else if(y-k>0)
            y-=k;
       /* else
            x+=k;*/
    }
    for(auto p:v)s.insert(c[p.f][p.s]),gget(p.f,p.s);

    for(auto c1:s){
        if(c1=='-')continue;
        for(auto c2:s1){
            if(c2=='-')continue;
            if(c1==c2)
            goto out;
        }
        for(auto p:v)if(c[p.f][p.s]=='-')c[p.f][p.s]=c1;
        return;
        out:
        int x;
    }
    if(s1.find('R')==s1.end()){for(auto p:v)if(c[p.f][p.s]=='-')c[p.f][p.s]='R';return;}
    if(s1.find('B')==s1.end()){for(auto p:v)if(c[p.f][p.s]=='-')c[p.f][p.s]='B';return;}
    if(s1.find('Y')==s1.end()){for(auto p:v)if(c[p.f][p.s]=='-')c[p.f][p.s]='Y';return;}
    if(s1.find('G')==s1.end()){for(auto p:v)if(c[p.f][p.s]=='-')c[p.f][p.s]='G';return;}
}

