int main()
{
    int H, W, d;
    cin >> H >> W >> d;

    char color[] = { 'R', 'Y', 'G', 'B' };
    vector<vector<vector<bool> > > canSet(4, vector<vector<bool> >(H, vector<bool>(W, true)));
    vector<vector<char> > c(H, vector<char>(W, 0));

    auto isOK = ([&](int h, int w){
        return 0 <= h && h < H && 0 <= w && w < W;
    });

    auto next = ([&](int i) {
        return (i == 3 ? 0 : i + 1);
    });

    int start = 0;

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            bool first = true;
            for (int k = start; first == true || k != start; k = next(k)) {
                if (k == 4) {
                    c[i][j] = 'X';
                    continue;
                }
                if (canSet[k][i][j]) {
                    c[i][j] = color[k];
                    for (int r = 0; r <= d; ++r) {
                        if (isOK(i + r, j + (d - r)))
                            canSet[k][i + r][j + (d - r)] = false;
                        if (isOK(i - r, j + (d - r)))
                            canSet[k][i - r][j + (d - r)] = false;
                        if (isOK(i + r, j - (d - r)))
                            canSet[k][i + r][j - (d - r)] = false;
                        if (isOK(i - r, j - (d - r)))
                            canSet[k][i - r][j - (d - r)] = false;
                    }
                    break;
                }
                first = false;
            }
            start = next(start);
        }
    }

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            cout << c[i][j];
        }
        cout << endl;
    }
}

