		for (int j = 0; j < w; j++) {
			int abc[4] = { 0 };
			for (int k = 0; k <= d; k++) {
				int a = k;
				int b = d - k;
				if (hantei(i + a, j + b, h, w)) {
					for (int p = 0; p < 4; p++) {
