					for (int p = 0; p < 4; p++) {
						if (aa[p] == c[i + a][j - b]) {
							abc[p] = 1;
						}
					}
				}
				if (hantei(i - a, j + b, h, w)) {
					for (int p = 0; p < 4; p++) {
						if (aa[p] == c[i - a][j + b]) {
