bool is_on_field(int y, int x, int h, int w) { return 0 <= y and y < h and 0 <= x and x < w; }

vector<vector<char> > solve(int h, int w, int d) {
    w = max(2 * h, w);
    auto f = vectors(h, w, char());
    if (d % 2 == 1) {
        repeat (y, h) repeat (x, w) {
            f[y][x] = (y + x) % 4 + 1;
        }
    } else {
        repeat (y, h) repeat (x, w) {
            array<bool, 5> found = {};
            for (int ny = y - d; ny < y + d + 1; ++ ny) {
                int delta = d - abs(ny - y);
                for (int nx : { x - delta, x + delta }) {
                    if (is_on_field(ny, nx, h, w)) {
                        assert (abs(ny - y) + abs(nx - x) == d);
                        found[f[ny][nx]] += 1;
                    }
                }
            }
            int c = 1;
            while (c < 5 and found[c]) ++ c;
            if (c == 5) {
                fprintf(stderr, "err\n");
                c = 0;
            }
            f[y][x] = c;
        }
    }
    return f;
}

