const int smjery[] = {0, 0, 1, -1};

const int smjer1[] = {-1, 1, 1, -1};
const int smjer2[] = {1, 1, -1, -1};

int n, m, d;

int dist(int x, int y, int nx, int ny) {
  return max(x - nx, nx - x) + max(y - ny, ny - y);
}

char sol[] = "RGYB";
int bio[MAXN][MAXN], ans[MAXN][MAXN];

void dfs(int x, int y) {
  bio[x][y] = 1;

  int boje = 0;
  int nx = x + d;
  int ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[0];
    ny += smjer2[0];
  }
  nx = x + d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[3];
    ny += smjer2[3];
  }
  nx = x - d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[1];
    ny += smjer2[1];
  }
  nx = x - d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[2];
    ny += smjer2[2];
  }

  REP(i, 4) if (!(boje & (1 << i))) {ans[x][y] = i; break;}

  REP(i, 4) {
    int nx = x + smjerx[i];
    int ny = y + smjery[i];
    if (nx < 0 || nx >= n || ny >= m || ny < 0 || bio[nx][ny]) continue;
    dfs(nx, ny);
  }
}

