int C[16];

struct NOD {
	NOD(int y, int x, int key) : y(y), x(x), key(key) {}
	int y, x, key;

	bool operator < (const NOD &t) const {
		return C[key] < C[t.key];
	}
	bool operator > (const NOD &t) const {
		return C[key] > C[t.key];
	}
};

priority_queue<NOD, vector<NOD>, greater<NOD>> PQ;
vector<pii> G[505][505];

int A[505][505], B[505][505], D[505][505];

int H, W, T;

bool isg(int y, int x) { return 1 <= y && y <= H && 1 <= x && x <= W; }

int main() {
	for(int key = 0; key < 16; key++) {
		int sum = 0;
		for(int i = 0; i < 4; i++) if(key & (1<<i)) sum++;
		C[key] = sum;
	}
	cin >> H >> W >> T;

	if(T&1) {
		for(int i = 1; i <= H; i++) {
			for(int j = 1; j <= W; j++) {
				int c = (i&1) << 1 | (j&1);
				putchar("RGBY"[c]);
			}
			puts("");
		}
		return 0;
	}

	for(int i = 1; i <= H; i++) for(int j = 1; j <= W; j++) {
		for(int s = 0; s <= T; s++) {
			int y = i-s, x = j-(T-s);
			if(isg(y, x)) G[i][j].eb(y, x);
			x = j+(T-s);
			if(isg(y, x)) G[i][j].eb(y, x);
			y = i+s; x = j-(T-s);
			if(isg(y, x)) G[i][j].eb(y, x);
			x = j+(T-s);
			if(isg(y, x)) G[i][j].eb(y, x);
		}
	}

	for(int i = 1; i <= H; i++) for(int j = 1; j <= W; j++) {
		B[i][j] = 15;
		PQ.push(NOD(i, j, 15));
	}

	for(int y, x, key; !PQ.empty();) {
		y = PQ.top().y; x = PQ.top().x; key = PQ.top().key;
		PQ.pop();
		if(B[y][x] != key) continue;

		if(!B[y][x]) exit(-1);
		vector<int> CV;
