		//random_shuffle(allv(CV));

		D[y][x] = CV[0];
		for(auto &v : G[y][x]) {
			int ny, nx; tie(ny, nx) = v;

			if(B[ny][nx] & (1<<CV[0])) {
				B[ny][nx] ^= 1<<CV[0];
				PQ.push(NOD(ny, nx, B[ny][nx]));
			}
		}
	}

	for(int i = 1; i <= H; i++) {
		for(int j = 1; j <= W; j++) {
			int c = D[i][j];
			putchar("RGBY"[c]);
		}
		puts("");
	}
	return 0;
}

