                    int diff = k - j;
                    if(diff >= d / 2 && sign > 0) {
                        sign = -1;
                        h += (1 * sign);
                    }
                    ans[i][k] = h;
                    if(i + h < H) { ans[i + h][k] = d - (h * 2 - 1); }
                    h += (1 * sign);
                }
            }
        }
        char tile1 = 'R', tile2 = 'Y', tile3 = 'B';
        for(int i = 0; i < H; i += d) {
            if(tile1 == 'G') { tile1 = 'R'; }
            else { tile1 = 'G'; }
            if(tile2 == 'Y') {
                tile2 = 'B';
                tile3 = 'Y';
            }
            else {
                tile2 = 'Y';
                tile3 = 'B';
            }
            char tmp1 = tile1;
            char tmp2 = tile2;
            char tmp3 = tile3;
            for(int j = 0; j < W; ++j) {
                if(j % d == 0) {
                    if(tmp1 == 'G') { tmp1 = 'R'; }
                    else { tmp1 = 'G'; }
                    if(tmp2 == 'Y') {
                        tmp2 = 'B';
                        tmp3 = 'Y';
                    }
                    else {
                        tmp2 = 'Y';
                        tmp3 = 'B';
                    }
                }
                for(int k = 0; k < ans[i][j]; ++k) {
                    if(i + k < H) { ret[i + k][j] = tmp1; }
                    if(i - k >= 0) { ret[i - k][j] = tmp1; }
                }
                if(i + ans[i][j] < H) {
                    for(int k = 0; k < ans[i+ans[i][j]][j]; ++k) {
                        if(i + 1 + k < H) {
                            if(j % d < d / 2) { ret[i + ans[i][j] + k][j] = tmp2; }
                            else { ret[i + ans[i][j] + k][j] = tmp3; }
                        }
                    }
                }
            }
        }
        //REP(i, H) {
        //    REP(j, W) {
        //        printf("%d ", ans[i][j]);
        //    }
        //    printf("\n");
        //}
        //printf("---\n");
        REP(i, H) {
            REP(j, W) {
                printf("%c", ret[i][j]);
            }
            printf("\n");
        }
#endif
    }
    return 0;
}

