        if (i >= 0 && i < H && j >= 0 && j < W) {
          switch(A[i][j]) {
          case 'R':
            chs[0] = 1;
            break;
          case 'Y':
            chs[1] = 1;
            break;
          case 'G':
            chs[2] = 1;
            break;
          case 'B':
            chs[3] = 1;
            break;
          }
        }
      }
      if (!chs[0]) {
        A[foundi][foundj] = 'R'; 
      } else if (!chs[1]) {
        A[foundi][foundj] = 'Y'; 
      } else if (!chs[2]) {
        A[foundi][foundj] = 'G'; 
      } else if (!chs[3]) {
        A[foundi][foundj] = 'B'; 
      } else {
        abort();
      }
    }
  }
  for (auto a: A) {
    cout << a << endl;
  }

  return 0;
}

