using namespace::std;

void solve(){
	int H,W,D;
	cin >> H >> W >> D;
	vector< vector<int> > fld(H,vector<int>(W,-1) );
	if( D&1 ){
		for(int h=0;h<H;++h){
			for(int w=0;w<W;++w){
				fld[h][w] = (h+w)%2;
			}
		}
	}else{//dが偶数
		vector< vector<bool> > use(H,vector<bool>(W,false));
		int dh[] = {-1,0, 1, 0};
		int dw[] = { 0,1, 0,-1};
		int dd = D/2;
		for(int h=0;h<H;++h){
			for(int w=0;w<W;++w){
				if( use[h][w] ) continue;
				for(int tr = 0;;++tr){
					int h_tr = h + tr*dd;
					int w_tr = w + tr*dd;
					if( H <= h_tr || W <= w_tr ) break;
					use[h_tr][w_tr] = true;

					vector<bool> hist(4,false);//使われている色
					for(int k=0;k<4;++k){
						int hh = h_tr + dd*dh[k];
						int ww = w_tr + dd*dw[k];
						if( hh < 0 || H <= hh ) continue;
						if( ww < 0 || W <= ww ) continue;
						if( fld[hh][ww] != -1 ){
							hist[ fld[hh][ww] ] = true;
						}
					}
					for(int k=0;k<4;++k){
						int hh = h_tr + dd*dh[k];
						int ww = w_tr + dd*dw[k];
						if( hh < 0 || H <= hh ) continue;
						if( ww < 0 || W <= ww ) continue;
						if( fld[hh][ww] == - 1 ){//色の決定
							for(int c=0;c<4;++c){
								if( hist[c] == false ){//未使用
									hist[c] = true;
									fld[hh][ww] = c;
									break;
								}
							}
						}
					}
				}
			}
		}
	}
	string word = "RGBY";
	for(int h=0;h<H;++h){
		for(int w=0;w<W;++w){
			cout << word[ fld[h][w] ];
		}
		cout << "\n";
	}
	cout << flush;
}

