    cin.tie(0);
    ios_base::sync_with_stdio(false);
    cout << fixed << setprecision(30);
}

ll H, W, D;
V<string> ans;

VV<char> color = {
    { 'R', 'Y' },
    { 'G', 'B' },
    { 'Y', 'R' },
    { 'B', 'G' },
};

inline bool set_color(ll ch, ll cw, ll r, char c) {
    bool ret = false;
    for(ll rr = 0; rr <= r; rr++) {
        for(ll dh = -rr; dh <= rr; dh++) {
            ll adw = rr - abs(dh);
            for(ll dw : { -adw, adw }) {
                ll h = ch + dh;
                ll w = cw + dw;
                if(!(0 <= h && h < H &&
                     0 <= w && w < W)) continue;
                ret = true;
                ans[h][w] = c;
            }
        }
    }
    return ret;
}

void solve() {
    cin >> H >> W >> D;
    ans = V<string>(H, string(W, '.'));
    if(D == 1) {
        for(ll i = 0; i < H; i++) for(ll j = 0; j < W; j++) ans[i][j] = color[i % 2][j % 2];
        return;
    } else if(D == 2) {
        string a = "RYGB";
        string b = "GBRY";
        for(ll i = 0; i < H; i++) {
            const auto &s = (i % 4 <= 1 ? a : b);
            for(ll j = 0; j < W; j++) {
                ans[i][j] = s[j % 4];
            }
        }
        return;
    }
    ll len = D - !(D % 2);
    ll r = len / 2;
    for(ll i = 0;; i++) {
        ll ch = i * max<ll>(1, r);
        bool update = false;
        for(ll j = 0;; j++) {
            ll cw = (i & 1 ? (r > 0 ? r + 1 : 0) : 0) + j * len;
            if(W < cw - r) break;
            update |= set_color(ch, cw, r, color[i % 4][j % 2]);
        }
        if(!update) break;
    }
}

int main() {
    init_io();
    solve();
    for(const auto &s : ans) cout << s << endl;
    return 0;
}

