//--------------8---------------->> coding space <<-----------------8-------------//

int H, W, d;
int col[555][555], dame[555][555];
int nc[4][2] = {{1,2},{0,3},{3,0},{2,1}};

void solve() {
	minit(col, -1);
	minit(dame, 0);

	set< pii > cell;
	for_(y,0,H) for_(x,0,W) cell.insert(pii(x,y));

	queue< pii > que;
	while (!cell.empty()) {
		pii f = *cell.begin();
		col[f.second][f.first] = 0;
		cerr << f.first << " " << f.second << endl;

		que.push(f);
		cell.erase(f);

		while (!que.empty()) {
			pii p = que.front(); que.pop();
			int x = p.first, y = p.second;

			int dx = 0, dy = -d, t = 0;
			for_(i,0,d) {
				if (in_range(y+dy, 0, H) && in_range(x+dx, 0, W) && col[y+dy][x+dx] == -1) {
					col[y+dy][x+dx] = nc[col[y][x]][t % 2];
					que.push(pii(x+dx, y+dy));
					cell.erase(pii(x+dx, y+dy));
				}
				++dx; ++dy; ++t;
			}

			dx = d; dy = 0;
			for_(i,0,d) {
				if (in_range(y+dy, 0, H) && in_range(x+dx, 0, W) && col[y+dy][x+dx] == -1) {
					col[y+dy][x+dx] = nc[col[y][x]][t % 2];
					que.push(pii(x+dx, y+dy));
					cell.erase(pii(x+dx, y+dy));
				}
				--dx; ++dy; ++t;
			}

			dx = 0; dy = d;
			for_(i,0,d) {
				if (in_range(y+dy, 0, H) && in_range(x+dx, 0, W) && col[y+dy][x+dx] == -1) {
					col[y+dy][x+dx] = nc[col[y][x]][t % 2];
					que.push(pii(x+dx, y+dy));
					cell.erase(pii(x+dx, y+dy));
				}
				--dx; --dy; ++t;
			}

			dx = -d; dy = 0;
			for_(i,0,d) {
				if (in_range(y+dy, 0, H) && in_range(x+dx, 0, W) && col[y+dy][x+dx] == -1) {
					col[y+dy][x+dx] = nc[col[y][x]][t % 2];
					que.push(pii(x+dx, y+dy));
					cell.erase(pii(x+dx, y+dy));
				}
				++dx; --dy; ++t;
			}
		}
	}

	string cs = "RGBY";
	for_(y,0,H) for_(x,0,W) cout << cs[col[y][x]] << (x < W-1 ? "" : "\n");
}

