		for(int i=2;i<=n;i+=d-1)	if(!a[i][1])a[i][1]='G';
		for(int i=3;i<=n;i+=d-1)	if(!a[i][1])a[i][1]='B';
		for(int i=4;i<=n;i+=d-1)	if(!a[i][1])a[i][1]='Y';	
		for(int i=1;i<=n;++i)
			if(!a[i][1])
				if(a[i+d][1]!='R'||a[i-d][1]!='R')	a[i][1]='R';
				else if(a[i+d][1]!='G'||a[i-d][1]!='G')	a[i][1]='G';
	}

	queue<data> q;
	a[1][1]='R';
	data tmp;tmp.x=1,tmp.y=1,tmp.k='R';
	q.push(tmp);
