			if(u.k=='B')	a[x][y]='R';
			if(u.k=='G')	a[x][y]='Y';
			if(u.k=='Y')	a[x][y]='G';
			tmp.x=x,tmp.y=y,tmp.k=a[x][y];
			q.push(tmp);
		}
	}
	for(int i=1;i<=n;++i)
		for(int j=1;j<=m;++j)
		{
			if(a[i][j]!=0)	continue;
			a[i][j]='R';
		}
	for(int i=1;i<=n;++i)
	{
		for(int j=1;j<=m;++j)
			printf("%c",a[i][j]);
		puts("");
	}
}
