LL H, W, D;

LL ans = 0LL;
string num = "0123";
string alpha = "RYGB";

void solve_even(VS &a, int s, int t) {
	int c = ans % 4;
	ans++;
	for (int i = s; i < H; i += D) {//四方向のみ
		for (int j = t; j < W; j += D) {
			if (j - D >= 0 && a[i][j - D] != '.') {
				a[i][j] = num[(a[i][j - D] - '0' + 1) % 4];
			}

			else if (a[i][j] == '.') {
				a[i][j] = num[c];
			}
		}
		c = (c + 1) % 4;
	}
	//間に埋まるやつ
	for (int i = D / 2 + s; i < H; i += D) {
		for (int j = D / 2 + t; j < W; j += D) {
			if (j - D >= 0 && a[i][j - D] != '.') {
				a[i][j] = num[(a[i][j - D] - '0' + 1) % 4];
			}
			else {
				if (i - D / 2 >= 0 && j - D / 2 >= 0)a[i][j] = num[(a[i - D / 2][j - D / 2] - '0' + 3) % 4];
				else if (i - D / 2 >= 0 && j + D / 2 < W)a[i][j] = num[(a[i - D / 2][j + D / 2] - '0' + 2) % 4];
				else if (i + D / 2 < H && j - D / 2 >= 0)a[i][j] = num[(a[i + D / 2][j - D / 2] - '0' + 2) % 4];
				else if (i + D / 2 < H  && j + D / 2 < W)a[i][j] = num[(a[i + D / 2][j + D / 2] - '0' + 1) % 4];
			}
		}
	}

}


void solve_odd(VS &a,int s,int t) {
	int c = ans % 4;
	ans++;
	for (int i = s; i < H; i += D) {//四方向のみ
		for (int j = t; j < W; j += D) {
			if (j - D >= 0 && a[i][j - D] != '.') {
				a[i][j] = num[(a[i][j - D] - '0' + 1) % 4];
			}

			else if (a[i][j] == '.') {
				a[i][j] = num[c];
			}
		}
		c = (c + 1) % 4;
	}
	for (int i = 1+s; i < H; i++) {//左下に
		for (int j = 0+t; j < W - 1; j+=D) {
			if (a[i][j] == '.'&&a[i-1][j+1]!='.')a[i][j] = a[i - 1][j + 1];
		}
	}
	for (int i = 1+s; i < H; i++) {//右下に
		for (int j = 1+t; j < W; j+=D) {
			if (a[i][j] == '.'&&a[i-1][j-1]!='.')a[i][j] = a[i - 1][j - 1];
		}
	}


}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> H >> W >> D;
	VS a(H, string(W, '.'));

	if (D % 2 == 0) {
		FOR(i, 0, D) {
			FOR(j, 0, D) {
				solve_even(a, i, j);
			}
		}
	}
	else {
		assert(false);
		FOR(i, 0, D) {
			FOR(j, 0, D) {
				solve_odd(a,i,j);
				/*FOR(k, 0, H) {
					cout << a[k] << endl;
				}
				LL ss; cin>>ss;*/
			}
		}
	}
	FOR(i, 0, H) {
		FOR(j, 0, W) {
			a[i][j] = alpha[a[i][j]-'0'];
		}
	}
	FOR(i, 0, H) {
		cout << a[i] << endl;
	}

	return 0;
}

