int inside(int u, int v) {
    if (!(u >= 0 && u < n)) return 0;
    if (!(v >= 0 && v < m)) return 0;
    return 1;
}

int getmask(int u, int v) {
    int res = 0;
    FOR(x, 0, d + 1) {
        int y = d - x;
        for (int s1 = -1; s1 <= 1; s1 += 2) {
            for (int s2 = -1; s2 <= 1; s2 += 2) {
                int nu = u + x * s1;
                int nv = v + y * s2;
                if (inside(nu, nv) && vis[nu][nv]) {
                    res |= 1 << a[nu][nv];
                    if (bitcount(res) == 3) {
                        return res;
                    }
                }
            }
        }
    }
    return res;
}

