#include <iostream>
using namespace std;
int H, W, d;
char m[512][512];
char colors[] = {'R', 'Y', 'G', 'B'};

bool fourColoring(int x, int y, char color) {
  for (int i = 0; i <= d; i++) {
    int dx = i, dy = d - i;
    if (x - dx >= 0 && y - dy >= 0 && m[y-dy][x-dx] == color)
      return false;
    if (x - dx >= 0 && y + dy < H  && m[y+dy][x-dx] == color)
      return false;
    if (x + dx < W  && y - dy >= 0 && m[y-dy][x+dx] == color)
      return false;
    if (x + dx < W  && y + dy < H  && m[y+dy][x+dx] == color)
      return false;
  }

  m[y][x] = color;
  for (int i = 0; i < 4; i++) {
    if (colors[i] == color)
      continue;
    bool res = false;
    for (int j = 0; j <= d; j++) {
      int dx = j, dy = d - j;
      if (x - dx >= 0 && y - dy >= 0 && m[y-dy][x-dx] == 0)
        res |= !fourColoring(x-dx, y-dy, colors[i]);
      if (x - dx >= 0 && y + dy < H  && m[y+dy][x-dx] == 0)
        res |= !fourColoring(x-dx, y+dy, colors[i]);
      if (x + dx < W  && y - dy >= 0 && m[y-dy][x+dx] == 0)
        res |= !fourColoring(x+dx, y-dy, colors[i]);
      if (x + dx < W  && y + dy < H  && m[y+dy][x+dx] == 0)
        res |= !fourColoring(x+dx, y+dy, colors[i]);
    }
    if (res == false)
      break;
  }

  return true;
}

int main(void) {
  cin >> H >> W >> d;

  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (m[i][j] == 0) {
        for (int k = 0; k < 4; k++)
          if (fourColoring(i, j, colors[k]))
            break;
      }
    }
  }

  for (int i = 0; i < H; i++) {
    cout << m[i][0];
    for (int j = 1; j < W; j++)
      cout << ' ' << m[i][j];
    cout << '\n';
  }
}

