	int ni = 1;
	for (int i = 0;i < 31;i++) {
		n2[i] = ni;
		ni *= 2;
	}
	mody[0] = y;
	rep(1, i, 31) {
		y = (y * y) % mod;
		mody[i] = y;
	}
	rep(0, i, 31)nis[i] = 0;
	nn = mod - 2;
	for (int i = 30;i >= 0;i -= 1) {
		if (nn > n2[i]) {
			nis[i]++;
			nn -= n2[i];
		}
	}
