	if (n == 0)return 1;
	n -= 1;
	int ni = 1;
	for (int i = 0;i < 62;i++) {
		n2[i] = ni;
		ni *= 2;
	}
	int yy = y;
	mody[0] = yy;
	rep(1, i, 62) {
		yy = (yy * yy) % mod;
		mody[i] = yy;
	}
	rep(0, i, 62)nis[i] = 0;
	nn = n;
	for (int i = 62;i >= 0;i -= 1) {
		if (nn >= n2[i]) {
			nis[i]++;
			nn -= n2[i];
		}
	}
	rep(0, i, 62) {
		if (nis[i] == 1) {
			y = (y * mody[i]) % mod;
		}
	}
	return y;
}
