    char col[] = {'R', 'Y', 'G', 'B'};

    auto div = [&](int x) {
        const int T = 100000;

        x += T * d;
        x /= d;
        x -= T;

        return x;
    };

    FOR(i,0,h-1) FOR(j,0,w-1) {
        int index;

        if (d % 2) {
            index = 2 * (i % 2) + j % 2;
        } else {
            int x = i + j;
            int y = i - j;

            x = div(x);
            y = div(y);

            x %= 2; if (x < 0) x += 2;
            y %= 2; if (y < 0) y += 2;

            index = 2 * x + y;
        }

        cout << col[index];

        if (j == w-1) {
            cout << '\n';
        }
    }

    return 0;
}

