void dfs(int cur) {
  {
    int h = cur / W, w = cur % W;
    if (colors[h][w]!=0)return;
  }
  set<char> S;
  S.insert('R');
  S.insert('Y');
  S.insert('G');
  S.insert('B');

  for(int to:G[cur]) {
    int h=to/W,w=to%W;
    if (colors[h][w]!=0) {
      if(S.find(colors[h][w])!=S.end())S.erase(colors[h][w]);
    }
  }
  {
    int h = cur / W, w = cur % W;
    colors[h][w]=*S.begin();
  }
  for(int to:G[cur]) {
    int h=to/W,w=to%W;
    if (colors[h][w]==0) {
      dfs(to);
    }
  }
}
int main() {
  scanf("%d%d%d", &H, &W, &D);
  for(int i=0;i<H;++i) {
    for(int j=0;j<W;++j) {
      for(int k=-D;k<=D;++k) {
        int h=i+k;
        int w1=j+(D-abs(k));
        int w2=j-(D-abs(k));
        if (h>=0&&h<H &&w1>=0&&w1<W) {
          addEdge(i*W+j,h*W+w1);
        }
        if (h>=0&&h<H &&w2>=0&&w2<W && abs(k)!=D) {
          addEdge(i*W+j,h*W+w2);
        }
      }
    }
  }

  for(int i=0;i<H;++i) {
    for (int j = 0; j < W; ++j) {
      if (colors[i][j]==0) {
        dfs(i*W+j);
      }
    }
  }
  for(int i=0;i<H;++i) {
    for(int j=0;j<W;++j) {
      printf("%c", colors[i][j]);
    }
    printf("\n");
  }
  return 0;
}

#include <algorithm>
