        visited[i][j] = true;
        repl(k, 0, d + 1) {
            if (range(i + k, j + d - k) && !visited[i + k][j + d - k] && p[i][j] == p[i + k][j + d - k]) {
                p[i + k][j + d - k] = change(p[i][j]);
                q.push(PIP(num--, P(i + k, j + d - k)));
            }
            if (range(i + k, j - d + k) && !visited[i + k][j - d + k] && p[i][j] == p[i + k][j - d + k]) {
                p[i + k][j - d + k] = change(p[i][j]);
                q.push(PIP(num--, P(i + k, j - d + k)));
            }
        }

        repl(k, -d, 0) {
            if (range(i + k, j + d + k) && !visited[i + k][j + d + k] && p[i][j] == p[i + k][j + d + k]) {
                p[i + k][j + d + k] = change(p[i][j]);
                q.push(PIP(num--, P(i + k, j + d + k)));
            }
            if (range(i + k, j - d - k) && !visited[i + k][j - d - k] && p[i][j] == p[i + k][j - d - k]) {
                p[i + k][j - d - k] = change(p[i][j]);
                q.push(PIP(num--, P(i + k, j - d - k)));
            }
        }
    }

    rep(i, h) {
        rep(j, w) {
            cout << p[i][j];
        }
        cout << endl;
    }
    return 0;
}

