void get(int x, int y, int id)
{
    CL(vis, 0);
    FF(k, 0, d){
        int nx = x + k;
        int ny = y + d - k;
        if(check(nx, ny))
        vis[a[nx][ny]] = 1;
    }
    FF(k, 0, d){
        int nx = x - k;
        int ny = y + d - k;
        if(check(nx, ny))
        vis[a[nx][ny]] = 1;
    }
    FF(k, 0, d){
        int nx = x + k;
        int ny = y - (d - k);
        if(check(nx, ny))
        vis[a[nx][ny]] = 1;
    }
    FF(k, 0, d){
        int nx = x - k;
        int ny = y - (d - k);
        if(check(nx, ny))
        vis[a[nx][ny]] = 1;
    }
    FF(i, 1, 4) if(!vis[i]) ok[id].PB(i);
}

