vector<int>ans;
int dfs(int cur, int to)
{
    if(cur == to+1){
        return 1;
    }
    ///
    int sz = ok[cur].size();
    FF(i, 0, sz-1){
        int c = ok[cur][i];
        if(!vv[c])
        {
            ans.PB(c);
            vv[c] = 1;
            if(dfs(cur+1, to)) return 1;
            vv[c] = 0;
            ans.pop_back();
        }
    }
    return 0;
}
vector<node>now;
void bfs(int x, int y)
{
    int step = n/2;
    p.x = x; p.y = y;
    que.push(p);
    while(!que.empty()){
        node f = que.front(); que.pop();
        x = f.x; y = f.y;
        now.clear();
        int cnt = 0;
        FF(i, 0, 3){
            int nx = x+dx[i]*step, ny = y+dy[i]*step;
            if(check(nx, ny)){
                if(a[nx][ny]) continue;
                ++cnt;
                ok[cnt].clear();
                get(nx, ny, cnt);
                ///push
                p.x = nx; p.y = ny;
                now.PB(p);
                que.push(p);
            }
        }
        ans.clear();
        CL(vv, 0);
        dfs(1, cnt);
        int sz = now.size();
        FF(i, 0, sz-1){
            int xx = now[i].x, yy = now[i].y;
            a[xx][yy] = ans[i];
        }
    }
}

