bool check(int i,int j)
{
    if(i>=0&&j>=0&&i<n&&j<m)
        return true;
    return false;
}
vector<int > g[N];
bool vis[N];
int col[N];
bool colcheck(int i,int hold)
{
    for(const int & it : g[i])
    {
        if(col[it]==hold)
            return false;
    }
    return true;
}
void dfs(int node)
{
    vis[node]=1;
    for(const int & it : g[node])
    {
        if(vis[it])
            continue;
        for(int j=0;j<4;j++)
        {
            if(colcheck(it,j))
            {
                col[it]=j;
                break;
            }
        }
        dfs(it);
    }
}
int jkl(int i,int j)
{
    return i*m+j;
}
int main()
{
    for(int i=0;i<n;i++)
        for(int j=0;j<n;j++)
            vis[i]=0,col[i]=-1;
    cin>>n>>m>>d;
    int cn=0;
    int hh;
    int hold=n*m;
    for(int i=0;i<n;i++)
    {
        cn=0;
        for(int j=0;j<m;j++)
        {
            hh=j-d;
            if(check(i,hh))
            {
                g[jkl(i,j)].push_back(jkl(i,hh));
            }
            if(check(i,j+d))
            {
                g[jkl(i,j)].push_back(jkl(i,j+d));
            }
            if(check(i-d,j))
            {
                g[jkl(i,j)].push_back(jkl(i-d,j));
            }
            if(check(i+d,j))
            {
                g[jkl(i,j)].push_back(jkl(i+d,j));
            }
            hh++;
            cn++;
            while(hh!=j)
            {
                if(check(i+cn,hh))
                {
                   g[jkl(i,j)].push_back(jkl(i+cn,hh));
                }
                if(check(i-cn,hh))
                {
                    g[jkl(i,j)].push_back(jkl(i-cn,hh));
                }
                hh++;
                cn++;
            }
            hh++;
            cn--;
            while(hh!=j+d)
            {
                if(check(i+cn,hh))
                {
                   g[jkl(i,j)].push_back(jkl(i+cn,hh));
                }
                if(check(i-cn,hh))
                {
                    g[jkl(i,j)].push_back(jkl(i-cn,hh));
                }
                hh++;
                cn--;
            }
        }
