		for (int y = 0; y < H; y += d) {
			for (int x = 0; x < W; x += d) {
				int t = (x + y) / d;
				char c = (t % 2 == 0 ? 'R' : 'B');
				FOR(i, -D, D + 1) {
					int dd = D - (int)std::abs(i);
					FOR(j, -dd, dd + 1) {
