							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
	}
	else { // d % 2 == 0
		assert(false);
		// R, B
		for (int y = 0; y < H; y += d) {
			for (int x = 0; x < W; x += d + 2) {
				int t = (x + y) / d;
				char c = (t % 2 == 0 ? 'R' : 'B');
