							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
					else {
						FOR(j, -dd, dd + 2) {
							if (!IN(0, i + y, H) || !IN(0, j + x, W)) continue;
							ans[i + y][j + x] = c;
						}
					}
				}
			}
		}
		// G, Y
		for (int y = D; y < H; y += d) {
			for (int x = D + 1; x < W; x += d + 2) {
				int t = (x - D + y - D) / d;
				char c = (t % 2 == 0 ? 'G' : 'Y');
				ans[y][x] = c;
				FOR(i, -(D - 1), D + 1) {
