int check(const int r, const int c, const int f){
    int idx=-1;
    int hlf=d>>1;
    //[L, U)
    for(int i=d; i; i--){
        idx++;
        if(r-d+i<0 || r-d+i>=h)continue;
        if(c-i<0 || c-i>=w)continue;
        if(!~a[r-d+i][c-i])continue;
        if(a[r-d+i][c-i]!=(((idx/hlf)&1)^f))return 0;
    }
    //[U, R)
    for(int i=d; i; i--){
        idx++;
        if(r-i<0 || r-i>=h)continue;
        if(c+d-i<0 || c+d-i>=w)continue;
        if(!~a[r-i][c+d-i])continue;
        int goal=((idx/hlf)&1)^f;
        if(!f){
            if(goal)goal|=2;
        }else{
            if(!goal)goal=3;
        }
        if(a[r-i][c+d-i]!=goal)return 0;
    }
    //[R, D)
    for(int i=d; i; i--){
        idx++;
        if(r+d-i<0 || r+d-i>=h)continue;
        if(c+i<0 || c+i>=w)continue;
        if(!~a[r+d-i][c+i])continue;
        if(a[r+d-i][c+i]!=(((idx/hlf)&1)^f))return 0;
    }
    //[D, L)
    for(int i=d; i; i--){
        idx++;
        if(r+i<0 || r+i>=h)continue;
        if(c-d+i<0 || c-d+i>=w)continue;
        if(!~a[r+i][c-d+i])continue;
        int goal=((idx/hlf)&1)^f;
        if(!f){
            if(goal)goal|=2;
        }else{
            if(!goal)goal=3;
        }
        if(a[r+i][c-d+i]!=goal)return 0;
    }
    return 1;
}

void even(){
    for(int r=0; r<h; r++){
        for(int c=0; c<w; c++){
            if(!~a[r][c]){
                a[r][c]=2;
                if(check(r, c, 0)){
                    int idx=-1;
                    int hlf=d>>1;
                    //[L, U)
                    for(int i=d; i; i--){
                        idx++;
                        if(r-d+i<0 || r-d+i>=h)continue;
                        if(c-i<0 || c-i>=w)continue;
                        a[r-d+i][c-i]=(idx/hlf)&1;
