const int N = 505;

struct edge {
  int nxt, to;
}e[10000000];
int fir[N * N], cnt = 0;

char ch[4] = {'R', 'Y', 'G', 'B'};
int id[N][N], col[N * N], deg[N * N], nid[N * N];

inline void add(int x, int y) {
  e[++ cnt] = (edge){fir[x], y};
  fir[x] = cnt;
}

inline void link(int x, int y) {
  add(max(x, y), min(x, y));
  deg[x] ++; deg[y] ++;
}

inline bool cmp(int x, int y) {
  return deg[x] > deg[y];
}

int main() {
  int n, m, d, pnt = 0;
  scanf("%d%d%d", &n, &m, &d);
  for (int i = 1; i <= n; i ++)
    for (int j = 1; j <= m; j ++) id[i][j] = ++ pnt;
  for (int i = 1; i <= n; i ++)
    for (int j = 1; j <= m; j ++) {
      nid[id[i][j]] = id[i][j];
      if (j + d <= m) link(id[i][j], id[i][j + d]);
      for (int k = 1; k <= d && i + k <= n; k ++) {
	if (j - (d - k) > 0) link(id[i][j], id[i + k][j - (d - k)]);
	if (j + (d - k) <= m) link(id[i][j], id[i + k][j + (d - k)]);
      }
    }
  sort(nid + 1, nid + n * m + 1, cmp);
  int cur = 0;
  for (int i = 1; i <= n * m; i ++)
    if (!col[nid[i]]) {
      col[nid[i]] = cur;
      for (int j = i + 1; j <= n * m; j ++)
	if (!col[nid[j]]) {
	  bool flag = 1;
	  for (int k = fir[nid[j]]; k; k = e[k].nxt)
	    if (col[e[k].to] == cur) {flag = 0; break;}
	  if (flag) col[nid[j]] = cur;
	}
      cur ++;
    }
  for (int i = 1; i <= n * m; i ++) {
    //cerr << col[i] << " ";
    putchar(ch[col[i] - 1]);
    if (i % n == 0) putchar('\n');
  }
  return 0;
}

