void f(int h, int w, char c){
  int dd = (d-1) / 2;
  for(int k = -dd; k <= dd; k++){
    for(int i = h + abs(k); i <= h + d - 1 - abs(k); i++){
      if( isin(i, w+k) )
	a[i][w+k] = c;
    }
  }
