void f2(int h, int w, char c){
  int dd = d / 2;
  for(int dh = 0; dh < dd; dh++){
    for(int ww = w + dh; ww <= w + d - 2 - dh; ww++){
      if( isin( h + dh, ww ) ){
	a[h + dh][ ww ] = c;
      }
      if( isin( h - 1 - dh, ww ) ){
	a[h - 1 - dh][ ww ] = c;
      }
    }
  }
}

