bool checker(std::vector<std::string>const& field, int h, int w, int d)
{
	for (int i = 0; i < h; ++i)
	{
		for (int j = 0; j < w; ++j)
		{
			for (int k = -d; k <= d; ++k)
			{
				int x = i + k;
				int y1 = j + std::abs(d - std::abs(k));
				int y2 = j - std::abs(d - std::abs(k));
				if (0 <= x&&x < h)
				{
					if (0 <= y1&&y1 < w)
					{
						if (field[x][y1] == field[i][j])
						{
							return false;
						}
					}
					if (0 <= y2&&y2 < w)
					{
						if (field[x][y1] == field[i][j])
						{
							return false;
						}
					}
				}
			}
		}
	}
	return true;
}

