            if (b[i][j] != -1) continue;
            vector<bool> used(4, true);

            for (int dx = 0; dx <= d; ++dx) {
                const int dy = (d - dx);

                if (is_in(j + dx, i + dy) && b[i + dy][j + dx] != -1)
                    used[b[i + dy][j + dx]] = false;
                if (is_in(j - dx, i + dy) && b[i + dy][j - dx] != -1)
                    used[b[i + dy][j - dx]] = false;
                if (is_in(j + dx, i - dy) && b[i - dy][j + dx] != -1)
                    used[b[i - dy][j + dx]] = false;
                if (is_in(j - dx, i - dy) && b[i - dy][j - dx] != -1)
                    used[b[i - dy][j - dx]] = false;

            }

            for (int k = 0; k < 4; ++k)
                if (used[k]) {
                    b[i][j] = k;
                    break;
                }
        }
    }

    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            cout << c[b[i][j]];
        }
        cout << endl;
    }

    return 0;
}

