    if (is_inside(nr, nc)) v.push_back(Pi(nr, nc));
    nr = r - D + i, nc = c + i;
    if (is_inside(nr, nc)) v.push_back(Pi(nr, nc));
  }
}

void solve() {
  for (int i = 0; i < H; i++)
    for (int j = 0; j <= W; j++) MAT[i][j] = '\0';


  for (int r = 0; r < H; r++) {
    for (int c = 0; c < W; c++) {
      if (MAT[r][c] != '\0') continue;

#ifdef DEBUG
cout << i << " " << j << endl;
#endif

      bool used[4] = {false, false, false, false};
      vector<Pi> v;
      get_d(r, c, v);
      for (auto p: v) {
        int nr = p.FST, nc = p.SND;
        int k = idx(MAT[nr][nc]);
        if (k >= 0) used[k] = true;
      }

      for (int i = 0; i < 4; i++) {
        if (!used[i]) {
          MAT[r][c] = COLOR[i]; break;
        }
      }
    }
  }

  for (int i = 0; i < H; i++)
    cout << MAT[i] << endl;

}

