int main() {
	int h,w,d;
	std::cin >> h >> w >> d;
	std::vector<std::vector<int> > g(2*h+d,std::vector<int>(2*w+d,-1));
	auto dec = [] (int c) -> char {
		if(c==0) return 'R';
		if(c==1) return 'Y';
		if(c==2) return 'G';
		if(c==3) return 'B';
		return 'x';
	};
