			rep(j,w) std::cout << dec(g[i][j]);
			std::cout << EL;
		}
	} else {
		std::queue<P> que;
		for(int i=0;i*d<2*h+d;i++) {
			for(int j=0;j*d<2*w+d;j++) {
				int c = (i%2)^(j%2);
				g[i*d][j*d] = c;
				que.emplace(i*d,j*d,c);
				if(i*d+1<2*h+d) {
					g[i*d+1][j*d] = c;
					que.emplace(i*d+1,j*d,c);
				}
			}
		}
		for(int i=0;i*d+d/2<2*h+d;i++) {
			for(int j=0;j*d+d/2<2*w+d;j++) {
				int c = (i%2)^(j%2)+2;
