					if(dx+x<0||dx+x>=2*h+d) continue;
					if(dy+y<0||dy+y>=2*w+d) continue;
					if(g[dx+x][dy+y]!=-1) continue;
					g[dx+x][dy+y]=c;
					que.emplace(dx+x,dy+y,c);
				}
			}
		}
		rep(i,h) {
			rep(j,w) std::cout << dec(g[i+d][j+d]);
			std::cout << EL;
		}
	}
}

