    cin >> H >> W >> d;
    int R = 1, Y = 1 << 1, G = 1 << 2, B = 1 << 3;
    string color = "RYGB";
    vector<vector<int>> c(H, vector<int>(W, (1 << 4) - 1));
    c[0][0] = R;
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(__builtin_popcount(c[i][j]) != 1) {
                int mask = c[i][j];
                for(int dx = 0; dx <= d; ++dx) {
                    int dy = d - dx;
                    if(i - dy >= 0 && j - dx >= 0 && __builtin_popcount(c[i - dy][j - dx]) == 1) {
                        mask &= ~c[i - dy][j - dx];
                    }
                    if(i - dy >= 0 && j + dx < W && __builtin_popcount(c[i - dy][j + dx]) == 1) {
                        mask &= ~c[i - dy][j + dx];
                    }
                    if(i + dy < H && j - dx >= 0 && __builtin_popcount(c[i +dy][j - dx]) == 1) {
                        mask &= ~c[i + dy][j - dx];
                    }
                    if(i + dy < H && j + dx < W && __builtin_popcount(c[i + dy][j + dx]) == 1) {
                        mask &= ~c[i + dy][j + dx];
                    }
                }
                for(int k = 0; k < 4; ++k) {
                    if((mask >> k) & 1) {
                        c[i][j] = (1 << k);
                        break;
                    }
                }
            }
            for(int dx = 0; dx <= d; ++dx) {
                int dy = d - dx;
                int mask2 = ((1 << 4) - 1) & (~c[i][j]);
                if(i - dy >= 0 && j - dx >= 0) {
                    c[i - dy][j - dx] &= mask2;
                }
                if(i - dy >= 0 && j + dx < W) {
                    c[i - dy][j + dx] &= mask2;
                }
                if(i + dy < H && j - dx >= 0) {
                    c[i + dy][j - dx] &= mask2;
                }
                if(i + dy < H && j + dx < W) {
                    c[i + dy][j + dx] &= mask2;
                }
            }
        }
    }

    vector<vector<char>> res(H, vector<char>(W, '$'));
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            for(int k = 0; k < 4; ++k) {
                if((c[i][j] >> k) & 1) {
                    res[i][j] = color[k];
                    break;
                }
                assert(c[i][j] != '$');
            }
        }
    }

    for(auto& s : res) {
        for(auto c : s) {
            cout << c;
        }
        cout << endl;
    }
}

