const int MAXN = 510;
const int smjerx[] = {1, -1, 0, 0};
const int smjery[] = {0, 0, 1, -1};

const int smjer1[] = {-1, 1, 1, -1};
const int smjer2[] = {1, 1, -1, -1};

int n, m, d;

int dist(int x, int y, int nx, int ny) {
  return max(x - nx, nx - x) + max(y - ny, ny - y);
}

char sol[] = "RGYB";
int bio[MAXN][MAXN], ans[MAXN][MAXN];

void obojaj(int x, int y) {
  int boje = 0;
  int nx = x + d;
  int ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[0];
    ny += smjer2[0];
  }
  nx = x + d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[3];
    ny += smjer2[3];
  }
  nx = x - d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[1];
    ny += smjer2[1];
  }
  nx = x - d;
  ny = y;
  while (dist(nx, ny, x, y) == d) {
    if (nx >= 0 && nx < n && ny >= 0 && ny < m && bio[nx][ny]) boje |= (1 << ans[nx][ny]);
    nx += smjer1[2];
    ny += smjer2[2];
  }

  REP(i, 4) if (!(boje & (1 << i))) {ans[x][y] = i; break;}
  assert(ans[x][y] != -1);
}

void bfs() {
  queue <int> q;
  srand(time(NULL));
  q.push(rand()%n);
  q.push(rand()%m);
  int x, y;
  while (!q.empty()) {
    x = q.front();
    q.pop();
    y = q.front();
    q.pop();
    bio[x][y] = 1;
    obojaj(x, y);
    REP(i, 4) {
      int nx = x + smjerx[i];
      int ny = y + smjery[i];
      if (nx < 0 || ny < 0 || nx >= n || ny >= m || bio[nx][ny]) continue;
      bio[nx][ny] = 1;
      q.push(nx);
      q.push(ny);
    }
  }
}

int main() {
  memset(ans, -1, sizeof ans);
  scanf("%d %d %d",&n,&m,&d);
  bfs();
  REP(i, n) {
    REP(j, m) printf("%c",sol[ans[i][j]]);
    puts("");
  }

  return 0;
}

