int vis[MAX][MAX];
int in_stack[MAX][MAX];
int h, w, d;
char color[] = {' ','R','Y','G','B'};
int c1[MAX][MAX], c2[MAX][MAX], c3[MAX][MAX], c4[MAX][MAX];

void dfs(int i, int j){
	stack< ii > s;
	s.push(ii(i,j));
	in_stack[i][j] = 1;
	while(!s.empty()){
		ii tmp = s.top();
		int x= tmp.first;
		int y= tmp.second;
		s.pop();
		if(vis[x][y])continue;
		int cl;
		if(c1[x][y])cl = 1;
		else if(c2[x][y])cl =2;
		else if(c3[x][y])cl =3;
		else cl=4;
		vis[x][y]=cl;
		// cout << "vis " << x << " " << y << " " << cl << endl;
		for(int p=-d; p<=d; p++){
			int l = x - p;
			int m = y - (d-(int)abs(p));
			// cout << l << " " << m << endl;
			if(l>=1 && l<=h && m>=1 && m<=w && !vis[l][m]){
				if(cl==1)c1[l][m]=0;
				else if(cl==2)c2[l][m]=0;
				else if(cl==3)c3[l][m]=0;
				else c4[l][m]=0;
				if(!in_stack[l][m]){
					s.push(ii(l,m));
					in_stack[l][m]=1;
				}
			}
			m = y + (d-(int)abs(p));
			// cout << l << " " << m << endl;

			if(l>=1 && l<=h && m>=1 && m<=w && !vis[l][m]){
				if(cl==1)c1[l][m]=0;
				else if(cl==2)c2[l][m]=0;
				else if(cl==3)c3[l][m]=0;
				else c4[l][m]=0;
				if(!in_stack[l][m]){
					s.push(ii(l,m));
					in_stack[l][m]=1;
				}
			}
		}
	}
}

