char sol[MAXN + 1][MAXN + 1];
int n, m, d;

void dfs(int l, int c) {
    int a = min(l - d, 1), b = max(l + d, n);
    int i;
    bool ok[4];
    memset(ok, 0, sizeof(ok));
    for(i = a; i <= b; i++) {
        int c1 = d + c - abs(l - i);
        int c2 = c + abs(l - i) - d;
        if(c1 >= 1 && c1 <= m && sol[i][c1] > -1)
            ok[sol[i][c1]] = 1;
        if(c2 >= 1 && c2 <= m && sol[i][c2] > -1)
            ok[sol[i][c2]] = 1;
    }
    i = 0;
    while(i < 4 && ok[i] == 1)
        i++;
    sol[l][c] = i;
    for(i = a; i <= b; i++) {
        int c1 = d + c - abs(l - i);
        int c2 = c + abs(l - i) - d;
        if(c1 >= 1 && c1 <= m && sol[i][c1] == -1)
            dfs(i, c1);
        if(c2 >= 1 && c2 <= m && sol[i][c2] == -1)
            dfs(i, c2);
    }
}

