#define s second
#define lb lower_bound
#define ub upper_bound

const int MOD = 1000000007;

int H,W,d;
char grid[500][500];

void solveodd() {
    F0R(i,H) {
        F0R(j,W) {
            if (i % 2 == 0) {
                if (j % 2 == 0) grid[i][j] = 'A';
                else grid[i][j] = 'B';
            } else {
                if (j % 2 == 0) grid[i][j] = 'C';
                else grid[i][j] = 'D';
            }
        }
    }
    F0R(i,H) {
        F0R(j,W) cout << grid[i][j];
        cout << "\n";
    }
}

void fill(int x, int y, char c) {
    vector<pii> todo;
    F0R(i,d/2) FOR(j,-(d/2-i)+1,d/2-i) todo.pb({x-i,y+j});
    F0R(i,d/2) FOR(j,-(d/2-i)+1,d/2-i) todo.pb({x+1+i,y+j});
    for (auto a: todo) if (0 <= a.f && a.f < H && 0 <= a.s && a.s < W) grid[a.f][a.s] = c;
}

void solveeven() {
    FOR(i,-505,H+505) FOR(j,-505,W+505) {
        if (i % d == 0 && j % d == 0) {
            if ((i/d+j/d) % 2 == 0) fill(i,j,'R');
            else fill(i,j,'Y');
        } else if ((i%d+d)%d == (d/2) && (j%d+d)%d == (d/2)) {
            if ((i/d+j/d) % 2 == 0) fill(i,j,'G');
            else fill(i,j,'B');
        }
    }
    F0R(i,H) {
        F0R(j,W) cout << grid[i][j];
        cout << "\n";
    }
}

int main() {
	ios_base::sync_with_stdio(0);cin.tie(0);
	cin >> H >> W >> d;
	if (d % 2 == 1) solveodd();
	else solveeven();
}

