const int dx[4] = {1, -1, -1, 1};
const int dy[4] = {-1, 1,-1, 1};

void dfs(int x, int y){
  vector<int> colors;
  for(int i=0;i<=d;i++){
    for(int j=0;j<4;j++){
      int nx = x + i*dx[j], ny = y + (d-i)*dy[j];
      if(nx < 0 || ny < 0 || nx >= H || ny >= W) continue;
      colors.push_back(mass[nx][ny]);
    }
  }
  int c = 0;
  sort(colors.begin(), colors.end());
  for(int i = 0;i<colors.size();i++){
    if(c == colors[i]) c++;
  }
  mass[x][y] = c;
  //  cout << c << endl;
  for(int i=0;i<=d;i++){
    for(int j=0;j<4;j++){
      int nx = x + i*dx[j], ny = y + (d-i)*dy[j];
      if(nx < 0 || ny < 0 || nx >= H || ny >= W) continue;
      if(mass[nx][ny] != -1) continue;
      dfs(nx, ny);
    }
  }
}

int main()
{
