  memset(mass, -1, sizeof(mass));

  for(int i=0;i<H;i++){
    for(int j=0;j<W;j++){
      if(mass[i][j] == -1){
	dfs(i, j);
      }
    }
  }

  for(int i=0;i<H;i++){
    for(int j=0;j<W;j++){
      //      cout << mass[i][j] << endl;
      cout << color[mass[i][j]];
    }
    cout << endl;
  }
  return 0;
}

