		bucket[i] = 0;
	}
	for (i = 0; i <= n; i++) {
		bucket[s[i]]++;
	}
	ull sum = 0;
	for (i = 0; i <= ckind; i++) {
		sum += bucket[i];
		bucket[i] = sum - bucket[i];
	}

	// put LMS
	ull cnt[ckind];
	for (i = 0; i < ckind; i++) {
		cnt[i] = 0;
	}
	for (i = lmscnt - 1; i >= 0; i--) {
		ull ch = s[lms[i]];
		sa[bucket[ch + 1] - 1 - cnt[ch]] = lms[i];
		// printf("LMSput: [%3llu] <- %3llu\n", bucket[ch + 1] - 1 - cnt[ch], lms[i]);
		// fflush(stdout);
		cnt[ch]++;
	}

	// put L-type
	memset(cnt, 0, sizeof(ull) * ckind);
	for (i = 0; i <= n; i++) {
		if (sa[i] < 0) continue;
		if (sa[i] == 0 || isS[sa[i] - 1]) continue;

		ull ch = s[sa[i] - 1];
		sa[bucket[ch] + cnt[ch]] = sa[i] - 1;
		// printf("  Lput: [%3llu] <- %3llu\n", bucket[ch] + cnt[ch], sa[i] - 1);
		// fflush(stdout);
		cnt[ch]++;
	}

	// put S-type
	memset(cnt, 0, sizeof(ull) * ckind);
	for (i = n; i >= 0; i--) {
		if (sa[i] < 0) continue;
		if (sa[i] == 0 || !isS[sa[i] - 1]) continue;

		ull ch = s[sa[i] - 1];
		sa[bucket[ch + 1] - 1 - cnt[ch]] = sa[i] - 1;
		// printf("  Sput: [%3llu] <- %3llu\n", bucket[ch + 1] - 1 - cnt[ch], sa[i] - 1);
		// fflush(stdout);
		cnt[ch]++;
	}
}

void sa_is (ull s[], sll sa[], ull n, ull ckind) {
	sll i;

	bool isS[n + 1];
	isS[n] = true;
	for (i = n - 1; i >= 0; i--) {
		if (s[i] < s[i + 1]) {
			isS[i] = true;
		} else if (s[i] > s[i + 1]) {
			isS[i] = false;
		} else {
			isS[i] = isS[i + 1];
		}
	}

	ull lms[n + 1], lmscnt = 0;
	for (i = 0; i <= n; i++) {
		if (is_lms(isS, i)) {
			lms[lmscnt++] = i;
		}
	}

	induced_sort(s, sa, isS, lms, n, lmscnt, ckind);

	ull lmssort[lmscnt], c = 0;
	for (i = 0; i <= n; i++) {
		ull v = sa[i];
		if (is_lms(isS, v)) {
			lmssort[c++] = v;
		}
	}

	ull nums[n + 1], num = 0;
	nums[lmssort[0]] = 0;
	bool isunique = true;
	for (i = 1; i < lmscnt; i++) {
		ull prev = lmssort[i - 1];
		ull curr = lmssort[i];

		bool issame = true;
		sll j = 0;
		while (true) {
			if (prev + j > n || curr + j > n || s[prev + j] != s[curr + j] || is_lms(isS, prev + j) != is_lms(isS, curr + j)) {
				issame = false;
				break;
			} else if (j && is_lms(isS, prev + j) && is_lms(isS, curr + j)) {
				break;
			}

			j++;
		}

		if (issame) {
			isunique = false;
		} else {
			num++;
		}
		nums[curr] = num;
	}

	if (!isunique) {
		ull densenums[lmscnt];
		for (i = 0; i < lmscnt; i++) {
			densenums[i] = nums[lms[i]];
		}
		sa_is(densenums, sa, lmscnt - 1, num + 1);
		for (i = 0; i < lmscnt; i++) {
			lmssort[i] = lms[sa[i]];
		}
	}

	induced_sort(s, sa, isS, lmssort, n, lmscnt, ckind);
}

