                int x = 0;
                while ((bit[i][j] & (1 << x)) == 0) ++x;
                bit[i][j] = 1 << x;
                class T {
                    void dfs(int a, int b, int x) {
                        if (!in(a, b)) return;
                        if (ok[a][b]) return;
                        ok[a][b] = true;
                        bit[a][b] = 1 << x;
                        for (int k = 0; k <= d; ++k) {
                            remove(a + k, b + d - k, x);
                            remove(a - k, b + d - k, x);
                            remove(a + k, b - d + k, x);
                            remove(a - k, b - d + k, x);
                        }
                        int f = d + d;
                        dfs(a + f, b, x);
                        dfs(a - f, b, x);
                        dfs(a, b + f, x);
                        dfs(a, b - f, x);
                    }

