		for(int i=0;i<h;i++){
			for(int j=0;j<w;j++){
				for(int k=0;k<4;k++){
					if(i-d>=0){
						if(flag[k][i-d][j]){
							continue;
						}
					}
					if(j-d>=0){
						if(flag[k][i][j-d]){
							continue;
						}
					}
					if(j==0){
						t[i] = s[k];
						flag[k][i][j] = true;
					}
					else{
						t[i] = t[i] + s[k];
						flag[k][i][j] = true;
					}
					for(int x=0;x<=d;x++){
						if(i+x<h && j+d-x<w){
							flag[k][i+x][j+d-x] = true;
						}
					}
					break;
				}
			}
		}
		for(int i=0;i<w;i++){
			System.out.println(t[i]);
		}
	}
}

