public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int h = ir.nextInt();
		int w = ir.nextInt();
		int d = ir.nextInt();
		char[][] map = new char[h][w];
		if (d % 2 == 1) {
			for (int i = 0; i < h; i++)
				for (int j = 0; j < w; j++)
					map[i][j] = ((i + j) % 4 == 0 ? 'R' : ((i + j) % 4 == 1) ? 'Y' : ((i + j) % 4 == 2) ? 'G' : 'B');
		} else {
			for (int i = 0; i < h; i++)
				for (int j = 0; j < w; j++) {
					if ((i + j) % (2 * d) < d) {
						if (i % d < d / 2)
							map[i][j] = 'R';
						else
							map[i][j] = 'Y';
					} else {
						if (i % d < d / 2)
							map[i][j] = 'G';
						else
							map[i][j] = 'B';
					}
				}
		}
		for (int i = 0; i < h; i++)
			out.println(map[i]);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		if (debug)
			out.println(Arrays.deepToString(o));
	}
}

import java.io.*;
import java.util.*;

public class Main{
	class Node implements Comparable<Node>{
		@Override
		public String toString() {
			return "Node [r=" + r + ", c=" + c + ", color=" + Arrays.toString(color) + ", mine=" + mine + ", sum=" + sum + "]";
		}

		int r, c;
		boolean[] color;
		int mine;
		int sum;
		public Node(int r, int c){
			this.r = r;
			this.c = c;
			color = new boolean[4];
		}

		@Override
		public int compareTo(Node o) {
			if(o.r == r && o.c == c){
				return 0;
			}
			if(o.sum != sum){
				return -Integer.compare(sum, o.sum);
			}
			if(o.r != r){
				return Integer.compare(r, o.r);
			}
			return Integer.compare(c, o.c);
		}
	}

	public Node get(int r, int c){
		if(0 <= r && r < H && 0 <= c && c < W){
			return map[r][c];
		}else{
			return null;
		}
	}

	int H, W, D;
	Node[][] map;
	TreeSet<Node> nodes;
	public void solve(){
		H = nextInt();
		W = nextInt();
		D = nextInt();
		map = new Node[H][W];
		nodes = new TreeSet<>();
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				map[i][j] = new Node(i, j);
				nodes.add(map[i][j]);
			}
		}

		dfs();

		char[] cc = {'R', 'Y', 'G', 'B'};
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				out.print(cc[map[i][j].mine]);
			}
			out.println();
		}
	}

	public boolean dfs(){
		if(nodes.isEmpty()){
			return true;
		}

		Node node = nodes.first();
		nodes.remove(node);
		int[] psum = new int[D * 4];

		for(int i = 0; i < 4; i++){
			if(node.color[i]) continue;

			int idx = 0;
			for(int j = 0; j <= D; j++){
				int r = node.r + j;
				int c = node.c + (D - j);
				Node nn = get(r, c);
				if(nn != null){
					psum[idx++] = nn.sum;
					if(!nn.color[i]){
						nodes.remove(nn);
						nn.color[i] = true;
						nn.sum++;
						nodes.add(nn);
					}
				}

				r = node.r - j;
				c = node.c - (D - j);
				nn = get(r, c);
				if(nn != null){
					psum[idx++] = nn.sum;
					if(!nn.color[i]){
						nodes.remove(nn);
						nn.color[i] = true;
						nn.sum++;
						nodes.add(nn);
					}
				}
			}
			node.mine = i;

			if(dfs()){
				return true;
			}
			idx = 0;
			for(int j = 0; j <= D; j++){
				int r = node.r + j;
				int c = node.c + (D - j);
				Node nn = get(r, c);
				if(nn != null){
					if(psum[idx++] != nn.sum){
						nodes.remove(nn);
						nn.color[i] = false;
						nn.sum--;
						nodes.add(nn);
					}
				}

				r = node.r - j;
				c = node.c - (D - j);
				nn = get(r, c);
				if(nn != null){
					if(psum[idx++] != nn.sum){
						nodes.remove(nn);
						nn.color[i] = false;
						nn.sum--;
						nodes.add(nn);
					}
				}
			}
		}
		nodes.add(node);
		return false;
	}

	private static PrintWriter out;
	public static void main(String[] args){
		out = new PrintWriter(System.out);
		new Main().solve();
		out.flush();
	}

	public static int nextInt(){
		int num = 0;
		String str = next();
		boolean minus = false;
		int i = 0;
		if(str.charAt(0) == '-'){
			minus = true;
			i++;
		}
		int len = str.length();
		for(;i < len; i++){
			char c = str.charAt(i);
			if(!('0' <= c && c <= '9')) throw new RuntimeException();
			num = num * 10 + (c - '0');
		}
		return minus ? -num : num;
	}

	public static long nextLong(){
		long num = 0;
		String str = next();
		boolean minus = false;
		int i = 0;
		if(str.charAt(0) == '-'){
			minus = true;
			i++;
		}
		int len = str.length();
		for(;i < len; i++){
			char c = str.charAt(i);
			if(!('0' <= c && c <= '9')) throw new RuntimeException();
