public class Main {

	static final char[] COLOR = { 'R', 'Y', 'G', 'B' };

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int h = sc.nextInt();
		int w = sc.nextInt();
		int d = sc.nextInt();

		int[][] color = new int[h][w];
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				color[i][j] = (1 << 3) + (1 << 2) + (1 << 1) + 1;
			}
		}

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				for (int k = 0; k < 4; k++) {
					if (((color[i][j] >> k) & 1) == 1) {
						color[i][j] = 1 << k;
						break;
					}
				}

				int jj = j - d;
				int ii = i;
				for (int k = 0; k < d; k++) {
					ii++;
					jj++;
					if ((0 <= ii && ii < h) && (0 <= jj && jj < w)) {
						color[ii][jj] &= ~color[i][j];
					}
				}
				for (int k = 0; k < d; k++) {
					ii--;
					jj++;
					if ((0 <= ii && ii < h) && (0 <= jj && jj < w)) {
						color[ii][jj] &= ~color[i][j];
					}
				}
			}
		}

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				for (int k = 0; k < 4; k++) {
					if (((color[i][j] >> k) & 1) == 1) {
						out.print(COLOR[k]);
						break;
					}
				}
			}
			out.println();
		}

		out.flush();
	}

}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
