class Block {
	boolean[][] c;
	int w;
	int h;
	int dx;
	int dy;
	int offx;
	int offy;

	Block(int d) {
		if (d % 2 == 0) {
			w = d;
			h = d - 1;
			this.c = new boolean[h][w];
			int cy = d / 2 - 1;
			int cx1 = d / 2 - 1;
			int cx2 = d / 2;
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (abs(cx1 - j) + abs(cy - i) < d / 2)
						this.c[i][j] = true;
					if (abs(cx2 - j) + abs(cy - i) < d / 2)
						this.c[i][j] = true;
				}
			}

			dx = w;
			dy = 0;

			offx = d / 2;
			offy = d / 2;
		} else {
			w = d;
			h = d;
			this.c = new boolean[h][w];
			int c = d - 1 >> 1;
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (abs(c - j) + abs(c - i) < (d + 1) / 2)
						this.c[i][j] = true;
				}
			}

			dx = d + 1 >> 1;
			dy = d - 1 >> 1;

			offx = dy;
			offy = dx;
		}
	}

	int abs(int a) {
		return a < 0 ? -a : a;
	}

	void dump() {
		for (int i = 0; i < h; i++) {
			String s = "";
			for (int j = 0; j < w; j++) {
				if (c[i][j])
					s += "*";
				else
					s += " ";
			}
			System.out.println(s);
		}
	}
}

class Field {
	int[][] c;
	int w, h;

	Field(int w, int h) {
		c = new int[h][w];
		this.w = w;
		this.h = h;
	}

	void put(Block b, int x, int y, int color) {
		for (int i = 0; i < b.h; i++) {
			for (int j = 0; j < b.w; j++) {
				int px = j + x;
				int py = i + y;
				if (px < 0 || py < 0 || px >= w || py >= h)
					continue;
				if (!b.c[i][j])
					continue;
				if (c[py][px] != 0)
					throw new Error("は？");
				c[py][px] = color;
			}
		}
	}

	void dump() {
		boolean ng = false;
		for (int i = 0; i < h; i++) {
			String s = "";
			for (int j = 0; j < w; j++) {
				s += "RGBY".charAt(c[i][j] - 1);
				if (c[i][j] == 0)
					ng = true;
			}
			System.out.println(s);
		}
		if (ng)
			throw new Error("は？");
	}
}

