/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            int d = in.nextInt();

            String color = "RYGB";

            if (d % 2 == 1) {
                for (int i = 0; i < h; i++) {
                    for (int j = 0; j < w; j++) {
                        out.print(color.charAt((i + j) % 2));
                    }
                    out.println();
                }
                return;
            }

            int half = d / 2;

            char[][] ans = new char[h + d][w + d];
            for (int i = 0; i * half < h + d; i++) {
                for (int j = 0; j * half < w + d; j++) {
                    if ((i + j) % 2 == 0) {
                        int c = 0;
                        if (i % 2 == 0) c += 2;
                        if ((i + j) / 2 % 2 == 0) c++;

                        int y = i * half;
                        int x = j * half;

                        for (int k = -(half - 1); k <= half - 1; k++) {
                            for (int l = -(half - 1 - Math.abs(k)); l <= half - Math.abs(k); l++) {
                                if (RangeUtils.isInside(y + k, x + l, h + d, w + d)) {
                                    ans[y + k][x + l] = color.charAt(c);
                                }
                            }
                        }
                    }
                }
            }

            for (int i = 0; i * (d - 1) + half < h; i++) {
                ans[i * (d - 1) + half][0] = color.charAt(1 - i % 2);
            }

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    out.print(ans[i][j]);
                }
                out.println();
            }
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class RangeUtils {
        public static boolean isInside(int y, int x, int h, int w) {
            return y >= 0 && x >= 0 && y < h && x < w;
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
    Scanner sc = new Scanner(System.in);

    public static final void main(String[] args) {
        new Main().solve();
    }

    void solve() {
        final int h = sc.nextInt();
        final int w = sc.nextInt();
        final int d = sc.nextInt();
        int[][] mat = new int[h][w];
        for (int i = 0; i < h; i++) Arrays.fill(mat[i], -1);
        ArrayList<Integer> xl = new ArrayList<>();
        ArrayList<Integer> yl = new ArrayList<>();
        xl.add(0); yl.add(-d);
        xl.add(-d); yl.add(0);
        for (int i = 1; i <= d; i++) {
            xl.add(i); yl.add(-d+i);
            xl.add(-i); yl.add(-d+i);
        }

        char[] colors = new char[] {'R', 'G', 'B', 'Y'};
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                boolean[] check = new boolean[4];
                for (int k = 0; k < xl.size(); k++) {
                    int x = j + xl.get(k);
                    int y = i + yl.get(k);
                    if (x < 0 || x >= w || y < 0 || y >= h || mat[y][x] == -1) continue;
                    check[mat[y][x]] = true;
                }
                for (int k = 0; k < 4; k++) {
                    if (!check[k]) {
                        mat[i][j] = k;
                        sb.append(colors[k]);
                        break;
                    }
                }
            }
            sb.append("\n");
        }
        System.out.println(sb.toString());
    }
}

