						mat[i1+i2][j1+j2]=j1%(2*d+2)==0?'R':'Y';
				for(int i2=d; i2<2*d&&i1+i2<h; ++i2)
					for(int j2=0; j2<2*d-i2&&j1+j2<w; ++j2)
						mat[i1+i2][j1+j2]=j1%(2*d+2)==0?'Y':'R';
				for(int i2=0; i2<d&&i1+i2<h; ++i2)
