public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    void solve() {
        final int h = ni(), w = ni(), d = ni();
        char c[] = {'R', 'Y', 'G', 'B'};
        int bit[][] = new int[h][w];
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                bit[i][j] = (1 << 4) - 1;
            }
        }
        boolean ok[][] = new boolean[h][w];
        class T {
            int queue[] = new int[h * w], qi, qs;

            void calc(int i, int j) {
                qi = 0;
                qs = 1;
                queue[0] = (i << 16) + j;
                while (qi < qs) {
                    int p = queue[qi++];
                    int a = p >> 16;
                    int b = p & ((1 << 16) - 1);
                    dfs(a, b);
                }
            }

            void dfs(int a, int b) {
                if (!in(a, b)) return;
                if (ok[a][b]) return;
                ok[a][b] = true;
                int x = 0;
                while ((bit[a][b] & (1 << x)) == 0) ++x;
                bit[a][b] = 1 << x;
                for (int k = 0; k <= d; ++k) {
                    remove(a + k, b + d - k, x);
                    remove(a - k, b + d - k, x);
                    remove(a + k, b - d + k, x);
                    remove(a - k, b - d + k, x);
                }
            }

            void remove(int a, int b, int x) {
                if (in(a, b) && !ok[a][b]) {
                    bit[a][b] &= ~(1 << x);
                    if (Integer.bitCount(bit[a][b]) == 1) {
                        ok[a][b] = true;
                        queue[qs++] = (a << 16) + b;
                    }
                }
            }

            boolean in(int a, int b) {
                return 0 <= a && a < h && 0 <= b && b < w;
            }
        }
        T t = new T();
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (bit[i][j] == 0) throw new RuntimeException();
                t.calc(i, j);
            }
        }
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (bit[i][j] == 0) throw new RuntimeException();
                int x = 0;
                while ((bit[i][j] & (1 << x)) == 0) ++x;
                out.print(c[x]);
            }
            out.println();
        }
    }

