        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                bool b = (i+j) / D % 2 == 0;
                bool c = (i-j+W) / D % 2 == 0;
                if(b && c){
                    sb.Append('R');
                }
                else if(b && !c){
                    sb.Append('G');
                }
                else if(!b && c){
                    sb.Append('Y');
                }
                else{
                    sb.Append('B');
                }
            }
            sb.Append('\n');
        }
    }
}
