class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int H = re.i();
        int W = re.i();
        int D = re.i();
        int B = (D+1) / 2;
        int[,] block = new int[4,4];
        block[0,0] = 0;
        block[0,1] = 1;
        block[0,2] = 2;
        block[0,3] = 3;
        block[1,0] = 2;
        block[1,1] = 3;
        block[1,2] = 0;
        block[1,3] = 1;
        block[2,0] = 1;
        block[2,1] = 0;
        block[2,2] = 3;
        block[2,3] = 2;
        block[3,0] = 3;
        block[3,1] = 2;
        block[3,2] = 1;
        block[3,3] = 0;
        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                int c = block[i/B%4,j/B%4];
                if(c == 0){
                    sb.Append('R');
                }
                else if(c == 1){
                    sb.Append('G');
                }
                else if(c == 2){
                    sb.Append('Y');
                }
                else{
                    sb.Append('B');
                }
            }
            sb.Append('\n');
        }
    }
}
