proc placeDiamond(a: var seq2[char]; h, w, y, x, r: int; c: char) =
  for dy in (-r + 1)..(r - 1):
    for dx in (-r + 1)..(r - 1):
      let nextY = dy + y
      let nextX = dx + x
      if nextY in 0..<h and nextX in 0..<w and abs(dy) + abs(dx) < r:
        a[nextY][nextX] = c

