import sys
class wall:
    def __init__(self, H, W, d):
        self.table = [[grid() for _ in xrange(W)] for _ in xrange(H)]
        self.h = H
        self.w = W
        self.d = d
    def paint(self, strategy = 1):
        if strategy == 1:
            status = self.paint_1()
            return self.draw()#
    def paint_1(self):
        for i in xrange(self.h):
            for j in xrange(self.w):
                thisgrid = self.table[i][j]
                if not thisgrid:
                    return False
                thisgrid.paint()
                status = self.note(i,j, thisgrid.color)
                if not status:
                    return False
        return True
    def note(self, i, j, c):
        def valid(ii, jj):
            return ii >= 0 and ii< self.h and jj>= 0 and jj< self.w
        status = True
        for dd in xrange(self.d+1):
            dd_ = self.d - dd
            # x+ y+
            ii = i + dd
            jj = j + dd_
            if valid(ii, jj):
                g = self.table[ii][jj]
                status = status and g.note(c)
            # x- y+
            ii = i - dd
            jj = j + dd_
            if valid(ii, jj):
                g = self.table[ii][jj]
                status = status and g.note(c)
            # x+ y-
            ii = i + dd
            jj = j - dd_
            if valid(ii, jj):
                g = self.table[ii][jj]
                status = status and g.note(c)
            # x- y-
            ii = i - dd
            jj = j - dd_
            if valid(ii, jj):
                g = self.table[ii][jj]
                status = status and g.note(c)
        return status
    def draw(self):
        res = ''
        for i in xrange(self.h):
            for j in xrange(self.w):
                res = res + (self.table[i][j].color if
                self.table[i][j].colored() else '0')
            res = res + '\n'
        return res
    def draw_note(self):
        res = ''
        for i in xrange(self.h):
            for j in xrange(self.w):
                res = res + '(' + self.table[i][j].noteStr() + ')'
            res = res + '\n'
        return res
class grid:
    def __init__(self):
        self.colors = ['R','Y','G','B']
        self.color = None
    def noteStr(self):
        return ''.join(self.colors)
    def note(self,c):
        if c in self.colors:
            self.colors.remove(c)
        if self.color and self.color == c:
            return False
        return True
    def __bool__(self):
        return bool(self.colors)
    def paint(self):
        if self.colors:
            self.color = self.colors[0]
            return True
        else:
            return False
    def colored(self):
        return self.color != None
