from collections import deque

def II(): return int(input())
def ILI(): return list(map(int, input().split()))


def read():
    H, W, d = ILI()
    return H, W, d


def solve(H, W, d):
    nei_board = [None] * (H * W)
    for h in range(H):
        for w in range(W):
            now = h * W + w
            set_nei = set()
            for i in range(-d, d + 1):
                nei = now + (i * W) + (d - abs(i))
                ano_nei = now + (i * W) - (d - abs(i))
                if 0 <= nei <= H * W - 1:
                    set_nei.add(nei)
                if 0 <= ano_nei <= H * W - 1:
                    set_nei.add(ano_nei)
            nei_board[now] = list(set_nei)

    ans_board = [0] * (H * W)

    def check_same_color(now, color):
        for nei in nei_board[now]:
            if ans_board[nei] == color:
                return False
        return True

    def DFS(node):
        ans_board[node] = 1
        queue = deque(nei_board[node])
        while len(queue) != 0:
            now = deque.pop(queue)
            for c in range(1, 5):
                if check_same_color(now, c):
                    ans_board[now] = c
                    break
            for nei in nei_board[now]:
                if ans_board[nei] == 0:
                    deque.appendleft(queue, nei)

    while True:
        b = True
        for i in range(H * W):
            if ans_board[i] == 0:
                b = False
                DFS(i)
                break
        if b:
            break

    color = ["R", "Y", "G", "B"]
    for i in range(0, H * W, H):
        ans = ""
        for j in range(i, i + W):
            ans += color[ans_board[j]]
        print(ans)


