A = [[None] * H for _ in range(W)]

def iter_d(x, y):
    for i in range(0, min(d, x) + 1):
        xx = x - i
        yy = y - (d - i)
        if yy >= 0:
            yield xx, yy
        yy = y + (d - i)
        if yy < H and d > i:
            yield xx, yy
    for i in range(1, min(d, W - x - 1) + 1):
        xx = x + i
        yy = y - (d - i)
        if yy >= 1:
            yield xx, yy
        yy = y + (d - i)
        if yy < H and d > i:
            yield xx, yy


