    let t = cmp::max(h, w) * 3 / d;
    let mut cur_si = -(cmp::max(h, w) as i64) - 1;
    let mut cur_sj = cur_si;
    let mut base_color = 0;
    for _ in 0..t {
        let d = d as i64;
        cur_si -= d - 1;
        cur_sj += d;
        if cur_si + d <= 0 {
            cur_si += d;
            cur_sj += d - 1;
        }
        let mut cur_i = cur_si;
        let mut cur_j = cur_sj;
        let mut tmp_color = 0;
        for _ in 0..t {
            let color = base_color * 2 + tmp_color;
            centers.push((cur_i, cur_j, color));
            cur_i += d;
            cur_j += d - 1;
            tmp_color = tmp_color ^ 1;
        }
        base_color = base_color ^ 1;
    }

    // println!("{:?}", centers);

    let mut ans = vec![vec![0; w]; h];
    for &(i, j, color) in centers.iter() {
        let tmp: Vec<i64> = vec![-1, 1];
        let d = d as i64;
        for dd in 0..d {
            for &t1 in tmp.iter() {
                for &t2 in tmp.iter() {
                    let h = h as i64;
                    let w = w as i64;
                    let i = i + t1 * ((d - 1) - dd);
                    let j = j + t2 * dd;
                    if i >= 0 && j >= 0 && i < h && j < w {
                        ans[i as usize][j as usize] = color;
                    }
                }
            }
        }
    }

    // println!("{:?}", ans);

    let c: Vec<char> = vec!['R', 'Y', 'B', 'G'];

    for i in 0..h {
        for j in 0..w {
            print!("{}", c[ans[i][j]]);
        }
        println!();
    }
}

